#!/usr/bin/env python3
"""OrangeBox Wazuh - reporte de seguridad unificado v4.

Un solo motor/cache genera dos vistas del mismo período:
- resumen ejecutivo HTML en el cuerpo del correo;
- reporte detallado HTML dentro de un ZIP adjunto.

El cache v3 se actualiza una sola vez y los dos reportes consumen una sola
pasada de los shards seleccionados. El antiguo script detallado queda como
compatibilidad, pero ya no contiene motor ni genera un segundo reporte.
"""

from __future__ import annotations

import argparse
import importlib.util
import ipaddress
import os
import re
import shutil
import smtplib
import subprocess
import sys
import time
import types
import zipfile
from collections import Counter, defaultdict
from datetime import datetime, timedelta
from email.mime.application import MIMEApplication
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from pathlib import Path

sys.dont_write_bytecode = True

# El motor y los renderers se embeben para que el reporte sea autocontenido
# y pueda desplegarse como un único archivo.
ENGINE_SOURCE = "#!/usr/bin/env python3\n\"\"\"OrangeBox Wazuh - motor de reportes v3.\n\nObjetivo:\n- leer alerts.json/archivos diarios una sola vez;\n- normalizar eventos una sola vez;\n- guardar parciales e históricos comprimidos por servidor;\n- permitir lectura selectiva por servidor para reporte normal y detallado;\n- no importar ni ejecutar los reportes productivos.\n\nEl motor queda aislado de /var/ossec/reports/*.py. Las funciones de\nclasificación y parseo necesarias para reproducir el resultado actual están\ncontenidas aquí.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport gzip\nimport hashlib\nimport ipaddress\nimport json\nimport os\nimport re\nimport tempfile\nimport time\nimport shutil\ntry:\n    import orjson\nexcept ImportError:\n    orjson = None\nfrom collections import Counter, defaultdict\nfrom datetime import date, datetime, timedelta\nfrom pathlib import Path\n\nALERTS_ROOT = Path(\"/var/ossec/logs/alerts\")\nALERTS_FILE = ALERTS_ROOT / \"alerts.json\"\nDEFAULT_CACHE = Path(\"/var/ossec/reports/cache-proto-v3\")\nFIREWALL_RULE = \"10458\"\nFIREWALL_RE = re.compile(r\"active-response/bin/firewall-drop:\\s*(\\{.*\\})$\")\n\nAUTH_RULES = {\"5710\",\"5712\",\"5715\",\"5716\",\"5720\",\"5760\",\"5763\",\"10001\",\"10006\",\"10007\",\"10008\",\"10009\",\"40101\"}\nWEB_RULES = {\"31101\",\"10023\",\"10024\",\"10025\",\"10026\"}\nFIM_RULES = {\"550\",\"553\",\"554\",\"10060\",\"10062\",\"10063\",\"10410\",\"10432\"}\nMALWARE_RULES = {\"10060\",\"10062\",\"10063\",\"10410\",\"10432\"}\nPRIV_RULES = {\"10004\",\"10005\",\"5402\",\"5403\",\"10032\"}\nAUTH_GROUPS = {\"authentication\",\"authentication_success\",\"authentication_failed\"}\nWEB_GROUPS = {\"web\",\"orangebox_web\"}\nFIM_GROUPS = {\"syscheck\",\"syscheck_entry_added\",\"syscheck_entry_modified\",\"syscheck_entry_deleted\",\"orangebox_temporary_executable\"}\nMALWARE_GROUPS = {\"malware\",\"webshell\",\"orangebox_malware\",\"orangebox_webshell\"}\nATTACK_GROUPS = {\"attack\",\"brute_force\",\"reconnaissance\",\"credential_discovery\",\"sensitive_file\",\"lateral_movement\"}\nREPORT_EXCLUDED_GROUPS = {\"orangebox_exception\",\"orangebox_whitelist\"}\nREPORT_EXCLUDED_RULES = {\"5402\"}\n\nCANONICAL = {\n \"5710\":\"SSH: Intento de acceso con usuario inexistente.\", \"5712\":\"SSH: Fuerza bruta intentando acceder al sistema con usuario inexistente.\",\n \"5715\":\"SSH: Inicio de sesión exitoso.\", \"5760\":\"SSH: Autenticación fallida.\", \"5763\":\"SSH: Fuerza bruta intentando acceder al sistema con autenticación fallida.\",\n \"5758\":\"SSH: Se superó el máximo de intentos de autenticación.\", \"10001\":\"SSH: Inicio de sesión SSH exitoso.\", \"10006\":\"SSH: Fuerza bruta completada con éxito.\",\n \"10007\":\"SSH: Posible movimiento lateral desde la red interna.\", \"40101\":\"ACCESO: Sesión de usuario iniciada.\", \"5501\":\"ACCESO: Sesión PAM de usuario abierta.\",\n \"5503\":\"ACCESO: Fallo de autenticación de usuario PAM.\", \"2501\":\"ACCESO: Fallo de autenticación de usuario.\", \"2502\":\"ACCESO: Contraseña incorrecta en múltiples intentos.\",\n \"3332\":\"ACCESO: Fallo de autenticación SASL de Postfix.\", \"10004\":\"PRIVILEGIOS: Usuario cambió de sesión a ROOT mediante comando SU.\",\n \"10005\":\"PRIVILEGIOS: SUDO hacia ROOT con comando no autorizado por la whitelist OrangeBox.\", \"5402\":\"PRIVILEGIOS: SUDO hacia ROOT ejecutado.\",\n \"5403\":\"PRIVILEGIOS: Primera ejecución de SUDO por el usuario.\", \"10032\":\"PRIVILEGIOS: Configuración de SUDO modificada.\",\n \"550\":\"ARCHIVOS: Integridad de archivo modificada.\", \"553\":\"ARCHIVOS: Archivo eliminado.\", \"554\":\"ARCHIVOS: Archivo agregado al sistema.\",\n \"517\":\"ARCHIVOS: Directorio monitorizado eliminado.\", \"560\":\"ARCHIVOS: Cola de FIM en tiempo real llena.\", \"231\":\"ARCHIVOS: Límite de archivos monitorizados próximo a alcanzarse.\",\n \"10060\":\"MALWARE: Script SHELL creado en directorio temporal.\", \"10062\":\"MALWARE: Posible WebShell PHP creado.\", \"10063\":\"MALWARE: Posible WebShell PHP modificado.\",\n \"10410\":\"MALWARE: Archivo ejecutable creado en directorio temporal.\", \"10432\":\"MALWARE: Permiso de ejecución agregado a archivo en directorio temporal.\",\n \"10023\":\"WEB: Reconocimiento o acceso a recurso sensible detectado.\", \"10024\":\"WEB: HTTP 401/403 detectado contra servidor web.\", \"10025\":\"WEB: Posible fuerza bruta web.\",\n \"10026\":\"WEB: Posible reconocimiento automatizado de archivos sensibles o credenciales web.\", \"31101\":\"WEB: Código de error 400 del servidor web.\",\n \"31516\":\"WEB: Acceso a URL sospechosa.\", \"31533\":\"WEB: Alta cantidad de solicitudes POST en un período corto.\",\n \"31509\":\"WEB: Intento de acceso de login de CMS.\", \"31151\":\"WEB: Múltiples errores 400 desde la misma IP de origen.\",\n \"30306\":\"WEB: Intento de acceso a índice de directorio prohibido.\", \"30318\":\"WEB: Aviso PHP detectado en log de Apache.\",\n \"31515\":\"WEB: Escaneo de PHPMyAdmin detectado.\", \"31104\":\"WEB: Ataque web común detectado.\",\n \"30305\":\"WEB: Intento de acceso a archivo o directorio prohibido.\", \"31510\":\"WEB: Fuerza bruta contra CMS detectada.\",\n \"31106\":\"WEB: Ataque web que devolvió código HTTP 200.\",\n \"10453\":\"RED: Posible escaneo de puertos TCP desde la misma IP de origen.\", \"10454\":\"RED: Posible inundación TCP SYN desde la misma IP de origen.\", \"10456\":\"ESCANEO DE PUERTOS\", \"10457\":\"SYN FLOOD\",\n \"10455\":\"RED: Posible ataque de denegación de servicio distribuido.\", \"10034\":\"CONFIGURACIÓN: Unidad o configuración persistente de SYSTEMD modificada.\",\n \"10035\":\"CONFIGURACIÓN: Configuración de CRON o ANACRON modificada.\", \"10036\":\"RED: Configuración crítica de red, DNS o montaje modificada.\",\n \"10037\":\"CONFIGURACIÓN: Configuración de FIREWALL modificada.\", \"10044\":\"CONFIGURACIÓN: Unidad o configuración persistente de SYSTEMD eliminada.\",\n \"100311\":\"ENDPOINT: Nuevo puerto de red detectado en el endpoint.\", \"100313\":\"ENDPOINT: Nuevo servicio detectado en el endpoint.\",\n}\n\n\ndef parse_timestamp(value):\n    if not value:\n        return None\n    try:\n        value = re.sub(r\"([+-]\\d{2})(\\d{2})$\", r\"\\1:\\2\", str(value))\n        return datetime.fromisoformat(value)\n    except (TypeError, ValueError):\n        return None\n\n\ndef valid_ip(value):\n    try:\n        ipaddress.ip_address(value)\n        return True\n    except (ValueError, TypeError):\n        return False\n\n\ndef standardize(rule_id, description, groups=None):\n    rid = str(rule_id)\n    if rid in CANONICAL:\n        return CANONICAL[rid]\n    text = re.sub(r\"^(?:ALERTA(?:\\s+CRITICA)?|ORANGEBOX(?:\\s+TEST)?)\\s*:\\s*\", \"\", str(description or \"Sin descripción\"), flags=re.I)\n    text = re.sub(r\"\\s+\", \" \", text).strip()\n    gs = {str(v).lower() for v in (groups or [])}\n    if rid in MALWARE_RULES or gs & MALWARE_GROUPS: prefix = \"MALWARE\"\n    elif rid in PRIV_RULES or gs & {\"privilege_escalation\",\"privilege_escalation_root\",\"sudo\"}: prefix = \"PRIVILEGIOS\"\n    elif rid in WEB_RULES or gs & WEB_GROUPS: prefix = \"WEB\"\n    elif rid in FIM_RULES or gs & FIM_GROUPS: prefix = \"ARCHIVOS\"\n    elif rid in AUTH_RULES or gs & AUTH_GROUPS: prefix = \"SSH\" if \"ssh\" in gs else \"ACCESO\"\n    elif gs & ATTACK_GROUPS: prefix = \"ATAQUE\"\n    else: return text or \"Sin descripción\"\n    return text if re.match(rf\"^{re.escape(prefix)}\\s*:\", text, re.I) else f\"{prefix}: {text}\"\n\n\ndef classify(rule_id, groups, level):\n    rid = str(rule_id); gs = {str(v).lower() for v in (groups or [])}\n    if rid == FIREWALL_RULE: return \"active_response\"\n    if rid in MALWARE_RULES or gs & MALWARE_GROUPS: return \"malware\"\n    if rid in PRIV_RULES or gs & {\"privilege_escalation\",\"privilege_escalation_root\",\"sudo\"}: return \"privilege\"\n    if rid in WEB_RULES or gs & WEB_GROUPS: return \"web\"\n    if rid in FIM_RULES or gs & FIM_GROUPS: return \"fim\"\n    if rid in AUTH_RULES or gs & AUTH_GROUPS: return \"authentication\"\n    if gs & ATTACK_GROUPS or int(level or 0) >= 12: return \"attack\"\n    return \"other\"\n\n\ndef exempt(event):\n    gs = {str(v).lower() for v in (event.get(\"groups\") or [])}\n    try: level = int(event.get(\"level\",0) or 0)\n    except (TypeError, ValueError): level = 0\n    return level <= 0 or str(event.get(\"rule_id\",\"\")) in REPORT_EXCLUDED_RULES or bool(gs & REPORT_EXCLUDED_GROUPS)\n\n\ndef firewall_payload(full_log):\n    if not isinstance(full_log, str): return None\n    m = FIREWALL_RE.search(full_log.strip())\n    if not m: return None\n    try: return json.loads(m.group(1))\n    except json.JSONDecodeError: return None\n\n\ndef parse_event(outer):\n    rule = outer.get(\"rule\") or {}; rid = str(rule.get(\"id\",\"\")); ts = parse_timestamp(outer.get(\"timestamp\"))\n    if not ts: return None\n    if rid == FIREWALL_RULE:\n        data = outer.get(\"data\") or {}; params = data.get(\"parameters\") or {}; command = data.get(\"command\") or params.get(\"command\")\n        payload = firewall_payload(outer.get(\"full_log\",\"\"))\n        if isinstance(payload, dict):\n            if command not in {\"add\",\"delete\"}: command = payload.get(\"command\") or params.get(\"command\")\n            raw = payload.get(\"parameters\") or {}\n            if raw:\n                merged = dict(raw); merged.update(params); params = merged\n        if command not in {\"add\",\"delete\"}: return None\n        alert = params.get(\"alert\") or {}\n        if not alert and isinstance(payload,dict): alert=(payload.get(\"parameters\") or {}).get(\"alert\") or {}\n        arule = alert.get(\"rule\") or {}; agent = alert.get(\"agent\") or {}; adata = alert.get(\"data\") or {}\n        src = adata.get(\"srcip\") or data.get(\"srcip\") or alert.get(\"srcip\")\n        if not src and isinstance(payload,dict):\n            pa=(payload.get(\"parameters\") or {}).get(\"alert\") or {}; src=(pa.get(\"data\") or {}).get(\"srcip\")\n        mitre = arule.get(\"mitre\") or {}\n        return {\"timestamp\":parse_timestamp(alert.get(\"timestamp\")) or ts,\"outer_rule\":rid,\"rule_id\":str(arule.get(\"id\",\"unknown\")),\n                \"description\":standardize(arule.get(\"id\",\"unknown\"),arule.get(\"description\",\"Firewall Drop\"),arule.get(\"groups\") or []),\n                \"level\":int(arule.get(\"level\",0) or 0),\"groups\":arule.get(\"groups\") or [],\"agent_id\":str(agent.get(\"id\",\"000\")),\n                \"agent_name\":agent.get(\"name\",\"unknown\"),\"srcip\":str(src) if valid_ip(src) else None,\"command\":command,\n                \"alert_id\":str(alert.get(\"id\",outer.get(\"id\",\"\"))),\"mitre\":mitre.get(\"id\",[]),\"techniques\":mitre.get(\"technique\",[]),\"url\":adata.get(\"url\"),\"fim_path\":\"\"}\n    agent=outer.get(\"agent\") or {}; data=outer.get(\"data\") or {}; mitre=rule.get(\"mitre\") or {}; syscheck=outer.get(\"syscheck\") or data.get(\"syscheck\") or {}\n    return {\"timestamp\":ts,\"outer_rule\":rid,\"rule_id\":rid,\"description\":standardize(rid,rule.get(\"description\",\"Sin descripción\"),rule.get(\"groups\") or []),\n            \"level\":int(rule.get(\"level\",0) or 0),\"groups\":rule.get(\"groups\") or [],\"agent_id\":str(agent.get(\"id\",\"000\")),\n            \"agent_name\":agent.get(\"name\",\"unknown\"),\"srcip\":str(data.get(\"srcip\")) if valid_ip(data.get(\"srcip\")) else None,\"command\":None,\n            \"alert_id\":str(outer.get(\"id\",\"\")),\"mitre\":mitre.get(\"id\",[]),\"techniques\":mitre.get(\"technique\",[]),\"url\":data.get(\"url\"),\n            \"fim_path\":str(data.get(\"path\") or syscheck.get(\"path\") or \"\").strip()}\n\n\ndef json_loader(handle, strict=False):\n    # orjson acelera el parseo masivo si está instalado, pero no es requisito.\n    try:\n        import orjson\n        loads = orjson.loads\n    except ImportError:\n        loads = json.loads\n    for lineno,raw in enumerate(handle,1):\n        if not raw.strip():\n            continue\n        try:\n            obj=loads(raw)\n            if isinstance(obj,dict):\n                yield obj\n            elif strict:\n                raise ValueError(\"La línea JSON no contiene un objeto.\")\n        except (ValueError, TypeError, UnicodeDecodeError) as exc:\n            if strict:\n                raise ValueError(f\"JSON inválido en línea {lineno}: {exc}\") from exc\n            continue\n\n\ndef day_sources(day):\n    base=ALERTS_ROOT/f\"{day.year:04d}\"/day.strftime(\"%b\")\n    gz=base/f\"ossec-alerts-{day.day:02d}.json.gz\"\n    plain=base/f\"ossec-alerts-{day.day:02d}.json\"\n    # El .gz es el log rotado/finalizado. Si existe, es la única fuente válida.\n    if gz.exists():\n        return [gz]\n    # El .json es el log operativo: jamás se considera cerrado ni se elimina.\n    return [plain] if plain.exists() else []\n\ndef day_source(day):\n    sources=day_sources(day)\n    return sources[0] if sources else None\n\n\ndef day_dir(cache_dir, day): return cache_dir/day.isoformat()\ndef cache_path(cache_dir, day, agent_id): return day_dir(cache_dir,day)/f\"{re.sub(r'[^A-Za-z0-9_.-]+','_',str(agent_id or '000'))}.jsonl.gz\"\ndef state_path(cache_dir, day): return cache_dir/f\"{day.isoformat()}.state.json\"\ndef manifest_path(cache_dir, day): return day_dir(cache_dir,day)/\"manifest.json\"\n\n\ndef load_state(path):\n    try: return json.loads(path.read_text(encoding=\"utf-8\")) if path.exists() else {}\n    except (OSError, ValueError): return {}\n\n\ndef load_manifest(path):\n    try: return json.loads(path.read_text(encoding=\"utf-8\")) if path.exists() else {}\n    except (OSError, ValueError): return {}\n\n\ndef atomic_json(path, obj):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    fd,tmp=tempfile.mkstemp(prefix=path.name+\".\",dir=path.parent); os.close(fd)\n    try:\n        Path(tmp).write_text(json.dumps(obj,ensure_ascii=False,separators=(\",\",\":\")),encoding=\"utf-8\"); os.replace(tmp,path)\n    finally:\n        try: os.unlink(tmp)\n        except FileNotFoundError: pass\n\n\ndef cache_day_files(cache_dir, day):\n    d=day_dir(cache_dir,day)\n    if not d.exists():\n        return []\n    return sorted(p for p in d.glob(\"*.jsonl.gz\") if p.is_file())\n\n\ndef cache_day_complete(cache_dir, day):\n    \"\"\"True solo cuando un día cerrado fue cacheado completamente.\"\"\"\n    st=load_state(state_path(cache_dir,day))\n    manifest=load_manifest(manifest_path(cache_dir,day))\n    if not st or not manifest:\n        return False\n    if int(st.get(\"version\",0) or 0)!=4 or not bool(st.get(\"closed\")):\n        return False\n    if int(manifest.get(\"version\",0) or 0)!=4:\n        return False\n    if manifest.get(\"day\")!=day.isoformat():\n        return False\n    try:\n        state_events=int(st.get(\"events\",0) or 0)\n        manifest_events=int(manifest.get(\"events\",0) or 0)\n    except (TypeError,ValueError):\n        return False\n    if state_events!=manifest_events:\n        return False\n    agents=manifest.get(\"agents\") or {}\n    for agent_id,item in agents.items():\n        if int(item.get(\"events\",0) or 0)<=0:\n            continue\n        path=cache_path(cache_dir,day,agent_id)\n        if not path.is_file():\n            return False\n        try:\n            if path.stat().st_size<=0:\n                return False\n        except OSError:\n            return False\n    return True\n\n\ndef cache_day_available(cache_dir, day):\n    \"\"\"True si existe cualquier representación usable del cache del día.\"\"\"\n    if state_path(cache_dir,day).is_file() or manifest_path(cache_dir,day).is_file():\n        return True\n    return bool(cache_day_files(cache_dir,day))\n\n\ndef purge_day_sources(day):\n    \"\"\"Elimina únicamente el .gz rotado; nunca toca el .json operativo.\"\"\"\n    removed=0\n    errors=[]\n    for source in day_sources(day):\n        if source.suffix != \".gz\":\n            continue\n        try:\n            source.unlink()\n            removed += 1\n        except FileNotFoundError:\n            pass\n        except OSError as exc:\n            errors.append(f\"{source}: {exc}\")\n    return removed,errors\n\ndef normalize_stream_sharded(src, writer_for_agent, start, end, counters, seen=None, manifest_agents=None, strict_json=False):\n    seen = seen if seen is not None else set()\n    for outer in json_loader(src, strict=strict_json):\n        event=parse_event(outer)\n        if not event: continue\n        ts=event.get(\"timestamp\")\n        if not ts or ts<start or ts>=end: continue\n        if event[\"outer_rule\"] != FIREWALL_RULE:\n            if exempt(event): continue\n            if event[\"rule_id\"]==\"40101\" and re.search(r\"pam_unix\\(systemd-user:session\\):\\s+session\\s+opened\",str(outer.get(\"full_log\",\"\")),re.I): continue\n        else:\n            if event.get(\"command\") != \"add\": continue\n        if event[\"outer_rule\"] != FIREWALL_RULE:\n            aid=event.get(\"alert_id\",\"\")\n            if aid and aid in seen: continue\n            if aid: seen.add(aid)\n        event[\"category\"]=classify(event[\"rule_id\"],event.get(\"groups\",[]),event.get(\"level\",0))\n        event[\"timestamp\"]=ts.isoformat()\n        agent_id=str(event.get(\"agent_id\",\"000\") or \"000\")\n        dst=writer_for_agent(agent_id)\n        dst.write(json.dumps(event,ensure_ascii=False,separators=(\",\",\":\"))+\"\\n\")\n        counters[\"events\"] += 1\n        if manifest_agents is not None:\n            item=manifest_agents.setdefault(agent_id,{\"events\":0,\"name\":str(event.get(\"agent_name\") or \"unknown\")})\n            item[\"events\"] += 1\n            item[\"name\"] = str(event.get(\"agent_name\") or item.get(\"name\") or \"unknown\")\n    return seen\n\n\ndef write_manifest(cache_dir, day, agents, total_events):\n    d=day_dir(cache_dir,day); d.mkdir(parents=True,exist_ok=True)\n    payload={\n        \"version\":4,\n        \"day\":day.isoformat(),\n        \"events\":int(total_events),\n        \"agents\":{\n            str(agent_id):{\n                \"name\":str(item.get(\"name\") or \"unknown\"),\n                \"events\":int(item.get(\"events\",0) or 0),\n                \"size\":int(item.get(\"size\",0) or 0),\n            }\n            for agent_id,item in agents.items()\n            if int(item.get(\"events\",0) or 0)>0 and cache_path(cache_dir,day,agent_id).exists()\n        },\n    }\n    atomic_json(manifest_path(cache_dir,day),payload)\n    return payload\n\n\ndef rebuild_day(cache_dir, day):\n    sources=day_sources(day)\n    if not sources: raise SystemExit(f\"No existe log de Wazuh para {day}\")\n    cache_dir.mkdir(parents=True,exist_ok=True)\n    final_dir=day_dir(cache_dir,day)\n    tmp_dir=Path(tempfile.mkdtemp(prefix=day.isoformat()+\".\",dir=cache_dir))\n    counters=Counter(); agents={}; writers={}; seen=set()\n    start=datetime.combine(day,datetime.min.time()).astimezone()\n    end=start+timedelta(days=1)\n\n    def writer_for_agent(agent_id):\n        aid=str(agent_id or \"000\")\n        handle=writers.get(aid)\n        if handle is None:\n            path=tmp_dir/f\"{re.sub(r'[^A-Za-z0-9_.-]+','_',aid)}.jsonl.gz\"\n            handle=gzip.open(path,\"wt\",encoding=\"utf-8\",compresslevel=6)\n            writers[aid]=handle\n        return handle\n\n    try:\n        for source in sources:\n            opener=gzip.open if source.suffix==\".gz\" else open\n            with opener(source,\"rt\",encoding=\"utf-8\",errors=\"replace\") as src:\n                seen=normalize_stream_sharded(src,writer_for_agent,start,end,counters,seen,agents,strict_json=True)\n        for handle in writers.values():\n            handle.close()\n        writers.clear()\n    except EOFError as exc:\n        for handle in writers.values():\n            try: handle.close()\n            except OSError: pass\n        writers.clear()\n        try: shutil.rmtree(tmp_dir)\n        except OSError: pass\n        bad_source=source if \"source\" in locals() else sources[0]\n        if bad_source.suffix==\".gz\":\n            raise SystemExit(\n                f\"Log de Wazuh truncado/corrupto: {bad_source}. \"\n                f\"No se genera cache para {day} para evitar resultados incompletos. \"\n                f\"Compruebe con: gzip -t {bad_source}\"\n            ) from exc\n        raise\n    except OSError as exc:\n        for handle in writers.values():\n            try: handle.close()\n            except OSError: pass\n        writers.clear()\n        try: shutil.rmtree(tmp_dir)\n        except OSError: pass\n        raise SystemExit(f\"No se pudo leer un log de {day}: {exc}\") from exc\n    except Exception:\n        for handle in writers.values():\n            try: handle.close()\n            except OSError: pass\n        writers.clear()\n        try: shutil.rmtree(tmp_dir)\n        except OSError: pass\n        raise\n\n    for aid in list(agents):\n        p=tmp_dir/f\"{re.sub(r'[^A-Za-z0-9_.-]+','_',str(aid or '000'))}.jsonl.gz\"\n        try: agents[aid][\"size\"]=p.stat().st_size\n        except OSError: agents[aid][\"size\"]=0\n\n    try:\n        if final_dir.exists():\n            shutil.rmtree(final_dir)\n        os.replace(tmp_dir,final_dir)\n    except OSError:\n        try: shutil.rmtree(tmp_dir)\n        except OSError: pass\n        raise\n\n    manifest=write_manifest(cache_dir,day,agents,counters[\"events\"])\n    source_meta=[{\"path\":str(p),\"size\":p.stat().st_size,\"mtime_ns\":p.stat().st_mtime_ns} for p in sources]\n    # Solo un .gz implica que Wazuh ya rotó/finalizó el día.\n    # Un .json es operativo y deja el cache en estado parcial.\n    closed=all(p.suffix==\".gz\" for p in sources)\n    atomic_json(state_path(cache_dir,day),{\n        \"version\":4,\n        \"day\":day.isoformat(),\n        \"closed\":closed,\n        \"sources\":source_meta,\n        \"events\":counters[\"events\"],\n        \"cache_size\":sum(item[\"size\"] for item in manifest[\"agents\"].values()),\n        \"agents\":len(manifest[\"agents\"]),\n    })\n\n    # El cache ya representa el día completo; solo el .gz rotado deja de ser necesario.\n    removed,errors=purge_day_sources(day)\n    for detail in errors:\n        print(f\"AVISO: no se pudo eliminar log cerrado {detail}\",flush=True)\n    if removed:\n        print(f\"Cache cerrado: {day.isoformat()} · logs eliminados: {removed}\",flush=True)\n\n    return counters[\"events\"]\n\n\ndef update_today(cache_dir):\n    day=datetime.now().astimezone().date()\n    source=ALERTS_FILE\n    if not source.exists(): raise SystemExit(f\"No existe {source}\")\n    cache_dir.mkdir(parents=True,exist_ok=True)\n    outdir=day_dir(cache_dir,day)\n    stfile=state_path(cache_dir,day)\n    st=load_state(stfile)\n    stat=source.stat()\n    manifest=load_manifest(manifest_path(cache_dir,day))\n    reset=(\n        st.get(\"inode\")!=stat.st_ino\n        or int(st.get(\"offset\",0) or 0)>stat.st_size\n        or not outdir.exists()\n        or int(manifest.get(\"version\",0) or 0)!=4\n    )\n    if reset:\n        shutil.rmtree(outdir,ignore_errors=True)\n        outdir.mkdir(parents=True,exist_ok=True)\n        offset=0\n        total=0\n        agents={}\n        seen=set()\n    else:\n        offset=int(st.get(\"offset\",0) or 0)\n        total=int(st.get(\"events\",0) or 0)\n        agents=manifest.get(\"agents\") or {}\n        seen=set()\n\n    start=datetime.combine(day,datetime.min.time()).astimezone()\n    end=datetime.now().astimezone()\n    counters=Counter()\n    writers={}\n\n    def writer_for_agent(agent_id):\n        aid=str(agent_id or \"000\")\n        handle=writers.get(aid)\n        if handle is None:\n            path=cache_path(cache_dir,day,aid)\n            handle=gzip.open(path,\"at\",encoding=\"utf-8\")\n            writers[aid]=handle\n        return handle\n\n    try:\n        with open(source,\"rb\") as src:\n            src.seek(offset)\n            seen=normalize_stream_sharded((line for line in src),writer_for_agent,start,end,counters,seen,agents)\n            new_offset=src.tell()\n        for handle in writers.values():\n            handle.close()\n        writers.clear()\n    except Exception:\n        for handle in writers.values():\n            try: handle.close()\n            except OSError: pass\n        writers.clear()\n        raise\n\n    for aid in list(agents):\n        p=cache_path(cache_dir,day,aid)\n        try: agents[aid][\"size\"]=p.stat().st_size\n        except OSError: agents[aid][\"size\"]=0\n\n    total_new=total+counters[\"events\"]\n    manifest=write_manifest(cache_dir,day,agents,total_new)\n    atomic_json(state_path(cache_dir,day),{\n        \"version\":4,\n        \"day\":day.isoformat(),\n        \"closed\":False,\n        \"inode\":stat.st_ino,\n        \"offset\":new_offset,\n        \"source_size\":stat.st_size,\n        \"source_mtime_ns\":stat.st_mtime_ns,\n        \"events\":total_new,\n        \"cache_size\":sum(item[\"size\"] for item in manifest[\"agents\"].values()),\n        \"agents\":len(manifest[\"agents\"]),\n        \"updated_at\":datetime.now().astimezone().isoformat(),\n    })\n    return counters[\"events\"]\n\n\ndef ensure_cache(cache_dir,start,end):\n    \"\"\"\n    Garantiza la mejor representación disponible para cada día sin hacer fallar\n    un reporte completo por falta/corrupción de un log individual.\n\n    Estado de los logs:\n      - .gz -> log rotado/finalizado -> el cache puede quedar closed=true;\n      - .json -> log operativo -> el cache queda closed=false.\n\n    Prioridad para días cerrados:\n      1) cache completo -> usar cache y eliminar únicamente el .gz residual;\n      2) cache incompleto + log disponible -> reconstruir el día;\n      3) cache incompleto + log ausente/corrupto -> conservar cache parcial;\n      4) sin cache + log válido -> construir cache;\n      5) sin cache + log ausente/corrupto -> saltar día.\n\n    Para hoy:\n      - con alerts.json -> actualización incremental;\n      - sin alerts.json -> usar lo que exista en cache;\n      - si no hay ninguno -> saltar el día.\n    \"\"\"\n    day=start.date()\n    last=(end-timedelta(microseconds=1)).date()\n    today=datetime.now().astimezone().date()\n    total=0\n\n    while day<=last:\n        try:\n            if day==today:\n                if ALERTS_FILE.exists():\n                    try:\n                        total += update_today(cache_dir)\n                    except (Exception,SystemExit) as exc:\n                        if cache_day_available(cache_dir,day):\n                            print(\n                                f\"AVISO: no se pudo actualizar el cache de {day}; \"\n                                f\"se conserva el cache existente: {exc}\",\n                                flush=True,\n                            )\n                        else:\n                            print(\n                                f\"AVISO: no se pudo leer alerts.json de {day}; \"\n                                f\"se salta el día: {exc}\",\n                                flush=True,\n                            )\n                elif cache_day_available(cache_dir,day):\n                    print(\n                        f\"AVISO: no existe {ALERTS_FILE}; se usa el cache disponible de {day}.\",\n                        flush=True,\n                    )\n                else:\n                    print(\n                        f\"AVISO: no existe {ALERTS_FILE} ni cache para {day}; se salta el día.\",\n                        flush=True,\n                    )\n                day += timedelta(days=1)\n                continue\n\n            if cache_day_complete(cache_dir,day):\n                removed,errors=purge_day_sources(day)\n                if errors:\n                    for detail in errors:\n                        print(f\"AVISO: no se pudo eliminar log cerrado {detail}\",flush=True)\n                if removed:\n                    print(f\"Cache completo usado: {day.isoformat()} · logs eliminados: {removed}\",flush=True)\n                day += timedelta(days=1)\n                continue\n\n            sources=day_sources(day)\n            has_cache=cache_day_available(cache_dir,day)\n\n            if sources:\n                try:\n                    total += rebuild_day(cache_dir,day)\n                except (Exception,SystemExit) as exc:\n                    if has_cache:\n                        print(\n                            f\"AVISO: log de {day} no pudo reconstruirse; \"\n                            f\"se conserva el cache disponible: {exc}\",\n                            flush=True,\n                        )\n                    else:\n                        print(\n                            f\"AVISO: log de {day} no pudo leerse y no hay cache; \"\n                            f\"se salta el día: {exc}\",\n                            flush=True,\n                        )\n            elif has_cache:\n                print(\n                    f\"AVISO: no existe log para {day}; se usa el cache disponible.\",\n                    flush=True,\n                )\n            else:\n                print(\n                    f\"AVISO: no existe log ni cache para {day}; se salta el día.\",\n                    flush=True,\n                )\n\n        except (Exception,SystemExit) as exc:\n            if cache_day_available(cache_dir,day):\n                print(\n                    f\"AVISO: fallo procesando {day}; se conserva el cache disponible: {exc}\",\n                    flush=True,\n                )\n            else:\n                print(\n                    f\"AVISO: fallo procesando {day} y no hay cache; se salta el día: {exc}\",\n                    flush=True,\n                )\n\n        day += timedelta(days=1)\n\n    return total\n\n\ndef iter_cache(cache_dir,start_day,end_day,allowed_ids=None):\n    allowed=None if allowed_ids is None else {str(v) for v in allowed_ids}\n    day=start_day\n    loads=orjson.loads if orjson is not None else json.loads\n    while day<=end_day:\n        manifest=load_manifest(manifest_path(cache_dir,day))\n        agents=manifest.get(\"agents\") or {}\n\n        if agents:\n            selected=sorted(agents) if allowed is None else sorted(allowed.intersection(agents))\n            paths=[cache_path(cache_dir,day,agent_id) for agent_id in selected]\n        else:\n            # Fallback para cache parcial/incompleto: si falta manifest o no\n            # contiene agentes, leer los shards existentes del día.\n            paths=cache_day_files(cache_dir,day)\n\n        for p in paths:\n            if not p.exists():\n                continue\n            try:\n                with gzip.open(p,\"rb\") as h:\n                    for line in h:\n                        try:\n                            e=loads(line)\n                            if isinstance(e,dict):\n                                if allowed is not None and str(e.get(\"agent_id\",\"000\")) not in allowed:\n                                    continue\n                                yield e\n                        except (ValueError,TypeError,UnicodeDecodeError):\n                            continue\n            except (OSError,EOFError) as exc:\n                print(f\"AVISO: cache corrupto o truncado, se salta {p}: {exc}\",flush=True)\n        day+=timedelta(days=1)\ndef period(mode, now):\n    today=now.date(); tz=now.tzinfo\n    if mode==\"today\": return datetime.combine(today,datetime.min.time(),tz),now\n    if mode==\"yesterday\": return datetime.combine(today-timedelta(days=1),datetime.min.time(),tz),datetime.combine(today,datetime.min.time(),tz)\n    monday=today-timedelta(days=today.weekday())\n    if mode==\"thisweek\": return datetime.combine(monday,datetime.min.time(),tz),now\n    if mode==\"lastweek\": return datetime.combine(monday-timedelta(days=7),datetime.min.time(),tz),datetime.combine(monday,datetime.min.time(),tz)\n    first=today.replace(day=1)\n    if mode==\"thismonth\": return datetime.combine(first,datetime.min.time(),tz),now\n    if mode==\"lastmonth\":\n        prev=first-timedelta(days=1); return datetime.combine(prev.replace(day=1),datetime.min.time(),tz),datetime.combine(first,datetime.min.time(),tz)\n    year=today.replace(month=1,day=1)\n    if mode==\"thisyear\": return datetime.combine(year,datetime.min.time(),tz),now\n    if mode==\"lastyear\": return datetime.combine(year.replace(year=year.year-1),datetime.min.time(),tz),datetime.combine(year,datetime.min.time(),tz)\n    if mode.startswith(\"date:\"):\n        d=datetime.strptime(mode[5:],\"%Y-%m-%d\").date(); return datetime.combine(d,datetime.min.time(),tz),datetime.combine(d+timedelta(days=1),datetime.min.time(),tz)\n    raise SystemExit(\"Período no válido\")\n\n\ndef aggregate(events, allowed):\n    stats=defaultdict(lambda:{\"events\":0,\"high\":0,\"critical\":0,\"attacks\":0,\"ips\":set(),\"categories\":Counter(),\"rules\":Counter(),\"mitre\":Counter(),\"blocked\":Counter()})\n    for e in events:\n        if allowed is not None and e.get(\"agent_id\") not in allowed: continue\n        aid=e.get(\"agent_id\",\"000\")\n        if e.get(\"outer_rule\")==FIREWALL_RULE:\n            if e.get(\"srcip\"): stats[aid][\"blocked\"][e[\"srcip\"]]+=1\n            continue\n        s=stats[aid]; level=int(e.get(\"level\",0) or 0); cat=e.get(\"category\",classify(e.get(\"rule_id\"),e.get(\"groups\"),level))\n        s[\"events\"]+=1; s[\"high\"] += 12<=level<15; s[\"critical\"] += level>=15; s[\"attacks\"] += cat==\"attack\"; s[\"categories\"][cat]+=1\n        s[\"rules\"][e.get(\"description\",\"Detección sin descripción\")]+=1\n        if e.get(\"srcip\"): s[\"ips\"].add(e[\"srcip\"])\n        for m in (e.get(\"mitre\") or []):\n            if m: s[\"mitre\"][str(m)]+=1\n    return stats\n\n\ndef checksum_events(events):\n    h=hashlib.sha256(); count=0\n    for e in events:\n        h.update(json.dumps(e,ensure_ascii=False,sort_keys=True,separators=(\",\",\":\")).encode()); h.update(b\"\\n\"); count+=1\n    return count,h.hexdigest()\n\n\ndef main():\n    p=argparse.ArgumentParser(description=\"OrangeBox Wazuh Report Engine PROTO v2\")\n    modes=p.add_mutually_exclusive_group(required=True)\n    for n in (\"today\",\"yesterday\",\"thisweek\",\"lastweek\",\"thismonth\",\"lastmonth\",\"thisyear\",\"lastyear\"): modes.add_argument(\"--\"+n,action=\"store_true\")\n    modes.add_argument(\"--date\")\n    p.add_argument(\"--cache-dir\",type=Path,default=DEFAULT_CACHE); p.add_argument(\"--rebuild\",action=\"store_true\"); p.add_argument(\"--status\",action=\"store_true\"); p.add_argument(\"--verify\",action=\"store_true\",help=\"Releer el cache completo y calcular SHA256 (benchmark/validacion)\")\n    args=p.parse_args(); now=datetime.now().astimezone(); mode=args.date and \"date:\"+args.date or next(n for n in (\"today\",\"yesterday\",\"thisweek\",\"lastweek\",\"thismonth\",\"lastmonth\",\"thisyear\",\"lastyear\") if getattr(args,n))\n    if args.status:\n        total=0\n        for f in sorted(args.cache_dir.glob(\"*.jsonl.gz\")) if args.cache_dir.exists() else []:\n            total+=f.stat().st_size; print(f\"{f.name} {f.stat().st_size:,} B\")\n        print(f\"TOTAL {total:,} B\"); return 0\n    start,end=period(mode,now); t=time.monotonic()\n    if args.rebuild:\n        d=start.date(); last=(end-timedelta(microseconds=1)).date()\n        while d<=last:\n            if d==now.date():\n                pth=cache_path(args.cache_dir,d); st=state_path(args.cache_dir,d)\n                if pth.exists(): pth.unlink()\n                if st.exists(): st.unlink()\n                update_today(args.cache_dir)\n            else: rebuild_day(args.cache_dir,d)\n            d+=timedelta(days=1)\n    else: ensure_cache(args.cache_dir,start,end)\n    cache_elapsed=time.monotonic()-t\n    print(f\"Cache listo en {cache_elapsed:.3f}s\")\n    if not args.verify:\n        print(\"Fin del motor de cache.\")\n        return 0\n    tv=time.monotonic()\n    count,sha=checksum_events(iter_cache(args.cache_dir,start.date(),(end-timedelta(microseconds=1)).date()))\n    print(f\"Verificacion en {time.monotonic()-tv:.3f}s\")\n    print(f\"Eventos cache: {count}\"); print(f\"SHA256 eventos: {sha}\")\n    return 0\n\nif __name__==\"__main__\": raise SystemExit(main())\n"
REPORT_SOURCE = "#!/usr/bin/env python3\n\"\"\"OrangeBox Wazuh Security Activity Report.\n\nGenera reportes HTML portables a partir de las alertas JSON de Wazuh.\nEl HTML usa tablas e estilos inline para funcionar en Thunderbird, webmail y móvil.\n\"\"\"\nimport argparse\nimport base64\nimport gzip\nimport html\nimport ssl\nimport urllib.error\nimport urllib.request\ntry:\n    import orjson\nexcept ImportError:\n    orjson = None\nimport ipaddress\nimport json\nimport os\nimport re\nimport subprocess\nimport shutil\ntry:\n    import maxminddb\nexcept ImportError:\n    maxminddb = None\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timedelta\nfrom email.mime.multipart import MIMEMultipart\nfrom email.mime.text import MIMEText\nfrom pathlib import Path\n\nALERTS_ROOT = \"/var/ossec/logs/alerts\"\nALERTS_FILE = f\"{ALERTS_ROOT}/alerts.json\"\nARCHIVE_DIR = \"/var/ossec/reports/archive\"\nDEFAULT_FROM = \"wazuh@example.com\"\nAGENT_GROUPS_BIN = \"/var/ossec/bin/agent_groups\"\nINDEXER_CONFIG = \"/var/ossec/etc/orangebox-indexer.conf\"\nFIREWALL_RULE = \"10458\"\nFIREWALL_RE = re.compile(r\"active-response/bin/firewall-drop:\\s*(\\{.*\\})$\")\nWAZUH_OSSEC_CONF = \"/var/ossec/etc/ossec.conf\"\nLOGO_URL = \"https://www.example.invalid/obox/img/logo-dark.png\"\n\nAUTH_RULES = {\"5710\", \"5712\", \"5715\", \"5716\", \"5720\", \"5760\", \"5763\", \"10001\", \"10006\", \"10007\", \"10008\", \"10009\", \"40101\"}\nWEB_RULES = {\"31101\", \"10023\", \"10024\", \"10025\", \"10026\"}\nFIM_RULES = {\"550\", \"553\", \"554\", \"10060\", \"10062\", \"10063\", \"10410\", \"10432\"}\nMALWARE_RULES = {\"10060\", \"10062\", \"10063\", \"10410\", \"10432\"}\nPRIV_RULES = {\"10004\", \"10005\", \"5402\", \"5403\", \"10032\"}\nAUTH_GROUPS = {\"authentication\", \"authentication_success\", \"authentication_failed\"}\nWEB_GROUPS = {\"web\", \"orangebox_web\"}\nFIM_GROUPS = {\"syscheck\", \"syscheck_entry_added\", \"syscheck_entry_modified\", \"syscheck_entry_deleted\", \"orangebox_temporary_executable\"}\nMALWARE_GROUPS = {\"malware\", \"webshell\", \"orangebox_malware\", \"orangebox_webshell\"}\nATTACK_GROUPS = {\"attack\", \"brute_force\", \"reconnaissance\", \"credential_discovery\", \"sensitive_file\", \"lateral_movement\"}\nREPORT_EXCLUDED_GROUPS = {\"orangebox_exception\", \"orangebox_whitelist\"}\n\n# Grupos funcionales/tecnicos que no representan clientes cuando se usa --group all.\nREPORT_NON_CLIENT_GROUPS = {\"default\", \"cpanel\", \"zimbra\"}\nREPORT_EXCLUDED_RULES = {\"5402\"}\n\nRULE_CANONICAL_DESCRIPTIONS = {\n    \"5710\": \"SSH: Intento de acceso con usuario inexistente.\",\n    \"5712\": \"SSH: Fuerza bruta intentando acceder al sistema con usuario inexistente.\",\n    \"5715\": \"SSH: Inicio de sesión exitoso.\",\n    \"5760\": \"SSH: Autenticación fallida.\",\n    \"5763\": \"SSH: Fuerza bruta intentando acceder al sistema con autenticación fallida.\",\n    \"5758\": \"SSH: Se superó el máximo de intentos de autenticación.\",\n    \"10001\": \"SSH: Inicio de sesión SSH exitoso.\",\n    \"10006\": \"SSH: Fuerza bruta completada con éxito.\",\n    \"10007\": \"SSH: Posible movimiento lateral desde la red interna.\",\n    \"40101\": \"ACCESO: Sesión de usuario iniciada.\",\n    \"5501\": \"ACCESO: Sesión PAM de usuario abierta.\",\n    \"5503\": \"ACCESO: Fallo de autenticación de usuario PAM.\",\n    \"2501\": \"ACCESO: Fallo de autenticación de usuario.\",\n    \"2502\": \"ACCESO: Contraseña incorrecta en múltiples intentos.\",\n    \"3332\": \"ACCESO: Fallo de autenticación SASL de Postfix.\",\n    \"10004\": \"PRIVILEGIOS: Usuario cambió de sesión a ROOT mediante comando SU.\",\n    \"10005\": \"PRIVILEGIOS: SUDO hacia ROOT con comando no autorizado por la whitelist OrangeBox.\",\n    \"5402\": \"PRIVILEGIOS: SUDO hacia ROOT ejecutado.\",\n    \"5403\": \"PRIVILEGIOS: Primera ejecución de SUDO por el usuario.\",\n    \"10032\": \"PRIVILEGIOS: Configuración de SUDO modificada.\",\n    \"550\": \"ARCHIVOS: Integridad de archivo modificada.\",\n    \"553\": \"ARCHIVOS: Archivo eliminado.\",\n    \"554\": \"ARCHIVOS: Archivo agregado al sistema.\",\n    \"517\": \"ARCHIVOS: Directorio monitorizado eliminado.\",\n    \"560\": \"ARCHIVOS: Cola de FIM en tiempo real llena.\",\n    \"231\": \"ARCHIVOS: Límite de archivos monitorizados próximo a alcanzarse.\",\n    \"10060\": \"MALWARE: Script SHELL creado en directorio temporal.\",\n    \"10062\": \"MALWARE: Posible WebShell PHP creado.\",\n    \"10063\": \"MALWARE: Posible WebShell PHP modificado.\",\n    \"10410\": \"MALWARE: Archivo ejecutable creado en directorio temporal.\",\n    \"10432\": \"MALWARE: Permiso de ejecución agregado a archivo en directorio temporal.\",\n    \"10023\": \"WEB: Reconocimiento o acceso a recurso sensible detectado.\",\n    \"10024\": \"WEB: HTTP 401/403 detectado contra servidor web.\",\n    \"10025\": \"WEB: Posible fuerza bruta web.\",\n    \"10026\": \"WEB: Posible reconocimiento automatizado de archivos sensibles o credenciales web.\",\n    \"31101\": \"WEB: Código de error 400 del servidor web.\",\n    \"31516\": \"WEB: Acceso a URL sospechosa.\",\n    \"31533\": \"WEB: Alta cantidad de solicitudes POST en un período corto.\",\n    \"31509\": \"WEB: Intento de acceso de login de CMS.\",\n    \"31151\": \"WEB: Múltiples errores 400 desde la misma IP de origen.\",\n    \"30306\": \"WEB: Intento de acceso a índice de directorio prohibido.\",\n    \"30318\": \"WEB: Aviso PHP detectado en log de Apache.\",\n    \"31515\": \"WEB: Escaneo de PHPMyAdmin detectado.\",\n    \"31104\": \"WEB: Ataque web común detectado.\",\n    \"30305\": \"WEB: Intento de acceso a archivo o directorio prohibido.\",\n    \"31510\": \"WEB: Fuerza bruta contra CMS detectada.\",\n    \"31106\": \"WEB: Ataque web que devolvió código HTTP 200.\",\n    \"10453\": \"RED: Posible escaneo de puertos TCP desde la misma IP de origen.\",\n    \"10454\": \"RED: Posible inundación TCP SYN desde la misma IP de origen.\",\n    \"10456\": \"ESCANEO DE PUERTOS\",\n    \"10457\": \"SYN FLOOD\",\n    \"10455\": \"RED: Posible ataque de denegación de servicio distribuido.\",\n    \"10034\": \"CONFIGURACIÓN: Unidad o configuración persistente de SYSTEMD modificada.\",\n    \"10035\": \"CONFIGURACIÓN: Configuración de CRON o ANACRON modificada.\",\n    \"10036\": \"RED: Configuración crítica de red, DNS o montaje modificada.\",\n    \"10037\": \"CONFIGURACIÓN: Configuración de FIREWALL modificada.\",\n    \"10044\": \"CONFIGURACIÓN: Unidad o configuración persistente de SYSTEMD eliminada.\",\n    \"100311\": \"ENDPOINT: Nuevo puerto de red detectado en el endpoint.\",\n    \"100313\": \"ENDPOINT: Nuevo servicio detectado en el endpoint.\",\n}\n\nMITRE_DESCRIPTIONS = {\n    \"T1110\": \"Fuerza bruta: intentos repetidos para obtener acceso mediante credenciales.\",\n    \"T1110.001\": \"Intentos repetidos de acceso probando contraseñas.\",\n    \"T1021\": \"Acceso remoto a otro sistema mediante un servicio de red.\",\n    \"T1021.004\": \"Acceso remoto a sistemas mediante SSH.\",\n    \"T1078\": \"Uso de una cuenta o credencial válida para intentar acceder.\",\n    \"T1565.001\": \"Modificación de información almacenada para alterar su contenido o comportamiento.\",\n    \"T1070.004\": \"Eliminación de archivos para borrar rastros de actividad.\",\n    \"T1485\": \"Destrucción de datos para provocar pérdida o interrupción de información.\",\n    \"T1548.003\": \"Uso de sudo para ejecutar acciones con privilegios elevados.\",\n    \"T1055\": \"Intento de ejecutar código dentro de otro proceso para evadir controles.\",\n    \"T1190\": \"Intento de aprovechar una aplicación o servicio expuesto a Internet.\",\n    \"T1498\": \"Intento de saturar un servicio mediante un volumen elevado de tráfico.\",\n    \"T1595.002\": \"Reconocimiento activo para identificar servicios o sistemas accesibles.\",\n    \"T1083\": \"Búsqueda de archivos y directorios para conocer qué existe en el sistema.\",\n    \"T1552\": \"Búsqueda de información sensible almacenada de forma insegura.\",\n    \"T1098\": \"Modificación de cuentas para mantener o ampliar el acceso.\",\n    \"T1059\": \"Uso de una consola o intérprete para ejecutar comandos.\",\n    \"T1059.004\": \"Ejecución de comandos mediante una consola Unix o Linux.\",\n    \"T1105\": \"Descarga o transferencia de archivos desde una ubicación remota.\",\n    \"T1505.003\": \"Intento de instalar o utilizar un componente web malicioso, como un webshell.\",\n}\n\nLABELS_ES = {\n    \"report\": \"Informe de Actividad de Seguridad\", \"subtitle\": \"Actividad de seguridad, detecciones y acciones automatizadas de Wazuh\", \"security_events\": \"Eventos de seguridad\", \"high_alerts\": \"Alertas de alta severidad\", \"source_ips\": \"IPs de origen observadas\", \"systems\": \"Servidores afectados\", \"firewall\": \"Bloqueo automático de IPs · Motivo\", \"firewall_sub\": \"Motivos que activaron el bloqueo automático y cantidad de IPs afectadas.\", \"agent\": \"Sistema\", \"reason\": \"Motivo\", \"rule\": \"Regla\", \"blocked_ips\": \"IPs bloqueadas\", \"attempts\": \"Intentos detectados\", \"access\": \"Intentos de acceso\", \"web\": \"Intentos de acceso y exploración web\", \"fim\": \"Cambios detectados en archivos\", \"malware\": \"Detecciones de malware y archivos sospechosos\", \"priv\": \"Escalamiento de privilegios\", \"attack\": \"Detecciones clasificadas como intentos de ataque\", \"mitre\": \"Técnicas MITRE observadas en las alertas\", \"technique\": \"Técnica\", \"meaning\": \"Qué significa\", \"detections\": \"Alertas asociadas\", \"agents\": \"Servidores afectados\", \"no_firewall\": \"No se registraron bloqueos automáticos con una IP de origen válida.\", \"no_activity\": \"No se registraron detecciones de esta categoría durante el período.\", \"attack_note\": \"Esta sección incluye únicamente alertas que el informe clasificó explícitamente como actividad de ataque. Que una técnica MITRE aparezca más abajo no significa por sí sola que exista un ataque confirmado.\", \"mitre_note\": \"El contador indica cuántas alertas de Wazuh fueron asociadas a cada técnica MITRE durante el período. No representa necesariamente accesos exitosos, conexiones individuales ni compromisos confirmados.\", \"firewall_note\": \"Los intentos detectados son detecciones Wazuh asociadas a las IP que fueron bloqueadas; no equivalen necesariamente a la cantidad bruta de conexiones o solicitudes originales.\", \"recidivist\": \"IPs reincidentes en bloqueos automáticos\", \"recidivist_sub\": \"IPs bloqueadas automáticamente más de una vez durante el período, con el servidor que ejecutó el bloqueo.\", \"block_count\": \"Bloqueos\", \"trigger_rules\": \"Reglas que activaron el bloqueo\", \"ban_duration\": \"Tiempo de baneo configurado\", \"servers\": \"Servidores más afectados\", \"servers_sub\": \"Resumen de actividad por servidor durante el período.\", \"events\": \"Eventos\", \"high\": \"Alta severidad\", \"source_ips_col\": \"IPs origen\", \"attack_alerts\": \"Alertas de ataque\", \"no_servers\": \"No se registraron eventos para los servidores durante el período.\", \"cve\": \"Vulnerabilidades críticas (CVE)\", \"cve_sub\": \"Resumen del inventario actual de vulnerabilidades críticas del Wazuh Indexer.\", \"cve_total\": \"Hallazgos CVE críticos\", \"cve_systems\": \"Sistemas con CVE críticos\", \"cve_agent\": \"Servidor\", \"cve_count\": \"CVE críticos\", \"cve_error\": \"No fue posible consultar el inventario de vulnerabilidades del Wazuh Indexer.\", \"cve_none\": \"No se registran CVE críticos en el inventario consultado.\", \"cve_unsupported\": \"CloudLinux detectado: Wazuh no realiza actualmente evaluación nativa de vulnerabilidades para esta distribución; no corresponde interpretar el resultado como ausencia de CVE.\", \"technical_note\": \"Los identificadores y descripciones de las reglas corresponden al motor de detección Wazuh. La detección de un intento no implica por sí sola que el sistema haya sido comprometido.\",\n}\nLABELS_EN = {\n    \"report\": \"Security Activity Report\", \"subtitle\": \"Security activity, detections and automated Wazuh responses\", \"security_events\": \"Security events\", \"high_alerts\": \"High-severity alerts\", \"source_ips\": \"Observed source IPs\", \"systems\": \"Affected servers\", \"firewall\": \"Automatic IP blocking · Reason\", \"firewall_sub\": \"Reasons that triggered automatic blocking and number of affected IPs.\", \"agent\": \"System\", \"reason\": \"Reason\", \"rule\": \"Rule\", \"blocked_ips\": \"Blocked IPs\", \"attempts\": \"Detected attempts\", \"access\": \"Access attempts\", \"web\": \"Web access and reconnaissance attempts\", \"fim\": \"Detected file changes\", \"malware\": \"Malware and suspicious file detections\", \"priv\": \"Privilege escalation\", \"attack\": \"Detections classified as attack attempts\", \"mitre\": \"MITRE techniques observed in alerts\", \"technique\": \"Technique\", \"meaning\": \"What it means\", \"detections\": \"Associated alerts\", \"agents\": \"Most affected systems\", \"no_firewall\": \"No automatic blocks with a valid source IP were recorded.\", \"no_activity\": \"No detections were recorded for this category during the period.\", \"attack_note\": \"This section includes only alerts explicitly classified by the report as attack activity. The appearance of a MITRE technique below does not by itself mean that a confirmed attack occurred.\", \"mitre_note\": \"The counter shows how many Wazuh alerts were associated with each MITRE technique during the period. It does not necessarily represent successful logins, individual connections, or confirmed compromises.\", \"firewall_note\": \"Detected attempts are Wazuh detections associated with the IPs that were blocked; they do not necessarily equal the raw number of original connections or requests.\", \"recidivist\": \"IPs with repeated automatic blocks\", \"recidivist_sub\": \"IPs automatically blocked more than once during the period, with the server that executed the block.\", \"block_count\": \"Blocks\", \"trigger_rules\": \"Rules that triggered the block\", \"ban_duration\": \"Configured ban time\", \"servers\": \"Most affected servers\", \"servers_sub\": \"Activity summary by server during the period.\", \"events\": \"Events\", \"high\": \"High severity\", \"source_ips_col\": \"Source IPs\", \"attack_alerts\": \"Attack alerts\", \"no_servers\": \"No server events were recorded during the period.\", \"cve\": \"Critical vulnerabilities (CVE)\", \"cve_sub\": \"Summary of the current critical vulnerability inventory from the Wazuh Indexer.\", \"cve_total\": \"Critical CVE findings\", \"cve_systems\": \"Systems with critical CVEs\", \"cve_agent\": \"Server\", \"cve_count\": \"Critical CVEs\", \"cve_error\": \"The Wazuh Indexer vulnerability inventory could not be queried.\", \"cve_none\": \"No critical CVEs are recorded in the queried inventory.\", \"cve_unsupported\": \"CloudLinux detected: Wazuh does not currently provide native vulnerability assessment for this distribution; the result must not be interpreted as absence of CVEs.\", \"technical_note\": \"Rule identifiers and descriptions come from the Wazuh detection engine. Detecting an attempt does not by itself mean that the system was compromised.\",\n}\n\ndef labels(lang): return LABELS_EN if lang == \"en\" else LABELS_ES\ndef esc(value): return html.escape(str(value), quote=True)\n\n\ndef display_agent_name(value):\n    \"\"\"Limpia prefijos visuales que no forman parte del nombre del agente.\"\"\"\n    return re.sub(r\"^\\s*(?:→|➜|➤|»|›|▶|►|⮕|➥)+\\s*\", \"\", str(value or \"\")).strip()\n\n\ndef standardize_rule_description(rule_id, description, groups=None):\n    \"\"\"Normaliza los nombres de reglas para el reporte sin modificar Wazuh.\"\"\"\n    rid = str(rule_id)\n    if rid in RULE_CANONICAL_DESCRIPTIONS:\n        return RULE_CANONICAL_DESCRIPTIONS[rid]\n\n    text = str(description or \"Sin descripción\").strip()\n    text = re.sub(\n        r\"^(?:ALERTA(?:\\s+CRITICA)?|ORANGEBOX(?:\\s+TEST)?)\\s*:\\s*\",\n        \"\",\n        text,\n        flags=re.IGNORECASE,\n    )\n    text = re.sub(r\"\\s+\", \" \", text).strip()\n\n    group_set = {str(value).lower() for value in (groups or [])}\n    if rid in MALWARE_RULES or group_set & MALWARE_GROUPS:\n        prefix = \"MALWARE\"\n    elif rid in PRIV_RULES or group_set & {\"privilege_escalation\", \"privilege_escalation_root\", \"sudo\"}:\n        prefix = \"PRIVILEGIOS\"\n    elif rid in WEB_RULES or group_set & WEB_GROUPS:\n        prefix = \"WEB\"\n    elif rid in FIM_RULES or group_set & FIM_GROUPS:\n        prefix = \"ARCHIVOS\"\n    elif rid in AUTH_RULES or group_set & AUTH_GROUPS:\n        prefix = \"SSH\" if \"ssh\" in group_set else \"ACCESO\"\n    elif group_set & ATTACK_GROUPS:\n        prefix = \"ATAQUE\"\n    else:\n        return text or \"Sin descripción\"\n\n    return text if re.match(rf\"^{re.escape(prefix)}\\s*:\", text, flags=re.IGNORECASE) else f\"{prefix}: {text}\"\n\n\ndef report_event_exempt(event):\n    group_set = {str(value).lower() for value in (event.get(\"groups\") or [])}\n    rule_id = str(event.get(\"rule_id\", \"\")).strip()\n    try:\n        level = int(event.get(\"level\", 0) or 0)\n    except (TypeError, ValueError):\n        level = 0\n    return (\n        level <= 0\n        or rule_id in REPORT_EXCLUDED_RULES\n        or bool(group_set & REPORT_EXCLUDED_GROUPS)\n    )\n\n\ndef read_secure_kv(path):\n    values = {}\n    path = Path(path)\n    if not path.exists():\n        return values\n    try:\n        mode = path.stat().st_mode & 0o777\n    except OSError:\n        mode = 0\n    if mode & 0o077:\n        raise RuntimeError(f\"{path} debe tener permisos 0600 o más restrictivos.\")\n    try:\n        content = path.read_text(encoding=\"utf-8\")\n    except OSError as exc:\n        raise RuntimeError(f\"No se pudo leer {path}: {exc}\") from exc\n    for line in content.splitlines():\n        line = line.strip()\n        if not line or line.startswith(\"#\") or \"=\" not in line:\n            continue\n        key, value = line.split(\"=\", 1)\n        values[key.strip()] = value.strip().strip(\"'\").strip('\"')\n    return values\n\n\ndef indexer_settings():\n    config = read_secure_kv(INDEXER_CONFIG)\n    user = os.environ.get(\"WAZUH_INDEXER_USER\") or config.get(\"WAZUH_INDEXER_USER\") or \"admin\"\n    password = os.environ.get(\"WAZUH_INDEXER_PASS\") or config.get(\"WAZUH_INDEXER_PASS\")\n    if not password:\n        raise RuntimeError(\n            f\"No existe WAZUH_INDEXER_PASS en {INDEXER_CONFIG}. \"\n            \"El password del Indexer no debe quedar dentro del repositorio.\"\n        )\n    return {\n        \"url\": (os.environ.get(\"WAZUH_INDEXER_URL\") or config.get(\"WAZUH_INDEXER_URL\") or \"https://127.0.0.1:9200\").rstrip(\"/\"),\n        \"user\": user,\n        \"password\": password,\n    }\n\n\ndef indexer_request(settings, path, payload):\n    body = json.dumps(payload).encode(\"utf-8\")\n    token = base64.b64encode(\n        f\"{settings['user']}:{settings['password']}\".encode(\"utf-8\")\n    ).decode(\"ascii\")\n    request = urllib.request.Request(\n        f\"{settings['url']}{path}\",\n        data=body,\n        method=\"POST\",\n        headers={\n            \"Content-Type\": \"application/json\",\n            \"Authorization\": f\"Basic {token}\",\n        },\n    )\n    context = ssl._create_unverified_context()\n    try:\n        with urllib.request.urlopen(request, context=context, timeout=30) as response:\n            return json.loads(response.read().decode(\"utf-8\")), None\n    except urllib.error.HTTPError as exc:\n        try:\n            detail = exc.read().decode(\"utf-8\", errors=\"replace\")\n        except OSError:\n            detail = \"\"\n        return None, f\"Indexer HTTP {exc.code}: {detail[:300]}\"\n    except (urllib.error.URLError, TimeoutError, ValueError, OSError) as exc:\n        return None, f\"Consulta al Indexer falló: {exc}\"\n\n\ndef fetch_critical_cves(allowed):\n    try:\n        settings = indexer_settings()\n    except RuntimeError as exc:\n        return {\"total\": 0, \"agents\": {}, \"unsupported_agents\": {}}, str(exc)\n\n    filters = [{\"term\": {\"vulnerability.severity\": \"Critical\"}}]\n    if allowed is not None:\n        if not allowed:\n            return {\"total\": 0, \"agents\": {}, \"unsupported_agents\": {}}, None\n        filters.append({\"terms\": {\"agent.id\": sorted(allowed)}})\n\n    results = {}\n    total_reported = None\n    search_after = None\n\n    while True:\n        payload = {\n            \"size\": 1000,\n            \"track_total_hits\": True,\n            \"_source\": [\n                \"agent.id\",\n                \"agent.name\",\n            ],\n            \"query\": {\n                \"bool\": {\n                    \"filter\": filters,\n                }\n            },\n            \"sort\": [\n                {\"_index\": {\"order\": \"asc\"}},\n                {\"_id\": {\"order\": \"asc\"}},\n            ],\n        }\n        if search_after is not None:\n            payload[\"search_after\"] = search_after\n\n        data, error = indexer_request(\n            settings,\n            \"/wazuh-states-vulnerabilities-*/_search\",\n            payload,\n        )\n        if error:\n            return {\"total\": 0, \"agents\": {}, \"unsupported_agents\": {}}, error\n\n        hits_root = data.get(\"hits\") or {}\n        if total_reported is None:\n            total = hits_root.get(\"total\") or 0\n            total_reported = int(total.get(\"value\", total) if isinstance(total, dict) else total)\n\n        hits = hits_root.get(\"hits\") or []\n        if not hits:\n            break\n\n        for hit in hits:\n            source = hit.get(\"_source\") or {}\n            agent = source.get(\"agent\") or {}\n            agent_id = str(agent.get(\"id\", \"\")).strip()\n            if not agent_id:\n                continue\n            agent_name = str(agent.get(\"name\") or f\"Servidor {agent_id}\")\n            record = results.setdefault(agent_id, {\"name\": agent_name, \"count\": 0})\n            record[\"count\"] += 1\n\n        next_sort = hits[-1].get(\"sort\")\n        if not next_sort:\n            break\n        if next_sort == search_after:\n            return {\"total\": 0, \"agents\": {}, \"unsupported_agents\": {}}, \"La paginación del inventario CVE quedó sin avance.\"\n        search_after = next_sort\n        if len(hits) < 1000:\n            break\n\n    unsupported_agents = {}\n    if allowed:\n        os_filters = [{\"terms\": {\"agent.id\": sorted(allowed)}}]\n        os_payload = {\n            \"size\": max(1000, len(allowed)),\n            \"track_total_hits\": False,\n            \"_source\": [\"agent.id\", \"agent.name\", \"host.os.name\", \"host.os.platform\"],\n            \"query\": {\"bool\": {\"filter\": os_filters}},\n        }\n        os_data, os_error = indexer_request(\n            settings,\n            \"/wazuh-states-inventory-system-*/_search\",\n            os_payload,\n        )\n        if not os_error:\n            for hit in (os_data.get(\"hits\") or {}).get(\"hits\", []):\n                source = hit.get(\"_source\") or {}\n                agent = source.get(\"agent\") or {}\n                agent_id = str(agent.get(\"id\", \"\")).strip()\n                host_os = source.get(\"host\") or {}\n                os_data_block = host_os.get(\"os\") or {}\n                os_name = str(os_data_block.get(\"name\") or \"\").strip()\n                os_platform = str(os_data_block.get(\"platform\") or \"\").strip()\n                os_name_l = os_name.lower()\n                os_platform_l = os_platform.lower()\n                is_almalinux = \"almalinux\" in os_name_l or \"almalinux\" in os_platform_l\n                is_cloudlinux = (\n                    os_platform_l == \"cloudlinux\"\n                    or os_name_l == \"cloudlinux\"\n                )\n                # AlmaLinux usa el ecosistema de CVE/RHEL y no debe quedar\n                # marcado como distro sin soporte aunque conserve un label\n                # de plataforma heredado.\n                if agent_id and is_cloudlinux and not is_almalinux:\n                    unsupported_agents[agent_id] = {\n                        \"name\": str(agent.get(\"name\") or f\"Servidor {agent_id}\")\n                    }\n\n    total = total_reported if total_reported is not None else sum(item[\"count\"] for item in results.values())\n    return {\"total\": total, \"agents\": results, \"unsupported_agents\": unsupported_agents}, None\n\ndef valid_ip(value):\n    try: ipaddress.ip_address(value); return True\n    except (ValueError, TypeError): return False\n\n\nGEOIP_CITY_DB = os.environ.get(\n    \"ORANGEBOX_GEOIP_CITY_DB\",\n    \"/var/lib/orangebox/geoip/dbip-city-lite.mmdb\",\n)\n\n\n# Reader MMDB reutilizable. Evita lanzar mmdblookup como subprocess por cada\n# IP/atributo. En reportes con miles de IPs esto genera miles de procesos.\n# Si maxminddb no está instalado, se conserva el fallback anterior.\n_GEOIP_READER = None\n_GEOIP_READER_ERROR = False\n\n\ndef _get_geoip_reader():\n    global _GEOIP_READER, _GEOIP_READER_ERROR\n\n    if _GEOIP_READER is not None or _GEOIP_READER_ERROR:\n        return _GEOIP_READER\n    if maxminddb is None or not Path(GEOIP_CITY_DB).is_file():\n        _GEOIP_READER_ERROR = True\n        return None\n    try:\n        _GEOIP_READER = maxminddb.open_database(GEOIP_CITY_DB)\n    except (OSError, ValueError):\n        _GEOIP_READER_ERROR = True\n        return None\n    return _GEOIP_READER\n\n\ndef _mmdb_country_data(ip):\n    reader = _get_geoip_reader()\n    if reader is None:\n        return None\n    try:\n        record = reader.get(str(ip))\n    except (OSError, ValueError):\n        return None\n    if not isinstance(record, dict):\n        return {}\n    country = record.get(\"country\") or {}\n    if not isinstance(country, dict):\n        return {}\n    names = country.get(\"names\") or {}\n    if not isinstance(names, dict):\n        names = {}\n    return {\n        \"country_code\": str(country.get(\"iso_code\") or \"\").upper(),\n        \"country\": str(names.get(\"es\") or names.get(\"en\") or \"\"),\n    }\n\n\ndef _mmdblookup_country_value(ip, *path):\n    \"\"\"Fallback de compatibilidad cuando maxminddb no está disponible.\"\"\"\n    if not Path(GEOIP_CITY_DB).is_file() or shutil.which(\"mmdblookup\") is None:\n        return \"\"\n    try:\n        result = subprocess.run(\n            [\"mmdblookup\", \"--file\", GEOIP_CITY_DB, \"--ip\", str(ip), *path],\n            capture_output=True,\n            text=True,\n            timeout=3,\n            check=False,\n        )\n    except (OSError, subprocess.SubprocessError):\n        return \"\"\n    if result.returncode != 0:\n        return \"\"\n    match = re.search(r'(?m)^\\s*\"((?:\\\\.|[^\"])*)\"\\s*<utf8_string>', result.stdout)\n    if not match:\n        return \"\"\n    try:\n        return json.loads(f'\"{match.group(1)}\"')\n    except json.JSONDecodeError:\n        return \"\"\n\n\ndef country_flag(country_code):\n    code = str(country_code or \"\").strip().upper()\n    if len(code) != 2 or not code.isalpha():\n        return \"🌐\"\n    return \"\".join(chr(127397 + ord(char)) for char in code)\n\n\ndef geoip_country(ip, cache=None):\n    cache = cache if cache is not None else {}\n    if ip in cache:\n        return cache[ip]\n    try:\n        if not ipaddress.ip_address(ip).is_global:\n            data = {\"country_code\": \"\", \"country\": \"IP local\", \"flag\": \"🌐\"}\n            cache[ip] = data\n            return data\n    except ValueError:\n        data = {\"country_code\": \"\", \"country\": \"No disponible\", \"flag\": \"🌐\"}\n        cache[ip] = data\n        return data\n\n    fast = _mmdb_country_data(ip)\n    if fast is not None:\n        code = str(fast.get(\"country_code\") or \"\").upper()\n        name = str(fast.get(\"country\") or \"\")\n    else:\n        code = _mmdblookup_country_value(ip, \"country\", \"iso_code\").upper()\n        name = (\n            _mmdblookup_country_value(ip, \"country\", \"names\", \"es\")\n            or _mmdblookup_country_value(ip, \"country\", \"names\", \"en\")\n        )\n    data = {\n        \"country_code\": code,\n        \"country\": name or \"No disponible\",\n        \"flag\": country_flag(code),\n    }\n    cache[ip] = data\n    return data\n\n\ndef geoip_country_map(ips):\n    cache = {}\n    for ip in set(ips):\n        geoip_country(ip, cache)\n    return cache\n\ndef geoip_country_ranking(ips, geo):\n    counts = Counter()\n    for ip in ips:\n        try:\n            if not ipaddress.ip_address(ip).is_global:\n                continue\n        except ValueError:\n            continue\n        item = geo.get(ip) or {}\n        code = str(item.get(\"country_code\") or \"\").upper()\n        name = str(item.get(\"country\") or \"No disponible\")\n        counts[(code, name)] += 1\n    return counts.most_common(10)\n\n\ndef render_country_ranking_rows(ranking):\n    rows = []\n    for position, ((code, name), count) in enumerate(ranking, start=1):\n        rows.append(\n            f\"<tr><td style='border-top:1px solid #e3e9ec;padding:7px;text-align:center;color:#78909c;font-size:11px;'>{position}</td>\"\n            f\"<td style='border-top:1px solid #e3e9ec;padding:6px;text-align:center;font-size:20px;'>{esc(country_flag(code))}</td>\"\n            f\"<td style='border-top:1px solid #e3e9ec;padding:7px;font-size:11px;font-weight:bold;'>{esc(name)}</td>\"\n            f\"<td style='border-top:1px solid #e3e9ec;padding:7px;text-align:right;font-size:12px;font-weight:bold;'>{count:,}</td></tr>\"\n        )\n    return \"\".join(rows)\n\n\ndef parse_timestamp(value):\n    if not value: return None\n    try:\n        value = re.sub(r\"([+-]\\d{2})(\\d{2})$\", r\"\\1:\\2\", str(value)); return datetime.fromisoformat(value)\n    except (TypeError, ValueError): return None\n\ndef extract_firewall_payload(full_log):\n    if not isinstance(full_log, str): return None\n    match = FIREWALL_RE.search(full_log.strip())\n    if not match: return None\n    try: return json.loads(match.group(1))\n    except json.JSONDecodeError: return None\n\ndef load_firewall_timeouts():\n    \"\"\"Lee desde ossec.conf los timeout de cada active-response firewall-drop.\n    Se procesa por bloques de texto porque ossec.conf puede contener varios\n    bloques <ossec_config>, que no forman un XML único estándar.\n    \"\"\"\n    timeouts = {}\n    try:\n        with open(WAZUH_OSSEC_CONF, \"r\", encoding=\"utf-8\", errors=\"ignore\") as handle:\n            config = handle.read()\n    except OSError:\n        return timeouts\n\n    for block in re.findall(r\"<active-response>\\s*(.*?)\\s*</active-response>\", config, flags=re.DOTALL):\n        command = re.search(r\"<command>\\s*([^<]+?)\\s*</command>\", block)\n        rules_id = re.search(r\"<rules_id>\\s*([^<]+?)\\s*</rules_id>\", block)\n        timeout = re.search(r\"<timeout>\\s*(\\d+)\\s*</timeout>\", block)\n        if not command or not rules_id or not timeout:\n            continue\n        if command.group(1).strip() != \"firewall-drop\":\n            continue\n        seconds = int(timeout.group(1))\n        for rule_id in re.split(r\"\\s*,\\s*\", rules_id.group(1).strip()):\n            if rule_id:\n                timeouts[rule_id] = seconds\n\n    # Compatibilidad histórica: 10457 era el wrapper de Active Response\n    # del SYN flood 10454. La regla 10457 ya no existe; los eventos históricos\n    # deben seguir mostrando el timeout configurado actualmente para 10454.\n    if \"10457\" not in timeouts and \"10454\" in timeouts:\n        timeouts[\"10457\"] = timeouts[\"10454\"]\n\n    return timeouts\n\ndef format_duration(seconds):\n    if seconds is None:\n        return \"No disponible\"\n    if seconds < 60:\n        return f\"{seconds}s\"\n    if seconds % 3600 == 0:\n        return f\"{seconds // 3600} h\"\n    if seconds % 60 == 0:\n        return f\"{seconds // 60} min\"\n    return f\"{seconds}s\"\n\ndef period_bounds(mode, now):\n    today = now.date()\n    if mode == \"today\": return datetime.combine(today, datetime.min.time(), now.tzinfo), now, \"Hoy\"\n    if mode == \"yesterday\":\n        day = today - timedelta(days=1); return datetime.combine(day, datetime.min.time(), now.tzinfo), datetime.combine(today, datetime.min.time(), now.tzinfo), \"Ayer\"\n    monday = today - timedelta(days=today.weekday())\n    if mode == \"thisweek\": return datetime.combine(monday, datetime.min.time(), now.tzinfo), now, \"Semana actual\"\n    if mode == \"lastweek\":\n        start = monday - timedelta(days=7); return datetime.combine(start, datetime.min.time(), now.tzinfo), datetime.combine(monday, datetime.min.time(), now.tzinfo), \"Semana anterior\"\n    first = today.replace(day=1)\n    if mode == \"thismonth\": return datetime.combine(first, datetime.min.time(), now.tzinfo), now, \"Mes actual\"\n    if mode == \"lastmonth\":\n        previous = first - timedelta(days=1); start = previous.replace(day=1); return datetime.combine(start, datetime.min.time(), now.tzinfo), datetime.combine(first, datetime.min.time(), now.tzinfo), \"Mes anterior\"\n    year = today.replace(month=1, day=1)\n    if mode == \"thisyear\": return datetime.combine(year, datetime.min.time(), now.tzinfo), now, \"Año actual\"\n    if mode == \"lastyear\":\n        start = year.replace(year=year.year - 1); return datetime.combine(start, datetime.min.time(), now.tzinfo), datetime.combine(year, datetime.min.time(), now.tzinfo), \"Año anterior\"\n    if mode.startswith(\"date:\"):\n        day = datetime.strptime(mode[5:], \"%Y-%m-%d\").date(); return datetime.combine(day, datetime.min.time(), now.tzinfo), datetime.combine(day + timedelta(days=1), datetime.min.time(), now.tzinfo), day.strftime(\"%Y-%m-%d\")\n    raise SystemExit(\"Período no válido\")\n\ndef iter_log_files(start, end):\n    paths=[]; day=start.date(); last=(end-timedelta(microseconds=1)).date()\n    while day <= last:\n        base=Path(ALERTS_ROOT)/f\"{day.year:04d}\"/day.strftime(\"%b\"); paths += [base/f\"ossec-alerts-{day.day:02d}.json.gz\", base/f\"ossec-alerts-{day.day:02d}.json\"]; day += timedelta(days=1)\n    if start.date() <= datetime.now().date() <= last: paths.append(Path(ALERTS_FILE))\n    seen=set()\n    for path in paths:\n        if path.exists() and str(path) not in seen: seen.add(str(path)); yield path\n\ndef iter_json(path):\n    opener=gzip.open if str(path).endswith(\".gz\") else open\n    with opener(path,\"rb\") as handle:\n        for line in handle:\n            try:\n                obj=orjson.loads(line) if orjson is not None else json.loads(line)\n                if isinstance(obj,dict): yield obj\n            except (json.JSONDecodeError, UnicodeDecodeError, ValueError): continue\n\ndef all_groups():\n    \"\"\"Obtiene grupos con agentes, excluyendo grupos tecnicos al usar --group all.\"\"\"\n    try:\n        process=subprocess.run([AGENT_GROUPS_BIN, \"-l\"], capture_output=True, text=True, timeout=15)\n    except (OSError,subprocess.SubprocessError) as exc:\n        raise SystemExit(f\"No se pudieron obtener los grupos Wazuh: {exc}\") from exc\n    output=process.stdout+\"\\n\"+process.stderr\n    if process.returncode != 0:\n        raise SystemExit(f\"agent_groups -l fallo: {output.strip()}\")\n    groups=[]\n    for line in output.splitlines():\n        match=re.match(r\"^\\s{2}(.+?)\\s+\\((\\d+)\\)\\s*$\", line)\n        if not match:\n            continue\n        group_name=match.group(1).strip()\n        count=int(match.group(2))\n        if count <= 0 or group_name.lower() in REPORT_NON_CLIENT_GROUPS:\n            continue\n        groups.append(group_name)\n    return groups\n\ndef group_members(group):\n    groups = [value.strip() for value in str(group).split(\",\") if value.strip()]\n    if not groups:\n        raise SystemExit(\"Debe especificar al menos un grupo Wazuh\")\n    if not os.path.exists(AGENT_GROUPS_BIN): raise SystemExit(f\"No existe {AGENT_GROUPS_BIN}\")\n\n    all_ids = set()\n    for group_name in groups:\n        try: process=subprocess.run([AGENT_GROUPS_BIN,\"-l\",\"-g\",group_name],capture_output=True,text=True,timeout=15)\n        except (OSError,subprocess.SubprocessError) as exc: raise SystemExit(f\"No se pudo consultar el grupo {group_name}: {exc}\") from exc\n        output=process.stdout+\"\\n\"+process.stderr\n        if process.returncode!=0: raise SystemExit(f\"Grupo Wazuh inválido o no disponible: {group_name}\\n{output.strip()}\")\n        ids=set(re.findall(r\"\\bID:\\s*([0-9]+)\\b\",output))\n        if ids:\n            all_ids.update(ids)\n        elif not re.search(r\"0\\s+agent\\(s\\)\",output,re.I):\n            raise SystemExit(f\"No se pudieron obtener servidores del grupo {group_name}\")\n    return all_ids\n\ndef classify(rule_id, groups, level):\n    rid=str(rule_id); group_set={str(value).lower() for value in (groups or [])}\n    if rid==FIREWALL_RULE: return \"active_response\"\n    if rid in MALWARE_RULES or group_set & MALWARE_GROUPS: return \"malware\"\n    if rid in PRIV_RULES or group_set & {\"privilege_escalation\",\"privilege_escalation_root\",\"sudo\"}: return \"privilege\"\n    if rid in WEB_RULES or group_set & WEB_GROUPS: return \"web\"\n    if rid in FIM_RULES or group_set & FIM_GROUPS: return \"fim\"\n    if rid in AUTH_RULES or group_set & AUTH_GROUPS: return \"authentication\"\n    if group_set & ATTACK_GROUPS or int(level or 0)>=12: return \"attack\"\n    return \"other\"\n\ndef parse_event(outer):\n    rule=outer.get(\"rule\") or {}; rule_id=str(rule.get(\"id\",\"\")); timestamp=parse_timestamp(outer.get(\"timestamp\"))\n    if not timestamp: return None\n    if rule_id==FIREWALL_RULE:\n        # Wazuh 4.x decodes active-responses.log into data.command +\n        # data.parameters. The previous parser expected the raw JSON payload\n        # in full_log, which made valid firewall-drop executions invisible.\n        data=outer.get(\"data\") or {}\n        command=data.get(\"command\")\n        params=data.get(\"parameters\") or {}\n\n        # En Wazuh 4.x, el evento 651 mezcla dos representaciones:\n        # command/parameters vienen estructurados en data, mientras que\n        # \"program\" y el payload completo de firewall-drop pueden permanecer\n        # únicamente dentro de full_log. Por eso no debemos exigir program\n        # dentro de data.parameters.\n        payload=extract_firewall_payload(outer.get(\"full_log\",\"\"))\n        if isinstance(payload,dict):\n            if command not in {\"add\",\"delete\"}:\n                command=payload.get(\"command\")\n            raw_params=payload.get(\"parameters\") or {}\n            if raw_params:\n                merged_params=dict(raw_params)\n                merged_params.update(params)\n                params=merged_params\n            elif payload.get(\"program\") and \"program\" not in params:\n                params=dict(params)\n                params[\"program\"]=payload.get(\"program\")\n\n        if command not in {\"add\",\"delete\"}:\n            return None\n\n        # La propia regla 651 identifica la ejecución de firewall-drop.\n        # En Wazuh 4.x \"program\" puede venir en full_log o en data.parameters;\n        # no lo usamos como condición de descarte porque la estructura puede\n        # variar entre versiones/decoders.\n        program=params.get(\"program\")\n        if not program and isinstance(payload,dict):\n            program=payload.get(\"program\")\n\n        alert=params.get(\"alert\") or {}\n        if not alert and isinstance(payload,dict):\n            alert=(payload.get(\"parameters\") or {}).get(\"alert\") or {}\n        alert_rule=alert.get(\"rule\") or {}\n        agent=alert.get(\"agent\") or {}\n        alert_data=alert.get(\"data\") or {}\n        # En los eventos 651 de Wazuh 4.x, la IP bloqueada está\n        # normalmente en data.parameters.alert.data.srcip.\n        src=alert_data.get(\"srcip\") or data.get(\"srcip\") or alert.get(\"srcip\")\n        if not src and isinstance(payload,dict):\n            payload_params=payload.get(\"parameters\") or {}\n            payload_alert=payload_params.get(\"alert\") or {}\n            payload_alert_data=payload_alert.get(\"data\") or {}\n            src=payload_alert_data.get(\"srcip\") or src\n        mitre=alert_rule.get(\"mitre\") or {}\n        return {\n            \"timestamp\":parse_timestamp(alert.get(\"timestamp\")) or timestamp,\n            \"outer_rule\":rule_id,\n            \"rule_id\":str(alert_rule.get(\"id\",\"unknown\")),\n            \"description\":standardize_rule_description(str(alert_rule.get(\"id\",\"unknown\")),alert_rule.get(\"description\",\"Firewall Drop\"),alert_rule.get(\"groups\") or []),\n            \"level\":int(alert_rule.get(\"level\",0) or 0),\n            \"groups\":alert_rule.get(\"groups\") or [],\n            \"agent_id\":str(agent.get(\"id\",\"000\")),\n            \"agent_name\":agent.get(\"name\",\"unknown\"),\n            \"srcip\":str(src) if valid_ip(src) else None,\n            \"command\":command,\n            \"alert_id\":str(alert.get(\"id\",outer.get(\"id\",\"\"))),\n            \"mitre\":mitre.get(\"id\",[]),\n            \"techniques\":mitre.get(\"technique\",[]),\n            \"url\":alert_data.get(\"url\"),\n        }\n    agent=outer.get(\"agent\") or {}; data=outer.get(\"data\") or {}; mitre=rule.get(\"mitre\") or {}\n    return {\n        \"timestamp\":timestamp,\n        \"outer_rule\":rule_id,\n        \"rule_id\":rule_id,\n        \"description\":standardize_rule_description(rule_id,rule.get(\"description\",\"Sin descripción\"),rule.get(\"groups\") or []),\n        \"level\":int(rule.get(\"level\",0) or 0),\n        \"groups\":rule.get(\"groups\") or [],\n        \"agent_id\":str(agent.get(\"id\",\"000\")),\n        \"agent_name\":agent.get(\"name\",\"unknown\"),\n        \"srcip\":str(data.get(\"srcip\")) if valid_ip(data.get(\"srcip\")) else None,\n        \"command\":None,\n        \"alert_id\":str(outer.get(\"id\",\"\")),\n        \"mitre\":mitre.get(\"id\",[]),\n        \"techniques\":mitre.get(\"technique\",[]),\n        \"url\":data.get(\"url\"),\n        \"fim_path\": str(data.get(\"path\") or ((data.get(\"syscheck\") or {}).get(\"path\")) or \"\").strip(),\n    }\n\ndef load_events(start,end,allowed):\n    files=list(iter_log_files(start,end))\n    if not files: raise SystemExit(\"No se encontraron logs JSON para el período solicitado\")\n    security_count=0; critical_count=0; source_ips=set(); agents=Counter()\n    agent_stats=defaultdict(lambda: {\"events\":0, \"high\":0, \"ips\":set(), \"attacks\":0})\n    categories={name:{\"count\":0,\"ips\":set(),\"agents\":set(),\"rules\":Counter(),\"rule_agents\":defaultdict(set)} for name in (\"authentication\",\"web\",\"fim\",\"malware\",\"privilege\",\"attack\")}\n    mitre_counts=Counter(); mitre_names={}; firewall_ips=set(); firewall_rows=defaultdict(set); firewall_attempts=Counter(); firewall_recurrence=Counter(); firewall_rules_by_ip=defaultdict(set); firewall_timeouts=load_firewall_timeouts(); timeline=Counter()\n    seen_day=None; seen=set(); today=datetime.now().date()\n    for path in files:\n        if path == Path(ALERTS_FILE): file_day=today\n        else:\n            try: file_day=datetime.strptime(f\"{path.name[13:15]} {path.parent.name} {path.parent.parent.name}\",\"%d %b %Y\").date()\n            except (ValueError, IndexError): file_day=None\n        if file_day != seen_day: seen_day=file_day; seen=set()\n        for outer in iter_json(path):\n            rule=outer.get(\"rule\") or {}; outer_rule=str(rule.get(\"id\",\"\"))\n            if outer_rule == FIREWALL_RULE:\n                # Los eventos 651 son el registro de la ejecución real de\n                # firewall-drop. Se procesan de forma independiente para no\n                # depender del decoder ni del deduplicado de alertas normales.\n                outer_ts=parse_timestamp(outer.get(\"timestamp\"))\n                data=outer.get(\"data\") or {}\n                params=data.get(\"parameters\") or {}\n                alert=params.get(\"alert\") or {}\n                command=data.get(\"command\") or params.get(\"command\")\n                payload=extract_firewall_payload(outer.get(\"full_log\",\"\"))\n                if isinstance(payload,dict):\n                    if command not in {\"add\",\"delete\"}:\n                        command=payload.get(\"command\")\n                    payload_params=payload.get(\"parameters\") or {}\n                    if not alert and isinstance(payload_params,dict):\n                        alert=payload_params.get(\"alert\") or {}\n                alert_rule=alert.get(\"rule\") or {}\n                alert_agent=alert.get(\"agent\") or {}\n                alert_data=alert.get(\"data\") or {}\n                src=alert_data.get(\"srcip\")\n                if not src and isinstance(payload,dict):\n                    payload_alert=payload.get(\"parameters\",{}).get(\"alert\") or {}\n                    src=(payload_alert.get(\"data\") or {}).get(\"srcip\")\n                    if not alert_rule: alert_rule=payload_alert.get(\"rule\") or {}\n                    if not alert_agent: alert_agent=payload_alert.get(\"agent\") or {}\n                event_ts=parse_timestamp(alert.get(\"timestamp\")) or outer_ts\n                agent_id=str(alert_agent.get(\"id\",\"000\"))\n                agent_name=alert_agent.get(\"name\",\"unknown\")\n                if (command==\"add\" and valid_ip(src) and event_ts and start<=event_ts<end\n                        and (allowed is None or agent_id in allowed)):\n                    rule_id=str(alert_rule.get(\"id\",\"unknown\"))\n                    alert_groups=alert_rule.get(\"groups\") or []\n                    alert_level=int(alert_rule.get(\"level\",0) or 0)\n                    if alert_level <= 0 or ({str(value).lower() for value in alert_groups} & REPORT_EXCLUDED_GROUPS):\n                        continue\n                    description=standardize_rule_description(rule_id,alert_rule.get(\"description\",\"Firewall Drop\"),alert_groups)\n                    row_key=(agent_id,agent_name,rule_id,description)\n                    src_str=str(src)\n                    firewall_rows[row_key].add(src_str)\n                    firewall_ips.add(src_str)\n                    firewall_recurrence[src_str] += 1\n                    firewall_rules_by_ip[src_str].add((rule_id,description))\n                continue\n            outer_ts=parse_timestamp(outer.get(\"timestamp\"))\n            if not outer_ts or outer_ts<start or outer_ts>=end: continue\n            event=parse_event(outer)\n            if not event or event[\"timestamp\"]<start or event[\"timestamp\"]>=end: continue\n            if allowed is not None and event[\"agent_id\"] not in allowed: continue\n            if report_event_exempt(event): continue\n            # Replica en el reporte de la excepción 20007: las sesiones\n            # systemd-user de usuarios como apache no son accesos interactivos.\n            if (\n                event[\"rule_id\"] == \"40101\"\n                and re.search(\n                    r\"pam_unix\\(systemd-user:session\\):\\s+session\\s+opened\",\n                    str(outer.get(\"full_log\", \"\")),\n                    flags=re.IGNORECASE,\n                )\n            ):\n                continue\n            key=event[\"alert_id\"]\n            if key:\n                if key in seen: continue\n                seen.add(key)\n            category=classify(event[\"rule_id\"],event[\"groups\"],event[\"level\"]); event_agent=(event[\"agent_id\"],event[\"agent_name\"])\n            if event[\"srcip\"]: firewall_attempts[(event[\"agent_id\"],event[\"rule_id\"],event[\"srcip\"])] += 1\n            if category==\"other\": continue\n            security_count += 1\n            timeline[event[\"timestamp\"].date()] += 1\n            if event[\"level\"]>=13: critical_count += 1\n            if event[\"srcip\"]: source_ips.add(event[\"srcip\"])\n            agents[event_agent] += 1\n            agent_info=agent_stats[event_agent]\n            agent_info[\"events\"] += 1\n            if event[\"level\"] >= 13: agent_info[\"high\"] += 1\n            if event[\"srcip\"]: agent_info[\"ips\"].add(event[\"srcip\"])\n            if category == \"attack\": agent_info[\"attacks\"] += 1\n            info=categories[category]; info[\"count\"] += 1\n            if event[\"srcip\"]: info[\"ips\"].add(event[\"srcip\"])\n            info[\"agents\"].add(event[\"agent_id\"])\n            rule_key=(event[\"rule_id\"],event[\"description\"]); info[\"rules\"][rule_key] += 1; info[\"rule_agents\"][rule_key].add(event[\"agent_name\"])\n            techniques=event.get(\"techniques\") or []\n            for index,mitre_id in enumerate(event.get(\"mitre\") or []):\n                mitre_counts[mitre_id] += 1\n                if index<len(techniques) and techniques[index]: mitre_names[mitre_id]=techniques[index]\n    firewall_result=[]\n    for key,ips in firewall_rows.items():\n        agent_id,agent_name,rule_id,description=key; attempts=sum(firewall_attempts[(agent_id,rule_id,ip)] for ip in ips)\n        if attempts==0: attempts=len(ips)\n        firewall_result.append({\"agent_id\":agent_id,\"agent_name\":agent_name,\"rule_id\":rule_id,\"description\":description,\"ips\":sorted(ips,key=lambda v:(ipaddress.ip_address(v).version,ipaddress.ip_address(v))),\"attempts\":attempts})\n    return {\"security_count\":security_count,\"critical_count\":critical_count,\"source_ips\":source_ips,\"agents\":agents,\"agent_stats\":agent_stats,\"categories\":categories,\"mitre_counts\":mitre_counts,\"mitre_names\":mitre_names,\"firewall_ips\":firewall_ips,\"firewall_rows\":sorted(firewall_result,key=lambda r:r[\"agent_name\"].lower()),\"firewall_recurrence\":firewall_recurrence,\"firewall_rules_by_ip\":firewall_rules_by_ip,\"firewall_timeouts\":firewall_timeouts,\"timeline\":timeline}\n\ndef section_rows(info):\n    merged = {}\n    for (rule_id, description), count in info[\"rules\"].most_common():\n        entry = merged.setdefault(\n            rule_id,\n            {\"description\": description, \"count\": 0, \"agents\": set()},\n        )\n        entry[\"count\"] += count\n        entry[\"agents\"].update(info[\"rule_agents\"][(rule_id, description)])\n    rows = [\n        (rule_id, entry[\"description\"], entry[\"count\"], sorted(entry[\"agents\"]))\n        for rule_id, entry in merged.items()\n    ]\n    rows.sort(key=lambda row: (-row[2], row[0]))\n    return rows[:12]\n\ndef mitre_rows(summary):\n    counts=summary[\"mitre_counts\"]; names=summary[\"mitre_names\"]\n    return [(mid,names.get(mid,\"Técnica MITRE ATT&CK\"),MITRE_DESCRIPTIONS.get(mid,\"Comportamiento asociado a una técnica de ataque o intrusión; Wazuh la vinculó con esta detección.\"),count) for mid,count in counts.most_common()]\n\ndef generate_html(summary,title,subtitle,period,group,lang=\"es\"):\n    L=labels(lang); security_count=summary[\"security_count\"]; critical_count=summary[\"critical_count\"]; all_ips=summary[\"source_ips\"]; agents=summary[\"agents\"]; agent_stats=summary[\"agent_stats\"]; categories=summary[\"categories\"]; firewall_rows=summary[\"firewall_rows\"]; firewall_ips=summary[\"firewall_ips\"]; cve_summary=summary.get(\"cve_summary\") or {}\n    bg=\"#f4f5f3\"; dark=\"#102d38\"; orange=\"#ff5a2f\"; coral=\"#ff6b4a\"; text=\"#19333e\"; muted=\"#667b84\"; border=\"#e1e5e4\"; page=[f\"<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1.0'></head><body style='margin:0;padding:0;background:{bg};font-family:Arial,Helvetica,sans-serif;color:{text};'>\"]\n    page.append(\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='width:100%;background:#f4f5f3;'>\")\n    page.append(f\"<tr><td style='height:6px;background:{orange};font-size:0;line-height:0;'>&nbsp;</td></tr>\")\n    page.append(\"<tr><td align='center' style='padding:18px 10px 34px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='width:100%;max-width:1120px;background:#ffffff;border:1px solid #e1e5e4;'>\")\n    page.append(\"<tr><td style='padding:0;background:#06141d;'>\"\n                 \"<img src='https://www.example.invalid/obox/img/banner-reporte-wazuh.png' alt='OrangeBox - Reporte de Seguridad Wazuh' width='1120' style='display:block;width:100%;max-width:1120px;height:auto;border:0;'>\"\n                 \"</td></tr>\")\n    page.append(f\"<tr><td style='padding:26px 26px 16px;'><div style='color:{orange};font-size:10px;font-weight:800;letter-spacing:1.8px;'>ORANGEBOX SECURITY · WAZUH</div><div style='font-size:30px;line-height:1.12;font-weight:800;margin-top:6px;color:{text};'>{esc(title)}</div><div style='font-size:14px;line-height:1.5;color:{muted};padding-top:7px;'>{esc(subtitle)}</div><table role='presentation' cellpadding='0' cellspacing='0' border='0' style='margin-top:16px;'><tr><td style='background:#f3f5f4;border:0;border-radius:20px;padding:9px 14px;font-size:11px;color:#526873;'><b>CLIENTE</b>&nbsp; {esc(group)}</td><td width='8'></td><td style='background:{orange};border-radius:20px;padding:9px 14px;font-size:11px;color:#ffffff;'><b>PERÍODO</b>&nbsp; {esc(period)}</td></tr></table></td></tr>\")\n    page.append(f\"<tr><td style='padding:0 28px 18px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='background:#fff7f2;border:1px solid #f2c8b9;border-left:5px solid {orange};border-radius:10px;'><tr><td style='padding:13px 15px;'><div style='font-size:12px;font-weight:800;color:{text};'>📎 INFORME DETALLADO ADJUNTO</div><div style='font-size:11px;line-height:1.45;color:#5f7178;margin-top:4px;'>Para revisar el detalle completo de las alertas, servidores y eventos, abra el archivo ZIP adjunto a este correo.</div></td></tr></table></td></tr>\")\n    page.append(\"<tr><td style='padding:0 22px 24px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='8' border='0'><tr>\")\n    metrics=[(security_count,L[\"security_events\"],\"#eef4f6\"),(critical_count,L[\"high_alerts\"],\"#fff0eb\"),(len(all_ips),L[\"source_ips\"],\"#eef6f5\"),(len(agents),L[\"systems\"],\"#f2f5f4\"),(len(firewall_ips),L[\"blocked_ips\"],\"#fff1ec\")]\n    card_width=f\"{100/len(metrics):.2f}%\";\n    for value,label,tint in metrics:\n        page.append(\n            f\"<td width='{card_width}' valign='top' style='padding:0;'>\"\n            f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='background:{tint};border:1px solid #e0e6e4;border-radius:12px;'>\"\n            f\"<tr><td style='padding:18px 12px 17px;'>\"\n            f\"<div style='font-size:30px;line-height:1;font-weight:800;color:{dark};'>{value:,}</div>\"\n            f\"<div style='font-size:9px;line-height:1.35;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:{muted};margin-top:9px;'>{esc(label)}</div>\"\n            f\"<div style='width:34px;height:4px;background:{orange};margin-top:13px;font-size:1px;line-height:4px;'>&nbsp;</div>\"\n            f\"</td></tr>\"\n            f\"</table></td>\"\n        )\n    page.append(\"</tr></table></td></tr>\")\n    def section_open(icon,heading,sub=None):\n        section=f\"<tr><td style='padding:0 22px 20px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='border:1px solid {border};border-radius:12px;background:#ffffff;'><tr><td style='background:#ffffff;border-bottom:1px solid {border};padding:15px 16px;font-size:17px;font-weight:800;color:{text};'><span style='color:{orange};font-size:13px;'>{icon}</span>&nbsp; {esc(heading)}</td></tr>\"\n        if sub: section+=f\"<tr><td style='padding:8px 14px 5px;color:#78909c;font-size:12px;'>{esc(sub)}</td></tr>\"\n        return section\n    def section_close(): return \"</table></td></tr>\"\n    geo_ips = set(all_ips) | set(firewall_ips)\n    geo = geoip_country_map(geo_ips)\n    source_country_rank = geoip_country_ranking(all_ips, geo)\n    blocked_country_rank = geoip_country_ranking(firewall_ips, geo)\n\n    source_rows = render_country_ranking_rows(source_country_rank)\n    if not source_rows:\n        source_rows = \"<tr><td colspan='4' style='padding:8px;color:#78909c;font-size:10px;'>Sin IPs públicas.</td></tr>\"\n    blocked_rows = render_country_ranking_rows(blocked_country_rank)\n    if not blocked_rows:\n        blocked_rows = \"<tr><td colspan='4' style='padding:8px;color:#78909c;font-size:10px;'>Sin IPs bloqueadas.</td></tr>\"\n\n    page.append(section_open(\n        \"🌍\",\n        \"Top países · eventos de seguridad\",\n        \"IPs públicas únicas asociadas a detecciones de seguridad del período; no implica por sí solo un ataque confirmado.\",\n    ))\n    page.append(\n        \"<tr><td style='padding:0 8px 8px;'>\"\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='8' border='0'><tr>\"\n        \"<td width='50%' valign='top' style='padding:0 4px 0 0;'>\"\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        \"<tr><td colspan='4' style='background:#102d38;color:#fff;padding:9px;font-size:11px;font-weight:800;'>Top países · eventos de seguridad</td></tr>\"\n        \"<tr><td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;width:28px;'>#</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;width:34px;text-align:center;'>FLAG</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;'>PAÍS</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;text-align:right;'>IPS</td></tr>\"\n        + source_rows +\n        \"</table></td>\"\n        \"<td width='50%' valign='top' style='padding:0 0 0 4px;'>\"\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        \"<tr><td colspan='4' style='background:#102d38;color:#fff;padding:9px;font-size:11px;font-weight:800;'>Top países · IPs bloqueadas</td></tr>\"\n        \"<tr><td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;width:28px;'>#</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;width:34px;text-align:center;'>FLAG</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;'>PAÍS</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:10px;font-weight:bold;text-align:right;'>IPS</td></tr>\"\n        + blocked_rows +\n        \"</table></td>\"\n        \"</tr></table></td></tr>\"\n    )\n    page.append(\n        \"<tr><td style='padding:0 14px 10px;color:#78909c;font-size:10px;'>\"\n        \"Las IPs de origen representan direcciones públicas asociadas a detecciones de seguridad; \"\n        \"no implican por sí solas un ataque confirmado. El segundo ranking muestra las IPs públicas \"\n        \"que activaron una respuesta automática de firewall-drop, limitado al top 10.\"\n        \"</td></tr>\"\n    )\n    page.append(section_close())\n\n    page.append(section_open(\"🛡\",L[\"firewall\"],L[\"firewall_sub\"]))\n    if firewall_rows:\n        # Agrupa las ejecuciones reales de firewall-drop por motivo de bloqueo.\n        # Una IP cuenta una sola vez dentro de cada motivo, aunque haya más de\n        # una ejecución/alerta asociada al mismo bloqueo.\n        firewall_by_reason=defaultdict(lambda: {\"ips\":set(), \"attempts\":0, \"rules\":set()})\n        for row in firewall_rows:\n            # El motivo se agrupa sin la IP dinámica incluida en la descripción.\n            # Así 400 SYN FLOOD de IPs distintas aparecen como una sola fila,\n            # conservando el total de IPs bloqueadas y de intentos detectados.\n            reason= re.sub(\n                r\"\\s+DESDE IP (?:PUBLICA|MALICIOSA CONOCIDA)\\s+\\S+\\.?$\",\n                \"\",\n                str(row[\"description\"] or \"\").strip(),\n                flags=re.IGNORECASE,\n            ).strip()\n            reason_key=(row[\"rule_id\"],reason)\n            firewall_by_reason[reason_key][\"ips\"].update(row[\"ips\"])\n            firewall_by_reason[reason_key][\"attempts\"] += row[\"attempts\"]\n            firewall_by_reason[reason_key][\"rules\"].add(row[\"rule_id\"])\n        firewall_reasons=sorted(firewall_by_reason.items(), key=lambda item:(-len(item[1][\"ips\"]), -item[1][\"attempts\"], item[0][0]))\n\n        page.append(\"<tr><td style='padding:0 8px 8px;overflow-wrap:anywhere;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n        page.append(f\"<tr><td style='background:#102d38;color:#fff;padding:10px;font-size:10px;font-weight:800;letter-spacing:.35px;'>{esc(L['reason'])}</td><td style='background:#102d38;color:#fff;padding:10px;font-size:10px;font-weight:800;letter-spacing:.35px;'>{esc(L['rule'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['blocked_ips'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['attempts'])}</td></tr>\")\n        for (rule_id,description),data in firewall_reasons:\n            page.append(f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:12px;overflow-wrap:anywhere;'>{esc(description)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-weight:bold;color:#d65d00;font-size:12px;'>{esc(rule_id)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{len(data['ips']):,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{data['attempts']:,}</td></tr>\")\n        page.append(\"</table></td></tr>\")\n    else: page.append(f\"<tr><td style='padding:10px 14px;color:#147a4a;font-size:12px;'>{esc(L['no_firewall'])}</td></tr>\")\n    page.append(f\"<tr><td style='background:#f7f9f8;border:0;border-left:4px solid {orange};border-radius:0 8px 8px 0;padding:11px 14px;color:#49616b;font-size:12px;'><b>{len(firewall_ips):,}</b> {esc(L['blocked_ips'].lower())} automáticamente · <b>{sum(row['attempts'] for row in firewall_rows):,}</b> {esc(L['attempts'].lower())} asociados a estos bloqueos.</td></tr><tr><td style='padding:0 14px 12px;color:#78909c;font-size:11px;'>{esc(L['firewall_note'])}</td></tr>\")\n    page.append(section_close())\n\n    # IPs con más de una ejecución real de firewall-drop durante el período.\n    firewall_recurrence=summary[\"firewall_recurrence\"]\n    firewall_rules_by_ip=summary[\"firewall_rules_by_ip\"]\n    firewall_timeouts=summary[\"firewall_timeouts\"]\n    firewall_agents_by_ip=defaultdict(set)\n    for row in firewall_rows:\n        for src in row[\"ips\"]:\n            firewall_agents_by_ip[src].add(row[\"agent_name\"] or \"Servidor desconocido\")\n    recidivists=[ip for ip,count in firewall_recurrence.items() if count > 1]\n    page.append(section_open(\"🔁\",L[\"recidivist\"],L[\"recidivist_sub\"]))\n    if recidivists:\n        recidivists.sort(key=lambda ip:(-firewall_recurrence[ip], ipaddress.ip_address(ip).version, int(ipaddress.ip_address(ip))))\n        page.append(\"<tr><td style='padding:0 8px 8px;overflow-wrap:anywhere;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n        page.append(f\"<tr><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>IP</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Servidor que ejecutó el bloqueo</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;white-space:nowrap;'>{esc(L['block_count'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['trigger_rules'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['ban_duration'])}</td></tr>\")\n        for src in recidivists:\n            geo_item=geo.get(src) or {}\n            ip_country=(f\"{geo_item.get('flag','🌐')} {geo_item.get('country')}\" if geo_item.get('country') and geo_item.get('country') != 'No disponible' else '🌐 No disponible')\n            rules=sorted(firewall_rules_by_ip[src], key=lambda item:item[0])\n            rule_text=\"<br>\".join(f\"<span style='font-family:monospace;color:#d65d00;font-weight:bold;'>{esc(rule_id)}</span> — {esc(description)}\" for rule_id,description in rules)\n            durations=sorted({format_duration(firewall_timeouts.get(rule_id)) for rule_id,_ in rules})\n            duration_text=\", \".join(durations)\n            agents_text=\"<br>\".join(esc(display_agent_name(name)) for name in sorted(firewall_agents_by_ip[src], key=str.lower))\n            page.append(f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-size:12px;font-weight:bold;'>{esc(src)}<br><span style='font-family:Arial,Helvetica,sans-serif;font-size:10px;font-weight:normal;color:#667b84;'>{esc(ip_country)}</span></td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;line-height:1.4;overflow-wrap:anywhere;'>{agents_text}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{firewall_recurrence[src]:,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;line-height:1.4;overflow-wrap:anywhere;'>{rule_text}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;white-space:nowrap;'>{esc(duration_text)}</td></tr>\")\n        page.append(\"</table></td></tr>\")\n        page.append(f\"<tr><td style='padding:0 14px 12px;color:#78909c;font-size:11px;'>El tiempo mostrado corresponde al <b>tiempo de bloqueo configurado en Wazuh</b> para cada regla de respuesta automática; no representa necesariamente el tiempo restante de un bloqueo histórico.</td></tr>\")\n    else:\n        page.append(\"<tr><td style='padding:10px 14px;color:#78909c;font-size:12px;'>No hubo IPs con más de una ejecución de firewall-drop durante el período.</td></tr>\")\n    page.append(section_close())\n\n    # Resumen de vulnerabilidades críticas actuales del Wazuh Indexer.\n    page.append(section_open(\"🛡\",L[\"cve\"],L[\"cve_sub\"]))\n    if cve_summary.get(\"error\"):\n        page.append(\n            f\"<tr><td style='padding:10px 14px;color:#8a3d2d;font-size:12px;'>{esc(L['cve_error'])} {esc(cve_summary['error'])}</td></tr>\"\n        )\n    else:\n        cve_total=int(cve_summary.get(\"total\",0) or 0)\n        cve_agents=cve_summary.get(\"agents\") or {}\n        page.append(\n            f\"<tr><td style='padding:0 8px 8px;color:#78909c;font-size:11px;'>\"\n            f\"<b>{cve_total:,}</b> {esc(L['cve_total'].lower())} · \"\n            f\"<b>{len(cve_agents):,}</b> {esc(L['cve_systems'].lower())}</td></tr>\"\n        )\n        unsupported_agents=cve_summary.get(\"unsupported_agents\") or {}\n        if cve_agents:\n            page.append(\"<tr><td style='padding:0 8px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n            page.append(\n                f\"<tr><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['cve_agent'])}</td>\"\n                f\"<td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;'>{esc(L['cve_count'])}</td></tr>\"\n            )\n            cve_rows=sorted(\n                cve_agents.values(),\n                key=lambda item:(-int(item.get(\"count\",0)), str(item.get(\"name\",\"\")).lower()),\n            )\n            for item in cve_rows:\n                page.append(\n                    f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;overflow-wrap:anywhere;'>{esc(display_agent_name(item.get('name') or 'Servidor desconocido'))}</td>\"\n                    f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{int(item.get('count',0)):,}</td></tr>\"\n                )\n            page.append(\"</table></td></tr>\")\n        elif not unsupported_agents:\n            page.append(f\"<tr><td style='padding:10px 14px;color:#147a4a;font-size:12px;'>{esc(L['cve_none'])}</td></tr>\")\n\n        if unsupported_agents:\n            names=\", \".join(\n                display_agent_name(item.get(\"name\") or f\"Servidor {agent_id}\")\n                for agent_id,item in sorted(\n                    unsupported_agents.items(),\n                    key=lambda item:str(item[1].get(\"name\",\"\")).lower(),\n                )\n            )\n            page.append(\n                f\"<tr><td style='padding:10px 14px;color:#8a5a20;font-size:12px;'>{esc(L['cve_unsupported'])}<br><b>Servidores:</b> {esc(names)}</td></tr>\"\n            )\n    page.append(section_close())\n\n    # Resumen de servidores: métricas derivadas de las alertas procesadas.\n    page.append(section_open(\"🖥\",L[\"servers\"],L[\"servers_sub\"]))\n    server_rows=sorted(agent_stats.items(), key=lambda item:(-item[1][\"events\"], item[0][1].lower()))\n    if server_rows:\n        page.append(\"<tr><td style='padding:0 8px 8px;overflow-wrap:anywhere;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n        page.append(f\"<tr><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Servidor</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;'>{esc(L['events'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;'>{esc(L['high'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;'>{esc(L['source_ips_col'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;text-align:center;'>{esc(L['attack_alerts'])}</td></tr>\")\n        for (agent_id,agent_name),data in server_rows[:15]:\n            page.append(f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:12px;font-weight:bold;overflow-wrap:anywhere;'>{esc(display_agent_name(agent_name))}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{data['events']:,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{data['high']:,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{len(data['ips']):,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:12px;'>{data['attacks']:,}</td></tr>\")\n        page.append(\"</table></td></tr>\")\n        if len(server_rows)>15:\n            page.append(f\"<tr><td style='padding:0 14px 12px;color:#78909c;font-size:11px;'>Mostrando los 15 servidores con más eventos de un total de {len(server_rows):,}.</td></tr>\")\n    else:\n        page.append(f\"<tr><td style='padding:10px 14px;color:#147a4a;font-size:12px;'>{esc(L['no_servers'])}</td></tr>\")\n    page.append(section_close())\n    section_labels=[(\"🔐\",L[\"access\"],\"authentication\"),(\"🌐\",L[\"web\"],\"web\"),(\"📁\",L[\"fim\"],\"fim\"),(\"🦠\",L[\"malware\"],\"malware\"),(\"🔑\",L[\"priv\"],\"privilege\"),(\"🎯\",L[\"attack\"],\"attack\")]\n    for icon,label,category in section_labels:\n        info=categories[category]; page.append(section_open(icon,label))\n        if not info[\"count\"]: page.append(f\"<tr><td style='padding:10px 14px;color:#147a4a;font-size:12px;'>{esc(L['attack_note'] if category=='attack' else L['no_activity'])}</td></tr>\")\n        else:\n            page.append(f\"<tr><td style='padding:0 8px 8px;color:#78909c;font-size:11px;'><b>{info['count']:,}</b> detecciones · <b>{len(info['ips']):,}</b> IPs · <b>{len(info['agents']):,}</b> sistemas</td></tr><tr><td style='padding:0 8px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Regla</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Descripción</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Detecciones</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Sistemas</td></tr>\")\n            for rule_id,description,count,names in section_rows(info):\n                shown=\", \".join(names[:5])+(\" …\" if len(names)>5 else \"\"); page.append(f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-weight:bold;color:#d65d00;font-size:11px;'>{esc(rule_id)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;overflow-wrap:anywhere;'>{esc(description)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:11px;'>{count:,}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;overflow-wrap:anywhere;'>{esc(shown)}</td></tr>\")\n            page.append(\"</table></td></tr>\")\n        if category==\"attack\": page.append(f\"<tr><td style='padding:0 14px 10px;color:#78909c;font-size:11px;'>{esc(L['attack_note'])}</td></tr>\")\n        page.append(section_close())\n    page.append(section_open(\"🧭\",L[\"mitre\"],\"MITRE ATT&CK\")); page.append(f\"<tr><td style='padding:8px 14px 5px;color:#78909c;font-size:11px;'>{esc(L['mitre_note'])}</td></tr>\"); mitre=mitre_rows(summary)\n    if mitre:\n        page.append(\"<tr><td style='padding:0 8px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"); page.append(f\"<tr><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['technique'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>Nombre</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['meaning'])}</td><td style='background:#29414c;color:#fff;padding:8px;font-size:11px;font-weight:bold;'>{esc(L['detections'])}</td></tr>\")\n        for mitre_id,name,meaning,count in mitre: page.append(f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-weight:bold;color:#d65d00;font-size:11px;'>{esc(mitre_id)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;'>{esc(name)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;line-height:1.35;'>{esc(meaning)}</td><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-weight:bold;font-size:11px;'>{count:,}</td></tr>\")\n        page.append(\"</table></td></tr>\")\n    else: page.append(\"<tr><td style='padding:10px 14px;color:#78909c;font-size:12px;'>No se encontraron técnicas MITRE ATT&CK en las alertas del período.</td></tr>\")\n    page.append(f\"<tr><td style='padding:10px 14px 18px;'><div style='background:#f7f9fa;border:1px solid #dce5e9;border-left:4px solid {orange};padding:10px 12px;font-size:11px;line-height:1.5;color:#526873;'>{esc(L['technical_note'])}</div></td></tr><tr><td style='background:{dark};border-top:4px solid {orange};padding:14px 20px;color:#c7d2d7;font-size:10px;'><b style='color:#fff;'>ORANGEBOX IT SERVICES</b><br>Monitoreo y seguridad de infraestructura</td></tr></table></td></tr></table></body></html>\")\n    return \"\".join(page)\n\ndef send_email(subject,body,recipient):\n    msg=MIMEMultipart(\"alternative\"); msg[\"Subject\"]=subject; msg[\"From\"]=f\"Wazuh SOC <{DEFAULT_FROM}>\"; msg[\"To\"]=recipient; msg.attach(MIMEText(\"OrangeBox Wazuh Security Activity Report.\",\"plain\",\"utf-8\")); msg.attach(MIMEText(body,\"html\",\"utf-8\"))\n    result = subprocess.run([\"/usr/sbin/sendmail\",\"-t\",\"-i\"], input=msg.as_string(), text=True, capture_output=True, timeout=10, check=False)\n    if result.returncode != 0:\n        detail = (result.stderr or result.stdout or f\"sendmail exit={result.returncode}\").strip()\n        raise RuntimeError(f\"Postfix maildrop: {detail}\")\n\ndef archive_html(body,label):\n    os.makedirs(ARCHIVE_DIR,mode=0o750,exist_ok=True); safe=re.sub(r\"[^A-Za-z0-9_.-]+\",\"_\",label); path=f\"{ARCHIVE_DIR}/security-report-{safe}.html\"\n    with open(path,\"w\",encoding=\"utf-8\") as handle: handle.write(body)\n    return path\n\ndef main():\n    parser=argparse.ArgumentParser(description=\"OrangeBox Wazuh Security Activity Report\"); modes=parser.add_mutually_exclusive_group(required=True)\n    for name in (\"today\",\"yesterday\",\"thisweek\",\"lastweek\",\"thismonth\",\"lastmonth\",\"thisyear\",\"lastyear\"): modes.add_argument(\"--\"+name,action=\"store_true\")\n    modes.add_argument(\"--date\",help=\"Día específico YYYY-MM-DD\"); parser.add_argument(\"--group\",required=True,help=\"Grupos Wazuh separados por comas\")\n    parser.add_argument(\"--email\",action=\"append\",required=True,help=\"Destinatario. Puede repetirse o contener varias direcciones separadas por comas.\"); parser.add_argument(\"--lang\",choices=(\"es\",\"en\"),default=\"es\",help=\"Idioma del informe: es o en\"); args=parser.parse_args()\n    recipients=[]\n    for value in args.email: recipients.extend(r.strip() for r in value.split(\",\") if r.strip())\n    if not recipients: raise SystemExit(\"Debe especificar al menos un destinatario\")\n    for recipient in recipients:\n        if not re.fullmatch(r\"[^\\s@]+@[^\\s@]+\",recipient): raise SystemExit(f\"Dirección de correo inválida: {recipient}\")\n    mode=args.date and f\"date:{args.date}\" or next(name for name in (\"today\",\"yesterday\",\"thisweek\",\"lastweek\",\"thismonth\",\"lastmonth\",\"thisyear\",\"lastyear\") if getattr(args,name))\n    now=datetime.now().astimezone(); start,end,label=period_bounds(mode,now)\n    groups = all_groups() if args.group.lower() == \"all\" else [value.strip() for value in args.group.split(\",\") if value.strip()]\n    if not groups:\n        raise SystemExit(\"No hay grupos Wazuh con servidores asignados para generar el reporte.\")\n    allowed=set()\n    for group in groups:\n        allowed.update(group_members(group))\n    if not allowed:\n        raise SystemExit(\"No se pudieron obtener servidores de los grupos seleccionados.\")\n    # Etiqueta visible del encabezado: usar los grupos efectivos,\n    # especialmente cuando --group all resuelve múltiples grupos.\n    group_label = \", \".join(groups)\n    summary=load_events(start,end,allowed)\n    cve_summary, cve_error = fetch_critical_cves(allowed)\n    summary[\"cve_summary\"] = cve_summary\n    if cve_error:\n        summary[\"cve_summary\"][\"error\"] = cve_error\n    period=f\"{start.strftime('%d/%m/%Y %H:%M')} — {end.strftime('%d/%m/%Y %H:%M') if end < now else 'ahora'}\"; L=labels(args.lang); body=generate_html(summary,L[\"report\"],L[\"subtitle\"],period,group_label,args.lang); archive=archive_html(body,f\"{args.group}-{mode.replace(':','-')}-{start:%Y%m%d}-{end:%Y%m%d}\")\n    subject_prefix={\n        \"today\": \"Reporte Diario de Seguridad\",\n        \"yesterday\": \"Reporte Diario de Seguridad\",\n        \"thisweek\": \"Reporte Semanal de Seguridad\",\n        \"lastweek\": \"Reporte Semanal de Seguridad\",\n        \"thismonth\": \"Reporte Mensual de Seguridad\",\n        \"lastmonth\": \"Reporte Mensual de Seguridad\",\n        \"thisyear\": \"Reporte Anual de Seguridad\",\n        \"lastyear\": \"Reporte Anual de Seguridad\",\n    }\n    subject=f\"📊 [ORANGEBOX] {subject_prefix.get(mode, 'Reporte de Seguridad')} — {args.group}\"; sent=[]; failed=[]\n    for recipient in recipients:\n        try: send_email(subject,body,recipient); sent.append(recipient)\n        except Exception as exc: failed.append((recipient,exc))\n    security=summary[\"security_count\"]; print(f\"Destinatarios enviados: {', '.join(sent) if sent else 'ninguno'}\")\n    if cve_error:\n        print(f\"CVE críticos: NO CONSULTADO — {cve_error}\")\n    else:\n        print(f\"CVE críticos: {summary['cve_summary']['total']:,} en {len(summary['cve_summary']['agents']):,} sistemas\")\n    for recipient,exc in failed: print(f\"ERROR enviando a {recipient}: {exc}\")\n    print(f\"Grupo: {args.group}\"); print(f\"Periodo: {period}\"); print(f\"Eventos de seguridad: {security}\"); print(f\"Archivo: {archive}\")\n    if failed: raise SystemExit(1)\n\nif __name__==\"__main__\": main()\n"
DETAIL_SOURCE = "#!/usr/bin/env python3\n\"\"\"OrangeBox Wazuh - Resumen detallado por grupo.\n\nReporte operativo orientado al cliente. Reutiliza el motor de extracción,\nclasificación y períodos de orangebox-security-report.py, pero presenta el\ndetalle completo por servidor.\n\nIncluye por servidor:\n- estado e IP del servidor;\n- eventos de seguridad;\n- severidad alta (12-14) y crítica (15-16);\n- detecciones clasificadas como ataque;\n- IPs de origen observadas;\n- distribución por categoría;\n- top de reglas por nombre/descripción, sin mostrar IDs;\n- IPs bloqueadas por firewall-drop y motivo;\n- técnicas MITRE observadas;\n- CVE críticos presentes en wazuh-states-vulnerabilities-*.\n\nEl reporte no modifica Wazuh ni sus configuraciones. Solo lee información.\n\nCredenciales del indexer para CVE:\n1) Variables de entorno WAZUH_INDEXER_USER / WAZUH_INDEXER_PASS, o\n2) Wazuh keystore del manager; opcionalmente variables de entorno para pruebas/override.\n\"\"\"\n\nimport argparse\nimport base64\nimport html\nimport importlib.util\nimport ipaddress\nimport os\nimport re\nimport socket\nimport ssl\nimport struct\nimport subprocess\nimport urllib.error\nimport urllib.request\nimport json\nfrom collections import Counter, defaultdict\nfrom datetime import datetime, timedelta\nfrom email.mime.multipart import MIMEMultipart\nfrom email.mime.text import MIMEText\nfrom pathlib import Path\nfrom xml.etree import ElementTree\n\nBASE_DIR = Path(__file__).resolve().parent\nREPORT_PATH = BASE_DIR / \"orangebox-security-report.py\"\nINDEXER_CONFIG = Path(\"/var/ossec/etc/orangebox-indexer.conf\")\nAGENT_CONTROL = \"/var/ossec/bin/agent_control\"\nAGENT_GROUPS = \"/var/ossec/bin/agent_groups\"\nOSSEC_CONF = Path(\"/var/ossec/etc/ossec.conf\")\nARCHIVE_DIR = Path(\"/var/ossec/reports/archive\")\nDEFAULT_FROM = \"wazuh@example.com\"\n\nLEVEL_HIGH_MIN = 12\nLEVEL_CRITICAL_MIN = 15\nTOP_RULES = 8\nTOP_MITRE = 8\n\n# Grupos funcionales/tecnicos que NO representan clientes.\n#\n# Cuando el reporte detallado se ejecuta con --group all, estos grupos\n# se excluyen para evitar que una funcion del endpoint (por ejemplo\n# cPanel o Zimbra) aparezca como si fuera un cliente.\n#\n# IMPORTANTE:\n#   Estos grupos SI pueden consultarse explicitamente con\n#   --group <grupo> para generar un reporte operacional interno.\n#\n# Un nuevo grupo funcional debe agregarse aqui antes de entrar en\n# produccion. Los grupos de clientes no necesitan registrarse aqui:\n# al solicitar --group <cliente> se consulta directamente el grupo Wazuh.\nREPORT_NON_CLIENT_GROUPS = {\n    \"default\",\n    \"cpanel\",\n    \"zimbra\",\n}\n\nCATEGORY_LABELS = {\n    \"authentication\": \"Autenticación y accesos\",\n    \"web\": \"Actividad web\",\n    \"fim\": \"Integridad de archivos\",\n    \"malware\": \"Malware / archivos sospechosos\",\n    \"privilege\": \"Escalamiento de privilegios\",\n    \"attack\": \"Detecciones de ataque\",\n    \"active_response\": \"Respuestas automáticas\",\n    \"other\": \"Otros\",\n}\n\n\ndef esc(value):\n    return html.escape(str(value), quote=True)\n\n\ndef display_agent_name(value):\n    \"\"\"Limpia prefijos visuales que no forman parte del nombre del agente.\"\"\"\n    return re.sub(r\"^\\s*(?:→|➜|➤|»|›|▶|►|⮕|➥)+\\s*\", \"\", str(value or \"\")).strip()\n\n\ndef num(value):\n    try:\n        return f\"{int(value):,}\".replace(\",\", \".\")\n    except (TypeError, ValueError):\n        return esc(value)\n\ndef fim_bucket(path):\n    \"\"\"Agrupa cambios FIM por ubicación para evitar listados interminables.\"\"\"\n    value = str(path or \"\").strip()\n    if not value:\n        return \"Ubicación no disponible\"\n    normalized = value.rstrip(\"/\") or \"/\"\n    if normalized == \"/etc\" or normalized.startswith(\"/etc/\"):\n        return \"/etc\"\n    if normalized == \"/tmp\" or normalized.startswith(\"/tmp/\") or normalized == \"/var/tmp\" or normalized.startswith(\"/var/tmp/\") or normalized == \"/dev/shm\" or normalized.startswith(\"/dev/shm/\"):\n        return \"Temporales (/tmp · /var/tmp · /dev/shm)\"\n    if normalized == \"/var/www\" or normalized.startswith(\"/var/www/\"):\n        return \"/var/www\"\n    if normalized == \"/var\" or normalized.startswith(\"/var/\"):\n        return \"/var\"\n    if normalized == \"/home\" or normalized.startswith(\"/home/\"):\n        return \"/home\"\n    if normalized == \"/opt\" or normalized.startswith(\"/opt/\"):\n        return \"/opt\"\n    if normalized == \"/usr\" or normalized.startswith(\"/usr/\"):\n        return \"/usr\"\n    if normalized == \"/root\" or normalized.startswith(\"/root/\"):\n        return \"/root\"\n    if normalized == \"/srv\" or normalized.startswith(\"/srv/\"):\n        return \"/srv\"\n    return \"Otros\"\n\n\ndef load_report_module():\n    spec = importlib.util.spec_from_file_location(\"orangebox_security_report\", REPORT_PATH)\n    if spec is None or spec.loader is None:\n        raise SystemExit(f\"No se pudo cargar {REPORT_PATH}\")\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef run_cmd(args):\n    try:\n        p = subprocess.run(args, capture_output=True, text=True, timeout=30, check=False)\n    except (OSError, subprocess.SubprocessError) as exc:\n        raise SystemExit(f\"No se pudo ejecutar {' '.join(args)}: {exc}\") from exc\n    return p.returncode, p.stdout, p.stderr\n\n\ndef parse_agent_control():\n    code, out, err = run_cmd([AGENT_CONTROL, \"-l\"])\n    if code != 0:\n        raise SystemExit(f\"agent_control -l falló: {err.strip()}\")\n    agents = {}\n    pattern = re.compile(\n        r\"^\\s*ID:\\s*(\\d+),\\s*Name:\\s*(.*?),\\s*IP:\\s*([^,]+),\\s*(.+?)\\s*$\"\n    )\n    for line in out.splitlines():\n        m = pattern.match(line)\n        if not m:\n            continue\n        agent_id, name, ip, status = m.groups()\n        agents[agent_id] = {\n            \"id\": agent_id,\n            \"name\": name.strip(),\n            \"ip\": ip.strip(),\n            \"status\": status.strip(),\n        }\n    return agents\n\n\ndef group_members(group):\n    groups = [value.strip() for value in str(group).split(\",\") if value.strip()]\n    if not groups:\n        raise SystemExit(\"Debe especificar al menos un grupo Wazuh\")\n\n    all_ids = set()\n    for group_name in groups:\n        code, out, err = run_cmd([AGENT_GROUPS, \"-l\", \"-g\", group_name])\n        if code != 0:\n            raise SystemExit(f\"No se pudo consultar grupo {group_name}: {err.strip()}\")\n\n        ids = set(re.findall(r\"\\bID:\\s*(\\d+)\\b\", out))\n        if ids:\n            all_ids.update(ids)\n        elif not re.search(r\"0\\s+agent\\(s\\)\", out, re.I):\n            raise SystemExit(f\"No se pudieron obtener servidores del grupo {group_name}\")\n\n    return all_ids\n\n\ndef all_groups():\n    \"\"\"Obtiene grupos con agentes, excluyendo grupos tecnicos al usar --group all.\"\"\"\n    try:\n        process=subprocess.run([AGENT_GROUPS, \"-l\"], capture_output=True, text=True, timeout=15)\n    except (OSError,subprocess.SubprocessError) as exc:\n        raise SystemExit(f\"No se pudieron obtener los grupos Wazuh: {exc}\") from exc\n    output=process.stdout+\"\\n\"+process.stderr\n    if process.returncode != 0:\n        raise SystemExit(f\"agent_groups -l fallo: {output.strip()}\")\n    groups=[]\n    for line in output.splitlines():\n        match=re.match(r\"^\\s{2}(.+?)\\s+\\((\\d+)\\)\\s*$\", line)\n        if not match:\n            continue\n        group_name=match.group(1).strip()\n        count=int(match.group(2))\n        if count <= 0 or group_name.lower() in REPORT_NON_CLIENT_GROUPS:\n            continue\n        groups.append(group_name)\n    return groups\n\ndef fetch_critical_cves(module, agent_ids):\n    \"\"\"Consulta CVE críticos actuales usando el mismo acceso al Indexer del reporte ejecutivo.\n\n    El índice de vulnerabilidades de esta instalación no expone\n    vulnerability.status, por lo que la consulta se limita a severity=Critical.\n    \"\"\"\n    if not agent_ids:\n        return {}, None\n\n    try:\n        settings = module.indexer_settings()\n    except RuntimeError as exc:\n        return {}, str(exc)\n\n    filters = [\n        {\"term\": {\"vulnerability.severity\": \"Critical\"}},\n        {\"terms\": {\"agent.id\": sorted(agent_ids)}},\n    ]\n    results = defaultdict(dict)\n    search_after = None\n\n    while True:\n        payload = {\n            \"size\": 1000,\n            \"track_total_hits\": False,\n            \"_source\": [\n                \"agent.id\",\n                \"agent.name\",\n                \"package.name\",\n                \"package.version\",\n                \"vulnerability.id\",\n                \"vulnerability.severity\",\n                \"vulnerability.score.base\",\n                \"vulnerability.description\",\n                \"vulnerability.reference\",\n                \"vulnerability.detected_at\",\n            ],\n            \"query\": {\n                \"bool\": {\n                    \"filter\": filters,\n                }\n            },\n            \"sort\": [\n                {\"_index\": {\"order\": \"asc\"}},\n                {\"_id\": {\"order\": \"asc\"}},\n            ],\n        }\n        if search_after is not None:\n            payload[\"search_after\"] = search_after\n\n        data, error = module.indexer_request(\n            settings,\n            \"/wazuh-states-vulnerabilities-*/_search\",\n            payload,\n        )\n        if error:\n            return {}, error\n\n        hits = ((data.get(\"hits\") or {}).get(\"hits\") or [])\n        if not hits:\n            break\n\n        for hit in hits:\n            source = hit.get(\"_source\") or {}\n            agent = source.get(\"agent\") or {}\n            vulnerability = source.get(\"vulnerability\") or {}\n            package = source.get(\"package\") or {}\n            agent_id = str(agent.get(\"id\", \"\")).strip()\n            if agent_id not in agent_ids:\n                continue\n            if str(vulnerability.get(\"severity\", \"\")).lower() != \"critical\":\n                continue\n\n            score = (vulnerability.get(\"score\") or {}).get(\"base\")\n            try:\n                score = float(score) if score is not None else None\n            except (TypeError, ValueError):\n                score = None\n\n            cve = {\n                \"id\": str(vulnerability.get(\"id\", \"\") or \"\"),\n                \"severity\": str(vulnerability.get(\"severity\", \"\") or \"\"),\n                \"score\": score,\n                \"description\": str(vulnerability.get(\"description\", \"\") or \"\"),\n                \"package\": str(package.get(\"name\", \"\") or \"\"),\n                \"version\": str(package.get(\"version\", \"\") or \"\"),\n                \"reference\": str(vulnerability.get(\"reference\", \"\") or \"\"),\n                \"detected_at\": str(vulnerability.get(\"detected_at\", \"\") or \"\"),\n            }\n            if not cve[\"id\"]:\n                continue\n\n            dedupe_key = (cve[\"id\"], cve[\"package\"], cve[\"version\"])\n            results[agent_id][dedupe_key] = cve\n\n        next_sort = hits[-1].get(\"sort\")\n        if not next_sort:\n            break\n        if next_sort == search_after:\n            return {}, \"La paginación del inventario CVE quedó sin avance.\"\n        search_after = next_sort\n        if len(hits) < 1000:\n            break\n\n    ordered = {}\n    for agent_id, values in results.items():\n        ordered[agent_id] = sorted(\n            values.values(),\n            key=lambda item: (\n                -(item[\"score\"] or 0),\n                item[\"id\"],\n                item[\"package\"],\n                item[\"version\"],\n            ),\n        )\n    return ordered, None\n\ndef fetch_cloudlinux_agents(module, agent_ids):\n    \"\"\"Identifica agentes CloudLinux desde el inventario de sistema.\"\"\"\n    if not agent_ids:\n        return set()\n\n    try:\n        settings = module.indexer_settings()\n    except RuntimeError:\n        return set()\n\n    payload = {\n        \"size\": max(1000, len(agent_ids)),\n        \"track_total_hits\": False,\n        \"_source\": [\n            \"agent.id\",\n            \"host.os.name\",\n            \"host.os.platform\",\n        ],\n        \"query\": {\n            \"bool\": {\n                \"filter\": [\n                    {\"terms\": {\"agent.id\": sorted(agent_ids)}},\n                ]\n            }\n        },\n    }\n\n    data, error = module.indexer_request(\n        settings,\n        \"/wazuh-states-inventory-system-*/_search\",\n        payload,\n    )\n    if error:\n        return set()\n\n    cloudlinux = set()\n    for hit in (data.get(\"hits\") or {}).get(\"hits\", []):\n        source = hit.get(\"_source\") or {}\n        agent = source.get(\"agent\") or {}\n        host = source.get(\"host\") or {}\n        os_info = host.get(\"os\") or {}\n        agent_id = str(agent.get(\"id\", \"\")).strip()\n        os_name = str(os_info.get(\"name\") or \"\").strip().lower()\n        os_platform = str(os_info.get(\"platform\") or \"\").strip().lower()\n        # Algunos hosts derivados de AlmaLinux pueden conservar un\n        # valor de plataforma heredado. Si el nombre/plataforma identifica\n        # AlmaLinux, se considera soportado para el inventario CVE de RHEL/AlmaLinux.\n        is_almalinux = \"almalinux\" in os_name or \"almalinux\" in os_platform\n        is_cloudlinux = (\n            os_name == \"cloudlinux\"\n            or os_platform == \"cloudlinux\"\n        )\n        if agent_id and is_cloudlinux and not is_almalinux:\n            cloudlinux.add(agent_id)\n\n    return cloudlinux\n\n\ndef source_ips(events):\n    return {e[\"srcip\"] for e in events if e.get(\"srcip\")}\n\n\ndef parse_events_for_agents(module, start, end, allowed):\n    files = list(module.iter_log_files(start, end))\n    if not files:\n        raise SystemExit(\"No se encontraron logs JSON para el período solicitado.\")\n\n    events = []\n    today = datetime.now().date()\n    seen_day = None\n    seen = set()\n\n    for path in files:\n        if path == Path(module.ALERTS_FILE):\n            file_day = today\n        else:\n            try:\n                file_day = datetime.strptime(\n                    f\"{path.name[13:15]} {path.parent.name} {path.parent.parent.name}\",\n                    \"%d %b %Y\",\n                ).date()\n            except (ValueError, IndexError):\n                file_day = None\n\n        if file_day != seen_day:\n            seen_day = file_day\n            seen = set()\n\n        for outer in module.iter_json(path):\n            outer_rule = str((outer.get(\"rule\") or {}).get(\"id\", \"\"))\n            if outer_rule != module.FIREWALL_RULE:\n                ts = module.parse_timestamp(outer.get(\"timestamp\"))\n                if not ts or ts < start or ts >= end:\n                    continue\n\n            event = module.parse_event(outer)\n            if event:\n                data = outer.get(\"data\") or {}\n                syscheck = outer.get(\"syscheck\") or data.get(\"syscheck\") or {}\n                event[\"fim_path\"] = str(syscheck.get(\"path\") or data.get(\"path\") or \"\").strip()\n            if not event or event[\"timestamp\"] < start or event[\"timestamp\"] >= end:\n                continue\n\n            if allowed is not None and event[\"agent_id\"] not in allowed:\n                continue\n\n            alert_id = event.get(\"alert_id\", \"\")\n            if alert_id:\n                if alert_id in seen:\n                    continue\n                seen.add(alert_id)\n\n            if event[\"outer_rule\"] == module.FIREWALL_RULE:\n                # Active response 10458 is included only once and is treated\n                # as a response, not as a normal security detection.\n                if event.get(\"command\") != \"add\":\n                    continue\n\n            events.append(event)\n\n    return events\n\n\ndef build_agent_stats(events, agent_info, cves):\n    by_agent = defaultdict(list)\n    for event in events:\n        by_agent[event[\"agent_id\"]].append(event)\n\n    stats = {}\n    all_ids = sorted(set(agent_info) | set(by_agent))\n    for agent_id in all_ids:\n        ev = by_agent.get(agent_id, [])\n        normal = [e for e in ev if e.get(\"outer_rule\") != module.FIREWALL_RULE]\n\n        high = sum(LEVEL_HIGH_MIN <= int(e.get(\"level\", 0)) < LEVEL_CRITICAL_MIN for e in normal)\n        critical = sum(int(e.get(\"level\", 0)) >= LEVEL_CRITICAL_MIN for e in normal)\n        attacks = sum(e.get(\"category\") == \"attack\" for e in normal)\n\n        rule_counts = Counter(\n            e.get(\"description\", \"Detección sin descripción\")\n            for e in normal\n        )\n\n        cats = Counter(e.get(\"category\", \"other\") for e in normal)\n        ips = source_ips(normal)\n\n        ip_rules = defaultdict(Counter)\n        for e in normal:\n            srcip = e.get(\"srcip\")\n            if not srcip:\n                continue\n            rule_key = (\n                str(e.get(\"rule_id\", \"unknown\")),\n                e.get(\"description\", \"Detección sin descripción\"),\n            )\n            ip_rules[srcip][rule_key] += 1\n\n        blocked = defaultdict(lambda: {\"count\": 0, \"reasons\": Counter(), \"rules\": Counter(), \"rule_reasons\": Counter()})\n        for e in ev:\n            if e.get(\"outer_rule\") != module.FIREWALL_RULE or not e.get(\"srcip\"):\n                continue\n            blocked[e[\"srcip\"]][\"count\"] += 1\n            blocked[e[\"srcip\"]][\"reasons\"][e.get(\"description\", \"Firewall Drop\")] += 1\n            blocked[e[\"srcip\"]][\"rules\"][str(e.get(\"rule_id\", \"unknown\"))] += 1\n            rule_key = (\n                str(e.get(\"rule_id\", \"unknown\")),\n                e.get(\"description\", \"Firewall Drop\"),\n            )\n            ip_rules[e[\"srcip\"]][rule_key] += 1\n            blocked[e[\"srcip\"]][\"rule_reasons\"][rule_key] += 1\n\n        mitre = Counter()\n        for e in normal:\n            values = e.get(\"mitre\") or []\n            if isinstance(values, str):\n                values = [values]\n            for m in values:\n                if m:\n                    mitre[str(m)] += 1\n\n        info = agent_info.get(\n            agent_id,\n            {\n                \"id\": agent_id,\n                \"name\": f\"Servidor {agent_id}\",\n                \"ip\": \"unknown\",\n                \"status\": \"Desconocido\",\n            },\n        )\n\n        stats[agent_id] = {\n            \"id\": agent_id,\n            \"name\": info[\"name\"],\n            \"ip\": info[\"ip\"],\n            \"status\": info[\"status\"],\n            \"events\": len(normal),\n            \"high\": high,\n            \"critical\": critical,\n            \"attacks\": attacks,\n            \"ips\": ips,\n            \"ip_rules\": ip_rules,\n            \"rules\": rule_counts,\n            \"categories\": cats,\n            \"blocked\": blocked,\n            \"mitre\": mitre,\n            \"cves\": cves.get(agent_id, []),\n        }\n    return stats\n\n\ndef empty_agent_stat(agent_id, info):\n    return {\n        \"id\": agent_id,\n        \"name\": info.get(\"name\", f\"Servidor {agent_id}\"),\n        \"ip\": info.get(\"ip\", \"unknown\"),\n        \"status\": info.get(\"status\", \"Desconocido\"),\n        \"events\": 0,\n        \"high\": 0,\n        \"critical\": 0,\n        \"attacks\": 0,\n        \"ips\": set(),\n        \"ip_rules\": defaultdict(Counter),\n        \"rules\": Counter(),\n        \"categories\": Counter(),\n        \"blocked\": defaultdict(lambda: {\"count\": 0, \"reasons\": Counter(), \"rules\": Counter(), \"rule_reasons\": Counter()}),\n        \"mitre\": Counter(),\n        \"auth_ips\": Counter(),\n        \"auth_events\": 0,\n        \"fim_events\": 0,\n        \"fim_groups\": Counter(),\n        \"fim_paths\": defaultdict(set),\n        \"cves\": [],\n        \"vd_unsupported\": False,\n    }\n\n\ndef init_agent_stats(agent_ids, agent_info):\n    stats = {}\n    for agent_id in sorted(agent_ids):\n        info = agent_info.get(\n            agent_id,\n            {\"id\": agent_id, \"name\": f\"Servidor {agent_id}\", \"ip\": \"unknown\", \"status\": \"Desconocido\"},\n        )\n        stats[agent_id] = empty_agent_stat(agent_id, info)\n    return stats\n\n\ndef accumulate_event(agent_stats, event, module):\n    agent_id = event[\"agent_id\"]\n    stat = agent_stats.get(agent_id)\n    if stat is None:\n        return\n\n    if event.get(\"outer_rule\") == module.FIREWALL_RULE:\n        srcip = event.get(\"srcip\")\n        if event.get(\"command\") != \"add\" or not srcip:\n            return\n        rule_id = str(event.get(\"rule_id\", \"unknown\"))\n        description = module.standardize(\n            rule_id,\n            event.get(\"description\", \"Firewall Drop\"),\n            event.get(\"groups\", []),\n        )\n        blocked = stat[\"blocked\"][srcip]\n        blocked[\"count\"] += 1\n        blocked[\"reasons\"][description] += 1\n        blocked[\"rules\"][rule_id] += 1\n        blocked[\"rule_reasons\"][(rule_id, description)] += 1\n        return\n\n    # El cache ya trae la categoría calculada durante la ingesta.\n    # Solo reclasificamos cuando el evento proviene de otra fuente.\n    category = event.get(\"category\") or module.classify(\n        event[\"rule_id\"],\n        event.get(\"groups\", []),\n        event.get(\"level\", 0),\n    )\n\n    # No descartar eventos que el motor no pudo categorizar.\n    # Se conservan en \"other\" para que el informe detallado no pierda\n    # actividad real de los agentes.\n    event[\"category\"] = category\n    level = int(event.get(\"level\", 0) or 0)\n    stat[\"events\"] += 1\n\n    if LEVEL_HIGH_MIN <= level < LEVEL_CRITICAL_MIN:\n        stat[\"high\"] += 1\n    elif level >= LEVEL_CRITICAL_MIN:\n        stat[\"critical\"] += 1\n\n    if category == \"attack\":\n        stat[\"attacks\"] += 1\n\n    stat[\"rules\"][event.get(\"description\", \"Detección sin descripción\")] += 1\n    stat[\"categories\"][category] += 1\n\n    srcip = event.get(\"srcip\")\n    if category == \"authentication\":\n        stat[\"auth_events\"] += 1\n        if srcip:\n            stat[\"auth_ips\"][srcip] += 1\n    if category == \"fim\" or event.get(\"fim_path\"):\n        stat[\"fim_events\"] += 1\n        path = event.get(\"fim_path\")\n        bucket = fim_bucket(path)\n        stat[\"fim_groups\"][bucket] += 1\n        if path:\n            stat[\"fim_paths\"][bucket].add(path)\n    if srcip:\n        stat[\"ips\"].add(srcip)\n        # El ranking GeoIP representa las mismas detecciones que el reporte\n        # ejecutivo: se excluyen eventos sin categoría (\"other\").\n        if category != \"other\":\n            stat[\"ip_rules\"][srcip][\n                (str(event.get(\"rule_id\", \"unknown\")), event.get(\"description\", \"Detección sin descripción\"))\n            ] += 1\n\n    values = event.get(\"mitre\") or []\n    if isinstance(values, str):\n        values = [values]\n    for technique in values:\n        if technique:\n            stat[\"mitre\"][str(technique)] += 1\n\n\ndef aggregate_events(module, start, end, allowed, agent_stats):\n    \"\"\"Agrega eventos usando la misma mecánica de extracción del reporte ejecutivo.\n\n    Se mantienen los límites de período, la exclusión de eventos no reportables,\n    la excepción systemd-user y la deduplicación diaria. Los 10458 de\n    firewall-drop se procesan como Active Response reales.\n    \"\"\"\n    files = list(module.iter_log_files(start, end))\n    if not files:\n        raise SystemExit(\"No se encontraron logs JSON para el período solicitado.\")\n\n    today = datetime.now().date()\n    seen_day = None\n    seen = set()\n\n    for path in files:\n        if path == Path(module.ALERTS_FILE):\n            file_day = today\n        else:\n            try:\n                file_day = datetime.strptime(\n                    f\"{path.name[13:15]} {path.parent.name} {path.parent.parent.name}\",\n                    \"%d %b %Y\",\n                ).date()\n            except (ValueError, IndexError):\n                file_day = None\n\n        if file_day != seen_day:\n            seen_day = file_day\n            seen = set()\n\n        for outer in module.iter_json(path):\n            rule = outer.get(\"rule\") or {}\n            outer_rule = str(rule.get(\"id\", \"\"))\n\n            if outer_rule == module.FIREWALL_RULE:\n                event = module.parse_event(outer)\n                if not event or event.get(\"command\") != \"add\":\n                    continue\n                if event[\"timestamp\"] < start or event[\"timestamp\"] >= end:\n                    continue\n                if allowed is not None and event[\"agent_id\"] not in allowed:\n                    continue\n                accumulate_event(agent_stats, event, module)\n                continue\n\n            outer_timestamp = module.parse_timestamp(outer.get(\"timestamp\"))\n            if not outer_timestamp or outer_timestamp < start or outer_timestamp >= end:\n                continue\n\n            event = module.parse_event(outer)\n            if not event or event[\"timestamp\"] < start or event[\"timestamp\"] >= end:\n                continue\n\n            if allowed is not None and event[\"agent_id\"] not in allowed:\n                continue\n\n            if module.report_event_exempt(event):\n                continue\n\n            if (\n                event[\"rule_id\"] == \"40101\"\n                and re.search(\n                    r\"pam_unix\\(systemd-user:session\\):\\s+session\\s+opened\",\n                    str(outer.get(\"full_log\", \"\")),\n                    flags=re.IGNORECASE,\n                )\n            ):\n                continue\n\n            alert_id = event[\"alert_id\"]\n            if alert_id:\n                if alert_id in seen:\n                    continue\n                seen.add(alert_id)\n\n            accumulate_event(agent_stats, event, module)\n\n\ndef period_bounds(mode, now):\n    today = now.date()\n    if mode == \"today\":\n        return datetime.combine(today, datetime.min.time(), now.tzinfo), now, \"Hoy\"\n    if mode == \"yesterday\":\n        day = today - timedelta(days=1)\n        return (\n            datetime.combine(day, datetime.min.time(), now.tzinfo),\n            datetime.combine(today, datetime.min.time(), now.tzinfo),\n            \"Ayer\",\n        )\n    monday = today - timedelta(days=today.weekday())\n    if mode == \"thisweek\":\n        return datetime.combine(monday, datetime.min.time(), now.tzinfo), now, \"Semana actual\"\n    if mode == \"lastweek\":\n        start = monday - timedelta(days=7)\n        return (\n            datetime.combine(start, datetime.min.time(), now.tzinfo),\n            datetime.combine(monday, datetime.min.time(), now.tzinfo),\n            \"Semana anterior\",\n        )\n    first = today.replace(day=1)\n    if mode == \"thismonth\":\n        return datetime.combine(first, datetime.min.time(), now.tzinfo), now, \"Mes actual\"\n    if mode == \"lastmonth\":\n        previous = first - timedelta(days=1)\n        start = previous.replace(day=1)\n        return (\n            datetime.combine(start, datetime.min.time(), now.tzinfo),\n            datetime.combine(first, datetime.min.time(), now.tzinfo),\n            \"Mes anterior\",\n        )\n    year = today.replace(month=1, day=1)\n    if mode == \"thisyear\":\n        return datetime.combine(year, datetime.min.time(), now.tzinfo), now, \"Año actual\"\n    if mode == \"lastyear\":\n        start = year.replace(year=year.year - 1)\n        return (\n            datetime.combine(start, datetime.min.time(), now.tzinfo),\n            datetime.combine(year, datetime.min.time(), now.tzinfo),\n            \"Año anterior\",\n        )\n    if mode.startswith(\"date:\"):\n        day = datetime.strptime(mode[5:], \"%Y-%m-%d\").date()\n        return (\n            datetime.combine(day, datetime.min.time(), now.tzinfo),\n            datetime.combine(day + timedelta(days=1), datetime.min.time(), now.tzinfo),\n            day.strftime(\"%Y-%m-%d\"),\n        )\n    raise SystemExit(\"Período no válido\")\n\n\ndef period_label(mode):\n    return {\n        \"today\": \"Diario\",\n        \"yesterday\": \"Diario\",\n        \"thisweek\": \"Semanal\",\n        \"lastweek\": \"Semanal\",\n        \"thismonth\": \"Mensual\",\n        \"lastmonth\": \"Mensual\",\n        \"thisyear\": \"Anual\",\n        \"lastyear\": \"Anual\",\n    }.get(mode, \"Seguridad\")\n\n\ndef load_firewall_timeouts():\n    \"\"\"Carga los tiempos de bloqueo configurados en los active-response de Wazuh.\"\"\"\n    try:\n        config = OSSEC_CONF.read_text(encoding=\"utf-8\", errors=\"replace\")\n    except OSError:\n        return {}\n\n    timeouts = {}\n    for block in re.findall(\n        r\"<active-response>\\s*(.*?)\\s*</active-response>\",\n        config,\n        flags=re.DOTALL,\n    ):\n        rules_id = re.search(\n            r\"<rules_id>\\s*(.*?)\\s*</rules_id>\",\n            block,\n            flags=re.DOTALL,\n        )\n        timeout = re.search(\n            r\"<timeout>\\s*(\\d+)\\s*</timeout>\",\n            block,\n            flags=re.DOTALL,\n        )\n        if not rules_id or not timeout:\n            continue\n\n        seconds = int(timeout.group(1))\n        for rule_id in re.split(r\"\\s*,\\s*\", rules_id.group(1).strip()):\n            if rule_id:\n                timeouts[rule_id] = seconds\n\n    # Compatibilidad histórica: 10457 era el wrapper de Active Response\n    # del SYN flood 10454. La regla 10457 ya no existe; los eventos históricos\n    # deben seguir mostrando el timeout configurado actualmente para 10454.\n    if \"10457\" not in timeouts and \"10454\" in timeouts:\n        timeouts[\"10457\"] = timeouts[\"10454\"]\n\n    return timeouts\n\n\ndef format_duration(seconds):\n    if seconds is None:\n        return \"No disponible\"\n    if seconds < 60:\n        return f\"{seconds}s\"\n    if seconds % 3600 == 0:\n        return f\"{seconds // 3600} h\"\n    if seconds % 60 == 0:\n        return f\"{seconds // 60} min\"\n    return f\"{seconds}s\"\n\n\ndef generate_html(group_sections, title, subtitle, period, total_agents, total_events, total_high, total_critical, total_attacks, vuln_error=None, mitre_descriptions=None, report_module=None):\n    logo_url = \"https://www.example.invalid/obox/img/logo-dark.png\"\n    dark = \"#102d38\"\n    orange = \"#ff5a2f\"\n    coral = \"#ff6b4a\"\n    text = \"#19333e\"\n    muted = \"#667b84\"\n    soft = \"#f4f5f3\"\n    panel = \"#f7f9f8\"\n    border = \"#e1e5e4\"\n    header_light = \"#29414c\"\n    firewall_timeouts = load_firewall_timeouts()\n\n    page = [\n        \"<!doctype html><html><head><meta charset='utf-8'>\",\n        \"<meta name='viewport' content='width=device-width,initial-scale=1'>\",\n        f\"<title>{esc(title)}</title>\",\n        \"</head><body style='margin:0;padding:0;background:{soft};color:{text};font-family:Arial,Helvetica,sans-serif;-webkit-text-size-adjust:100%;'>\",\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='width:100%;background:#f4f5f3;'>\",\n        f\"<tr><td style='height:6px;background:{orange};font-size:0;line-height:0;'>&nbsp;</td></tr>\",\n        \"<tr><td align='center' style='padding:18px 10px 34px;'>\",\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='width:100%;max-width:1120px;background:#ffffff;border:1px solid {border};'>\",\n\n        # Header corporativo alojado como imagen para máxima compatibilidad con clientes de correo.\n        \"<tr><td style='padding:0;background:#06141d;'>\",\n        \"<img src='https://www.example.invalid/obox/img/banner-reporte-wazuh.png' alt='OrangeBox - Reporte de Seguridad Wazuh' width='1120' style='display:block;width:100%;max-width:1120px;height:auto;border:0;'>\",\n        \"</td></tr>\",\n\n        # Report heading\n        \"<tr><td style='padding:26px 28px 12px;'>\",\n        f\"<div style='color:{orange};font-size:10px;font-weight:800;letter-spacing:2px;'>ORANGEBOX SECURITY · WAZUH</div>\",\n        f\"<div style='font-size:30px;line-height:1.12;font-weight:800;color:{text};margin-top:7px;'>{esc(title)}</div>\",\n        \"<table role='presentation' cellpadding='0' cellspacing='0' border='0' style='margin-top:16px;'><tr>\",\n        f\"<td style='background:{panel};border:1px solid {border};border-radius:18px;padding:8px 13px;font-size:11px;color:#526873;'><b>PERÍODO</b>&nbsp; {esc(period)}</td>\",\n        \"<td width='8'></td>\",\n        f\"<td style='background:{orange};border-radius:18px;padding:8px 13px;font-size:11px;color:#ffffff;'><b>SERVIDORES</b>&nbsp; {num(total_agents)}</td>\",\n        \"<td width='8'></td>\" if len(group_sections) > 1 else \"\",\n        \"\".join(\n            f\"<td style='background:{panel};border:1px solid {border};border-radius:18px;padding:8px 12px;font-size:10px;color:#526873;text-align:center;'><b>GRUPO</b>&nbsp; {esc(group_name)}</td><td width='6'></td>\"\n            for group_name, _ in group_sections\n        ) if len(group_sections) > 1 else \"\",\n        \"</tr></table></td></tr>\",\n\n        # Executive metric strip\n        \"<tr><td style='padding:4px 20px 22px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\",\n        \"<tr>\",\n        f\"<td style='padding:6px;'><div style='background:{panel};border:1px solid {border};border-radius:10px;text-align:center;padding:13px 8px;'><div style='font-size:24px;font-weight:800;color:{text};'>{num(total_agents)}</div><div style='font-size:9px;font-weight:800;letter-spacing:.9px;color:{muted};margin-top:3px;'>SERVIDORES</div></div></td>\",\n        f\"<td style='padding:6px;'><div style='background:{panel};border:1px solid {border};border-radius:10px;text-align:center;padding:13px 8px;'><div style='font-size:24px;font-weight:800;color:{text};'>{num(total_events)}</div><div style='font-size:9px;font-weight:800;letter-spacing:.9px;color:{muted};margin-top:3px;'>EVENTOS</div></div></td>\",\n        f\"<td style='padding:6px;'><div style='background:#fff7f2;border:1px solid #f5d7ca;border-radius:10px;text-align:center;padding:13px 8px;'><div style='font-size:24px;font-weight:800;color:{coral};'>{num(total_high)}</div><div style='font-size:9px;font-weight:800;letter-spacing:.9px;color:{muted};margin-top:3px;'>ALERTAS ALTA SEVERIDAD (12–14)</div></div></td>\",\n        f\"<td style='padding:6px;'><div style='background:#fff4ef;border:1px solid #f2c8b9;border-radius:10px;text-align:center;padding:13px 8px;'><div style='font-size:24px;font-weight:800;color:{orange};'>{num(total_critical)}</div><div style='font-size:9px;font-weight:800;letter-spacing:.9px;color:{muted};margin-top:3px;'>ALERTAS CRÍTICAS (15–16)</div></div></td>\",\n        f\"<td style='padding:6px;'><div style='background:{panel};border:1px solid {border};border-radius:10px;text-align:center;padding:13px 8px;'><div style='font-size:24px;font-weight:800;color:{text};'>{num(total_attacks)}</div><div style='font-size:9px;font-weight:800;letter-spacing:.9px;color:{muted};margin-top:3px;'>DETECCIONES DE ATAQUE</div></div></td>\",\n        \"</tr></table></td></tr>\",\n    ]\n\n\n    # CVE summary: unique CVE IDs and unique package/version combinations\n    # across the selected servers. Repeated server membership is de-duplicated.\n    cve_ids = set()\n    cve_packages = set()\n    cve_agents = set()\n    blocked_ips = set()\n    for _, stats in group_sections:\n        for agent_id, stat in stats.items():\n            blocked_ips.update(stat[\"blocked\"].keys())\n            for cve in stat[\"cves\"]:\n                if cve.get(\"id\"):\n                    cve_ids.add(str(cve[\"id\"]))\n                    cve_agents.add(agent_id)\n                package = str(cve.get(\"package\", \"\") or \"\")\n                version = str(cve.get(\"version\", \"\") or \"\")\n                if package:\n                    cve_packages.add((package, version))\n\n    page.append(\n        \"<tr><td style='padding:0 22px 20px;'>\"\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='8' border='0'>\"\n        \"<tr>\"\n        f\"<td valign='top' style='padding:14px;background:#fff1ec;border:1px solid #f0ddd7;border-radius:12px;text-align:center;'><div style='font-size:26px;font-weight:800;color:#19333e;'>{num(len(cve_ids))}</div><div style='font-size:9px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:#667b84;margin-top:6px;'>CVE críticos únicos</div></td>\"\n        f\"<td valign='top' style='padding:14px;background:#fff4ef;border:1px solid #f0ddd7;border-radius:12px;text-align:center;'><div style='font-size:26px;font-weight:800;color:#19333e;'>{num(len(blocked_ips))}</div><div style='font-size:9px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:#667b84;margin-top:6px;'>IPS BLOQUEADAS</div></td>\"\n        f\"<td valign='top' style='padding:14px;background:#eef4f6;border:1px solid #dde6e8;border-radius:12px;text-align:center;'><div style='font-size:26px;font-weight:800;color:#19333e;'>{num(len(cve_packages))}</div><div style='font-size:9px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:#667b84;margin-top:6px;'>Paquetes/versiones afectados</div></td>\"\n        f\"<td valign='top' style='padding:14px;background:#f2f5f4;border:1px solid #e0e6e4;border-radius:12px;text-align:center;'><div style='font-size:26px;font-weight:800;color:#19333e;'>{num(len(cve_agents))}</div><div style='font-size:9px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:#667b84;margin-top:6px;'>Servidores con CVE crítico</div></td>\"\n        \"</tr></table></td></tr>\",\n    )\n\n    if vuln_error:\n        page.append(\n            \"<tr><td style='padding:0 28px 18px;'><div style='background:#fff7f2;border:1px solid #f2c8b9;border-left:4px solid \"\n            f\"{orange};padding:13px 14px;font-size:12px;line-height:1.5;color:#8a3d2d;'>\"\n            f\"<b>Vulnerabilidades:</b> no fue posible consultar el inventario CVE del Wazuh indexer en esta ejecución. {esc(vuln_error)}\"\n            \"</div></td></tr>\"\n        )\n\n    # GeoIP consolidado: las IPs de origen representan detecciones de seguridad\n    # clasificadas por el reporte; las IPs bloqueadas se mantienen como ranking separado.\n    all_ip_rules = defaultdict(lambda: {\"rules\": Counter(), \"servers\": set()})\n    geo_blocked_ips = set()\n    for _, stats in group_sections:\n        for _, stat in stats.items():\n            geo_blocked_ips.update(stat.get(\"blocked\", {}).keys())\n            for ip, rules in stat.get(\"ip_rules\", {}).items():\n                for rule_key, count in rules.items():\n                    all_ip_rules[ip][\"rules\"][rule_key] += count\n                all_ip_rules[ip][\"servers\"].add(stat[\"name\"])\n\n    geo_module = report_module or load_report_module()\n    geo = geo_module.geoip_country_map(set(all_ip_rules.keys()) | geo_blocked_ips)\n    source_country_rank = geo_module.geoip_country_ranking(all_ip_rules.keys(), geo)\n    blocked_country_rank = geo_module.geoip_country_ranking(geo_blocked_ips, geo)\n\n    blocked_ip_counts = Counter()\n    for _, stats in group_sections:\n        for _, stat in stats.items():\n            for ip, data in stat.get(\"blocked\", {}).items():\n                try:\n                    if ipaddress.ip_address(ip).is_global:\n                        blocked_ip_counts[ip] += int(data.get(\"count\", 0) or 0)\n                except ValueError:\n                    continue\n    blocked_ip_top10 = blocked_ip_counts.most_common(10)\n\n    source_rows = \"\".join(\n        f\"<tr><td style='border-top:1px solid #e3e9ec;padding:7px;text-align:center;color:#78909c;font-size:11px;'>{i}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:6px;text-align:center;font-size:18px;'>{esc(geo_module.country_flag(code))}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;font-size:11px;font-weight:bold;'>{esc(name)}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;text-align:right;font-size:12px;font-weight:bold;'>{count:,}</td></tr>\"\n        for i, ((code, name), count) in enumerate(source_country_rank, 1)\n    ) or \"<tr><td colspan='4' style='padding:8px;color:#78909c;font-size:10px;'>Sin IPs públicas.</td></tr>\"\n\n    blocked_rows = \"\".join(\n        f\"<tr><td style='border-top:1px solid #e3e9ec;padding:7px;text-align:center;color:#78909c;font-size:11px;'>{i}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:6px;text-align:center;font-size:18px;'>{esc(geo_module.country_flag(code))}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;font-size:11px;font-weight:bold;'>{esc(name)}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;text-align:right;font-size:12px;font-weight:bold;'>{count:,}</td></tr>\"\n        for i, ((code, name), count) in enumerate(blocked_country_rank, 1)\n    ) or \"<tr><td colspan='4' style='padding:8px;color:#78909c;font-size:10px;'>No hubo IPs bloqueadas.</td></tr>\"\n\n    blocked_top_rows = \"\".join(\n        f\"<tr><td style='border-top:1px solid #e3e9ec;padding:7px;text-align:center;color:#78909c;font-size:11px;'>{i}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;font-family:monospace;font-size:11px;font-weight:bold;'>{esc(ip)}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:6px;text-align:center;font-size:18px;'>{esc((geo.get(ip) or {}).get('flag', '🌐'))}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;font-size:11px;font-weight:bold;'>{esc((geo.get(ip) or {}).get('country', 'No disponible'))}</td>\"\n        f\"<td style='border-top:1px solid #e3e9ec;padding:7px;text-align:right;font-size:12px;font-weight:bold;'>{num(count)}</td></tr>\"\n        for i, (ip, count) in enumerate(blocked_ip_top10, 1)\n    ) or \"<tr><td colspan='5' style='padding:8px;color:#78909c;font-size:10px;'>No hubo IPs bloqueadas automáticamente.</td></tr>\"\n\n    page.append(\n        f\"<tr><td style='padding:0 22px 20px;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='border:1px solid {border};border-radius:12px;background:#ffffff;'>\"\n        f\"<tr><td style='padding:12px 10px;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>\"\n        f\"<td valign='top' width='50%' style='padding:0 6px 0 0;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        f\"<tr><td style='background:#ffffff;border-bottom:1px solid {border};padding:13px 14px;font-size:16px;font-weight:800;color:{text};'><span style='color:{orange};font-size:13px;'>🌍</span>&nbsp; Top países · eventos de seguridad</td></tr>\"\n        f\"<tr><td style='padding:7px 10px 5px;color:#78909c;font-size:10px;'>IPs públicas únicas asociadas a detecciones de seguridad.</td></tr>\"\n        \"<tr><td style='padding:0 4px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        \"<tr><td style='background:#102d38;color:#fff;padding:6px;font-size:9px;font-weight:bold;width:24px;'>#</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;width:28px;text-align:center;'>FLAG</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;'>PAÍS</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;text-align:right;'>IPS</td></tr>\"\n        f\"{source_rows}\"\n        \"</table></td></tr>\"\n        \"</table></td>\"\n        f\"<td valign='top' width='50%' style='padding:0 0 0 6px;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        f\"<tr><td style='background:#ffffff;border-bottom:1px solid {border};padding:13px 14px;font-size:16px;font-weight:800;color:{text};'><span style='color:{orange};font-size:13px;'>🛡</span>&nbsp; Top 10 · IPs bloqueadas</td></tr>\"\n        f\"<tr><td style='padding:7px 10px 5px;color:#78909c;font-size:10px;'>IPs públicas con más ejecuciones de firewall-drop durante el período.</td></tr>\"\n        \"<tr><td style='padding:0 4px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n        \"<tr><td style='background:#102d38;color:#fff;padding:6px;font-size:9px;font-weight:bold;width:24px;'>#</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;'>IP</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;width:28px;text-align:center;'>FLAG</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;'>PAÍS</td>\"\n        \"<td style='background:#29414c;color:#fff;padding:6px;font-size:9px;font-weight:bold;text-align:right;'>BLOQUEOS</td></tr>\"\n        f\"{blocked_top_rows}\"\n        \"</table></td></tr>\"\n        \"</table></td></tr></table>\"\n        \"</td></tr></table></td></tr>\"\n    )\n\n    blocked_detail = defaultdict(lambda: {\"reasons\": Counter(), \"rules\": Counter(), \"rule_reasons\": Counter(), \"servers\": set(), \"count\": 0})\n    for _, stats in group_sections:\n        for _, stat in stats.items():\n            for ip, data in stat.get(\"blocked\", {}).items():\n                blocked_detail[ip][\"count\"] += int(data.get(\"count\", 0) or 0)\n                blocked_detail[ip][\"servers\"].add(stat[\"name\"])\n                for reason, count in data.get(\"reasons\", {}).items():\n                    normalized_reason = re.sub(\n                        r\"\\s+DESDE IP (?:PUBLICA|MALICIOSA CONOCIDA)\\s+\\S+\\.?$\",\n                        \"\",\n                        str(reason or \"\").strip(),\n                        flags=re.IGNORECASE,\n                    ).strip()\n                    blocked_detail[ip][\"reasons\"][normalized_reason] += count\n                for rule_id, count in data.get(\"rules\", {}).items():\n                    blocked_detail[ip][\"rules\"][str(rule_id)] += count\n                for (rule_id, reason), count in data.get(\"rule_reasons\", {}).items():\n                    normalized_reason = re.sub(\n                        r\"\\s+DESDE IP (?:PUBLICA|MALICIOSA CONOCIDA)\\s+\\S+\\.?$\",\n                        \"\",\n                        str(reason or \"\").strip(),\n                        flags=re.IGNORECASE,\n                    ).strip()\n                    blocked_detail[ip][\"rule_reasons\"][\n                        (str(rule_id), normalized_reason)\n                    ] += count\n\n    blocked_ips_ranked = sorted(\n        blocked_detail,\n        key=lambda ip: (-blocked_detail[ip][\"count\"], ipaddress.ip_address(ip).version, int(ipaddress.ip_address(ip))),\n    )\n\n    page.append(\n        f\"<tr><td style='padding:0 22px 20px;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='border:1px solid {border};border-radius:12px;background:#ffffff;'>\"\n        f\"<tr><td style='background:#ffffff;border-bottom:1px solid {border};padding:15px 16px;font-size:17px;font-weight:800;color:{text};'><span style='color:{orange};font-size:13px;'>🛡</span>&nbsp; IPs bloqueadas automáticamente</td></tr>\"\n        f\"<tr><td style='padding:8px 14px 5px;color:#78909c;font-size:11px;'>Cada IP aparece una sola vez, mostrando bandera, país, servidores que ejecutaron el bloqueo, tipo de regla y cantidad de bloqueos registrados.</td></tr>\"\n    )\n    if blocked_ips_ranked:\n        page.append(\"<tr><td style='padding:0 8px 8px;overflow-wrap:anywhere;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n        page.append(\n            f\"<tr><td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:100px;white-space:nowrap;'>IP</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:17%;'>PAÍS</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:20%;'>SERVIDORES</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;text-align:center;width:105px;white-space:nowrap;'>TIEMPO DE BANEO</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:31%;'>TIPO DE REGLA</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;text-align:right;width:70px;'>BLOQUEOS</td></tr>\"\n        )\n        for ip in blocked_ips_ranked:\n            item = geo.get(ip) or {}\n            country = f\"{item.get('flag', '🌐')} {item.get('country', 'No disponible')}\" if item.get(\"country\") and item.get(\"country\") != \"No disponible\" else \"🌐 No disponible\"\n            servers = \"<br>\".join(esc(display_agent_name(name)) for name in sorted(blocked_detail[ip][\"servers\"], key=str.lower))\n            rule_reasons = sorted(\n                blocked_detail[ip][\"rule_reasons\"].items(),\n                key=lambda item: (item[0][0], item[0][1]),\n            )\n            reasons = \"<br>\".join(\n                f\"<span style='font-family:monospace;color:#d65d00;font-weight:800;'>{esc(rule_id)}</span> — {esc(reason)}\"\n                for (rule_id, reason), _count in rule_reasons\n            )\n            durations = sorted(\n                {\n                    format_duration(firewall_timeouts.get(rule_id))\n                    for rule_id in blocked_detail[ip][\"rules\"]\n                }\n            )\n            duration_text = \", \".join(durations) if durations else \"No disponible\"\n            page.append(\n                f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-size:11px;font-weight:bold;white-space:nowrap;width:100px;'>{esc(ip)}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;font-weight:bold;'>{esc(country)}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:10px;line-height:1.45;overflow-wrap:anywhere;'>{servers}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:center;font-size:10px;white-space:nowrap;font-weight:800;color:{orange};width:105px;'>{esc(duration_text)}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:10px;line-height:1.45;'>{reasons}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;text-align:right;font-weight:800;font-size:11px;color:{text};'>{num(blocked_detail[ip]['count'])}</td></tr>\"\n            )\n        page.append(\"</table></td></tr>\")\n    else:\n        page.append(\"<tr><td style='padding:10px 14px;color:#78909c;font-size:12px;'>No se registraron bloqueos automáticos durante el período.</td></tr>\")\n    page.append(\n        \"<tr><td style='padding:0 14px 18px;color:#78909c;font-size:10px;'>\"\n        \"La columna TIEMPO DE BANEO muestra el tiempo de bloqueo configurado en Wazuh para las reglas que activaron cada bloqueo. No representa el tiempo restante de un bloqueo histórico.\"\n        \"</td></tr></table></td></tr>\"\n    )\n\n    page.append(\n        f\"<tr><td style='padding:0 22px 20px;'>\"\n        f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='border:1px solid {border};border-radius:12px;background:#ffffff;'>\"\n        f\"<tr><td style='background:#ffffff;border-bottom:1px solid {border};padding:15px 16px;font-size:17px;font-weight:800;color:{text};'><span style='color:{orange};font-size:13px;'>🔎</span>&nbsp; IPs de origen · reglas detectadas</td></tr>\"\n        f\"<tr><td style='padding:8px 14px 5px;color:#78909c;font-size:11px;'>Cada IP aparece una sola vez, agrupando las reglas, tipos de detección y servidores que registraron esa IP durante el período.</td></tr>\"\n    )\n\n    ranked_ips = sorted(\n        all_ip_rules,\n        key=lambda ip: (\n            -sum(all_ip_rules[ip][\"rules\"].values()),\n            -len(all_ip_rules[ip][\"servers\"]),\n            ipaddress.ip_address(ip).version,\n            int(ipaddress.ip_address(ip)),\n        ),\n    )\n    max_detail_ips = int(os.environ.get(\"ORANGEBOX_DETAILED_GEOIP_MAX_IPS\", \"200\"))\n    ranked_ips = ranked_ips[:max_detail_ips]\n\n    if ranked_ips:\n        page.append(\"<tr><td style='padding:0 8px 8px;overflow-wrap:anywhere;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\")\n        page.append(\n            f\"<tr><td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:110px;white-space:nowrap;'>IP</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:19%;'>PAÍS</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;width:21%;'>SERVIDORES</td>\"\n            f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>TIPOS / REGLAS DETECTADAS</td></tr>\"\n        )\n        for ip in ranked_ips:\n            item = geo.get(ip) or {}\n            country = (\n                f\"{item.get('flag', '🌐')} {item.get('country', 'No disponible')}\"\n                if item.get(\"country\") and item.get(\"country\") != \"No disponible\"\n                else \"🌐 No disponible\"\n            )\n            rule_items = []\n            for (rule_id, description), count in all_ip_rules[ip][\"rules\"].most_common(6):\n                rule_items.append(\n                    f\"<div style='margin-bottom:3px;'><span style='font-family:monospace;color:#d65d00;font-weight:800;'>{esc(rule_id)}</span>\"\n                    f\" — {esc(description)} <span style='color:#78909c;'>({num(count)})</span></div>\"\n                )\n            if len(all_ip_rules[ip][\"rules\"]) > 6:\n                rule_items.append(\n                    f\"<div style='color:#78909c;font-size:10px;'>+ {len(all_ip_rules[ip]['rules']) - 6} reglas adicionales</div>\"\n                )\n            agent_items = \"<br>\".join(esc(display_agent_name(name)) for name in sorted(all_ip_rules[ip][\"servers\"], key=str.lower))\n            page.append(\n                f\"<tr><td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-family:monospace;font-size:11px;font-weight:bold;white-space:nowrap;width:110px;'>{esc(ip)}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:11px;font-weight:bold;'>{esc(country)}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:10px;line-height:1.45;overflow-wrap:anywhere;'>{agent_items}</td>\"\n                f\"<td valign='top' style='border-top:1px solid #e3e9ec;padding:8px;font-size:10px;line-height:1.45;'>{''.join(rule_items)}</td></tr>\"\n            )\n        page.append(\"</table></td></tr>\")\n        if len(all_ip_rules) > max_detail_ips:\n            page.append(\n                f\"<tr><td style='padding:0 14px 12px;color:#78909c;font-size:11px;'>\"\n                f\"Mostrando las {max_detail_ips} IPs con más detecciones de un total de {len(all_ip_rules):,} IPs de origen.</td></tr>\"\n            )\n    else:\n        page.append(\"<tr><td style='padding:10px 14px;color:#78909c;font-size:12px;'>No se encontraron IPs públicas de origen durante el período.</td></tr>\")\n\n    page.append(\n        \"<tr><td style='padding:0 14px 18px;color:#78909c;font-size:10px;'>\"\n        \"<b>GeoIP:</b> DB-IP. La geolocalización es aproximada y no representa necesariamente la ubicación física real del origen.\"\n        \"</td></tr></table></td></tr>\"\n    )\n\n    for group_name, stats in group_sections:\n        page.append(\n            \"<tr><td style='padding:14px 20px 8px;'>\"\n            f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='border-bottom:1px solid {border};'><tr>\"\n            f\"<td style='padding:12px 6px 14px;color:{text};font-size:22px;font-weight:800;'>{esc(group_name)}</td>\"\n            \"</tr></table></td></tr>\"\n        )\n\n        if not stats:\n            page.append(\n                \"<tr><td style='padding:8px 26px 24px;color:#78909c;font-size:12px;'>Grupo sin servidores asignados.</td></tr>\"\n            )\n            continue\n\n        for agent_id in sorted(stats, key=lambda k: stats[k][\"name\"].lower()):\n            s = stats[agent_id]\n            page.extend([\n                \"<tr><td style='padding:0 20px 24px;'>\"\n                f\"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' style='background:#ffffff;border:1px solid {border};border-radius:12px;'>\"\n                f\"<tr><td style='background:{dark};padding:15px 16px;border-left:5px solid {orange};'>\"\n                f\"<div style='font-size:17px;line-height:1.25;font-weight:800;color:#ffffff;'>{esc(display_agent_name(s['name']))}</div>\"\n                f\"<div style='font-size:10px;color:#b8c5cb;margin-top:4px;'>ID {esc(s['id'])} &nbsp;·&nbsp; {esc(s['ip'])}</div>\"\n                f\"<div style='display:inline-block;background:#1d414e;color:#d8e1e4;border:1px solid #3c5963;border-radius:14px;padding:4px 9px;margin-top:8px;font-size:9px;font-weight:800;letter-spacing:.5px;'>ESTADO: {esc(s['status'])}</div>\"\n                \"</td></tr>\",\n\n                # Resumen del servidor: primero, breve y visible.\n                f\"<tr><td style='padding:10px 16px 2px;'><div style='font-size:14px;font-weight:800;color:{text};'>Resumen del servidor</div></td></tr>\",\n\n                # Server metric cards\n                \"<tr><td style='padding:12px 12px 4px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>\",\n                f\"<td style='padding:4px;'><div style='background:{panel};border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{text};'>{num(s['events'])}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>EVENTOS</div></div></td>\",\n                f\"<td style='padding:4px;'><div style='background:#fff7f2;border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{coral};'>{num(s['high'])}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>ALERTAS ALTA SEVERIDAD (12–14)</div></div></td>\",\n                f\"<td style='padding:4px;'><div style='background:#fff4ef;border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{orange};'>{num(s['critical'])}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>ALERTAS CRÍTICAS (15–16)</div></div></td>\",\n                f\"<td style='padding:4px;'><div style='background:{panel};border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{text};'>{num(s['attacks'])}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>DETECCIONES DE ATAQUE</div></div></td>\",\n                f\"<td style='padding:4px;'><div style='background:{panel};border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{text};'>{num(len(s['ips']))}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>IPS ORIGEN</div></div></td>\",\n                f\"<td style='padding:4px;'><div style='background:{panel};border-radius:9px;text-align:center;padding:10px 5px;'><div style='font-size:19px;font-weight:800;color:{text};'>{num(len(s['blocked']))}</div><div style='font-size:8px;color:{muted};font-weight:800;letter-spacing:.7px;'>IPS BLOQUEADAS</div></div></td>\",\n                \"</tr></table></td></tr>\",\n            ])\n\n            # Top rules by human-readable description\n            page.append(\n                \"<tr><td style='padding:10px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n                f\"<tr><td colspan='2' style='padding:7px 0 8px;border-bottom:2px solid {orange};font-size:14px;font-weight:800;color:{text};'>Principales detecciones</td></tr>\"\n            )\n            for description, count in s[\"rules\"].most_common(TOP_RULES):\n                page.append(\n                    f\"<tr><td style='padding:7px 5px;border-bottom:1px solid #edf1f3;font-size:11px;line-height:1.4;color:{text};'>{esc(description)}</td>\"\n                    f\"<td style='padding:7px 5px;border-bottom:1px solid #edf1f3;text-align:right;font-weight:800;font-size:11px;color:{text};'>{num(count)}</td></tr>\"\n                )\n            if not s[\"rules\"]:\n                page.append(\n                    \"<tr><td colspan='2' style='padding:8px 5px;color:#78909c;font-size:11px;'>Sin reglas de detección durante el período.</td></tr>\"\n                )\n            page.append(\"</table></td></tr>\")\n\n            # MITRE\n            page.append(\n                \"<tr><td style='padding:10px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n                f\"<tr><td colspan='2' style='padding:7px 0 8px;border-bottom:2px solid {orange};font-size:14px;font-weight:800;color:{text};'>Técnicas MITRE observadas</td></tr>\"\n            )\n            if s[\"mitre\"]:\n                page.append(\n                    f\"<tr><td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>TÉCNICA</td>\"\n                    f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>DESCRIPCIÓN</td>\"\n                    f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;text-align:right;'>ALERTAS</td></tr>\"\n                )\n                for technique, count in s[\"mitre\"].most_common(TOP_MITRE):\n                    description = (mitre_descriptions or {}).get(\n                        str(technique),\n                        \"Descripción no disponible en el catálogo MITRE del reporte.\",\n                    )\n                    page.append(\n                        f\"<tr><td style='padding:7px 5px;border-bottom:1px solid #edf1f3;font-family:monospace;font-size:11px;color:{text};vertical-align:top;'>{esc(technique)}</td>\"\n                        f\"<td style='padding:7px 5px;border-bottom:1px solid #edf1f3;font-size:11px;line-height:1.35;color:{text};vertical-align:top;'>{esc(description)}</td>\"\n                        f\"<td style='padding:7px 5px;border-bottom:1px solid #edf1f3;text-align:right;font-weight:800;font-size:11px;color:{text};vertical-align:top;'>{num(count)}</td></tr>\"\n                    )\n            else:\n                page.append(\n                    \"<tr><td colspan='2' style='padding:8px 5px;color:#78909c;font-size:11px;'>Sin técnicas MITRE observadas durante el período.</td></tr>\"\n                )\n            page.append(\"</table></td></tr>\")\n\n            # FIM summary by location\n            page.append(\n                \"<tr><td style='padding:10px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n                f\"<tr><td colspan='3' style='padding:7px 0 8px;border-bottom:2px solid {orange};font-size:14px;font-weight:800;color:{text};'>Integridad de archivos · resumen FIM</td></tr>\"\n                \"<tr><td colspan='3' style='padding:0 5px 8px;color:#78909c;font-size:10px;'>Cambios FIM agrupados por ubicación para mostrar tendencias sin llenar el informe con cientos de archivos.</td></tr>\"\n            )\n            if s[\"fim_groups\"]:\n                page.append(\n                    f\"<tr><td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>UBICACIÓN</td>\"\n                    f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;text-align:right;'>EVENTOS</td>\"\n                    f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;text-align:right;'>RUTAS ÚNICAS</td></tr>\"\n                )\n                for bucket, count in s[\"fim_groups\"].most_common():\n                    page.append(\n                        f\"<tr><td style='padding:7px 5px;border-bottom:1px solid #edf1f3;font-size:11px;color:{text};'>{esc(bucket)}</td>\"\n                        f\"<td style='padding:7px 5px;border-bottom:1px solid #edf1f3;text-align:right;font-weight:800;font-size:11px;color:{text};'>{num(count)}</td>\"\n                        f\"<td style='padding:7px 5px;border-bottom:1px solid #edf1f3;text-align:right;font-weight:800;font-size:11px;color:{text};'>{num(len(s['fim_paths'].get(bucket, set())))}</td></tr>\"\n                    )\n            else:\n                page.append(\"<tr><td colspan='3' style='padding:8px 5px;color:#78909c;font-size:11px;'>Sin cambios FIM durante el período.</td></tr>\")\n            page.append(\"</table></td></tr>\")\n\n            # Critical CVEs\n            page.append(\n                \"<tr><td style='padding:10px 16px 18px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>\"\n                f\"<tr><td colspan='4' style='padding:7px 0 8px;border-bottom:2px solid {orange};font-size:14px;font-weight:800;color:{text};'>CVE críticos en inventario</td></tr>\"\n                f\"<tr><td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>CVE</td>\"\n                f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>Software</td>\"\n                f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>CVSS</td>\"\n                f\"<td style='background:{header_light};color:#fff;padding:8px;font-size:10px;font-weight:800;'>Descripción</td></tr>\"\n            )\n            if vuln_error:\n                page.append(\n                    \"<tr><td colspan='4' style='padding:8px 5px;color:#8a3d2d;font-size:11px;line-height:1.4;'>\"\n                    f\"No fue posible consultar los CVE de este servidor: {esc(vuln_error)}\"\n                    \"</td></tr>\"\n                )\n            elif s.get(\"vd_unsupported\"):\n                page.append(\n                    f\"<tr><td colspan='4' style='padding:8px 5px;color:#8a5a20;font-size:11px;line-height:1.4;'><b>CloudLinux:</b> Wazuh no realiza actualmente evaluación nativa de vulnerabilidades para esta distribución; el resultado no corresponde interpretarlo como ausencia de CVE.</td></tr>\"\n                )\n            elif s[\"cves\"]:\n                for cve in s[\"cves\"]:\n                    desc = cve[\"description\"] or \"Sin descripción disponible.\"\n                    if len(desc) > 260:\n                        desc = desc[:257] + \"...\"\n                    package = cve[\"package\"]\n                    if cve[\"version\"]:\n                        package = f\"{package} {cve['version']}\"\n                    score = \"-\" if cve[\"score\"] is None else f\"{cve['score']:.1f}\"\n                    page.append(\n                        f\"<tr><td style='padding:7px;border-bottom:1px solid #edf1f3;font-family:monospace;font-size:11px;font-weight:800;color:{text};'>{esc(cve['id'])}</td>\"\n                        f\"<td style='padding:7px;border-bottom:1px solid #edf1f3;font-size:10px;color:{text};'>{esc(package)}</td>\"\n                        f\"<td style='padding:7px;border-bottom:1px solid #edf1f3;text-align:center;font-weight:800;font-size:11px;color:{orange};'>{esc(score)}</td>\"\n                        f\"<td style='padding:7px;border-bottom:1px solid #edf1f3;font-size:10px;line-height:1.4;color:{text};'>{esc(desc)}</td></tr>\"\n                    )\n            elif not vuln_error:\n                page.append(\n                    \"<tr><td colspan='4' style='padding:8px 5px;color:#147a4a;font-size:11px;'>No se registran CVE críticos en el inventario consultado.</td></tr>\"\n                )\n            page.append(\"</table></td></tr></table></td></tr>\")\n\n    page.extend([\n        f\"<tr><td style='background:{dark};border-top:4px solid {orange};padding:18px 22px;color:#c7d2d7;font-size:10px;line-height:1.5;'>\"\n        \"<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>\",\n        \"<td valign='middle' style='width:60%;'><b style='color:#ffffff;font-size:11px;'>ORANGEBOX IT SERVICES</b><br>Monitoreo y seguridad de infraestructura</td>\",\n        \"<td valign='middle' align='right' style='font-size:9px;color:#93aab3;letter-spacing:.7px;'>LINUX · INFRA · SECURITY</td>\",\n        \"</tr></table></td></tr>\",\n        \"</table></td></tr></table></body></html>\"\n    ])\n    return \"\".join(page)\n\n\ndef generate_plain(group_sections, period, total_agents, total_events, total_high, total_critical, total_attacks, vuln_error=None):\n    lines = [\n        \"OrangeBox — Resumen de Seguridad por Grupo\",\n        f\"Período: {period}\",\n        f\"Servidores: {total_agents} | Eventos de seguridad: {total_events} | Alertas alta severidad (12–14): {total_high} | Alertas críticas (15–16): {total_critical} | Detecciones de ataque: {total_attacks}\",\n        \"\",\n    ]\n\n    # CVE summary uses unique CVE IDs and unique package/version pairs.\n    cve_ids = set()\n    cve_packages = set()\n    cve_agents = set()\n    for _, stats in group_sections:\n        for agent_id, stat in stats.items():\n            for cve in stat[\"cves\"]:\n                if cve.get(\"id\"):\n                    cve_ids.add(str(cve[\"id\"]))\n                    cve_agents.add(agent_id)\n                package = str(cve.get(\"package\", \"\") or \"\")\n                version = str(cve.get(\"version\", \"\") or \"\")\n                if package:\n                    cve_packages.add((package, version))\n\n    lines.insert(\n        4,\n        f\"CVE críticos únicos: {len(cve_ids)} | Paquetes/versiones afectados: {len(cve_packages)} | Servidores con CVE crítico: {len(cve_agents)}\",\n    )\n\n    for group_name, stats in group_sections:\n        lines += [f\"GRUPO: {group_name}\", \"-\" * 72]\n        if not stats:\n            lines.append(\"Grupo sin servidores asignados.\")\n            lines.append(\"\")\n            continue\n        for agent_id in sorted(stats, key=lambda k: stats[k][\"name\"].lower()):\n            s = stats[agent_id]\n            lines += [\n                f\"{display_agent_name(s['name'])} (ID {agent_id}) | {s['status']} | IP {s['ip']}\",\n                f\"  Eventos: {s['events']} | Alta: {s['high']} | Críticas: {s['critical']} | Ataques: {s['attacks']} | IPs: {len(s['ips'])} | Bloqueadas: {len(s['blocked'])}\",\n                \"  Top detecciones:\",\n            ]\n            for desc, count in s[\"rules\"].most_common(TOP_RULES):\n                lines.append(f\"    - {desc}: {count}\")\n            if s[\"blocked\"]:\n                lines.append(\"  IPs bloqueadas:\")\n                for ip, data in s[\"blocked\"].items():\n                    reason = \"; \".join(r for r, _ in data[\"reasons\"].most_common(3))\n                    lines.append(f\"    - {ip}: {reason}\")\n            if vuln_error:\n                lines.append(f\"  CVE críticos en inventario: NO CONSULTADO — {vuln_error}\")\n            elif s.get(\"vd_unsupported\"):\n                lines.append(\"  Vulnerabilidades: CloudLinux — Wazuh no realiza actualmente evaluación nativa de vulnerabilidades para esta distribución.\")\n            else:\n                lines.append(f\"  CVE críticos del inventario: {len(s['cves'])}\")\n            for cve in s[\"cves\"] if not vuln_error else []:\n                lines.append(f\"    - {cve['id']} | {cve['package']} {cve['version']} | CVSS {cve['score'] or '-'}\")\n            lines.append(\"\")\n    return \"\\n\".join(lines)\n\n\ndef archive_html(body, filename):\n    ARCHIVE_DIR.mkdir(parents=True, exist_ok=True)\n    path = ARCHIVE_DIR / f\"{filename}.html\"\n    tmp = path.with_suffix(\".html.tmp\")\n    tmp.write_text(body, encoding=\"utf-8\")\n    os.replace(tmp, path)\n    return path\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"OrangeBox Wazuh Group Security Report\")\n    modes = parser.add_mutually_exclusive_group(required=True)\n    for name in (\"today\", \"yesterday\", \"thisweek\", \"lastweek\", \"thismonth\", \"lastmonth\", \"thisyear\", \"lastyear\"):\n        modes.add_argument(\"--\" + name, action=\"store_true\")\n    modes.add_argument(\"--date\", help=\"Día específico YYYY-MM-DD\")\n    parser.add_argument(\"--group\", required=True, help=\"Grupos Wazuh separados por comas\")\n    parser.add_argument(\"--email\", action=\"append\", required=True, help=\"Destinatario; se puede repetir\")\n    parser.add_argument(\"--lang\", choices=(\"es\", \"en\"), default=\"es\")\n    parser.add_argument(\"--dry-run\", action=\"store_true\")\n    args = parser.parse_args()\n\n    if os.geteuid() != 0:\n        raise SystemExit(\"Este reporte debe ejecutarse como root.\")\n\n    mode = args.date and f\"date:{args.date}\" or next(\n        name\n        for name in (\"today\", \"yesterday\", \"thisweek\", \"lastweek\", \"thismonth\", \"lastmonth\", \"thisyear\", \"lastyear\")\n        if getattr(args, name)\n    )\n\n    module = load_report_module()\n    now = datetime.now().astimezone()\n    start, end, label = module.period_bounds(mode, now)\n    agent_info = parse_agent_control()\n\n    groups = (\n        all_groups()\n        if args.group.lower() == \"all\"\n        else [value.strip() for value in args.group.split(\",\") if value.strip()]\n    )\n    group_memberships = {}\n    all_agent_ids = set()\n\n    for group in groups:\n        ids = group_members(group)\n        if not ids:\n            print(f\"Grupo omitido: {group} no tiene servidores asignados.\")\n            continue\n        group_memberships[group] = ids\n        all_agent_ids.update(ids)\n\n    if not group_memberships:\n        raise SystemExit(\"No hay grupos con servidores asignados para generar el reporte.\")\n\n    # Una sola pasada por los logs del período para TODOS los grupos.\n    # Se conservan solamente agregados por agente, no la lista completa\n    # de eventos, evitando consumir varios GB de RAM en períodos grandes.\n    agent_stats = init_agent_stats(all_agent_ids, agent_info)\n    aggregate_events(module, start, end, all_agent_ids, agent_stats)\n\n    cves, vuln_error = fetch_critical_cves(module, all_agent_ids)\n    cloudlinux_agents = fetch_cloudlinux_agents(module, all_agent_ids)\n    for agent_id, stat in agent_stats.items():\n        stat[\"cves\"] = cves.get(agent_id, [])\n        stat[\"vd_unsupported\"] = agent_id in cloudlinux_agents\n\n    rendered_sections = []\n    total_agents = 0\n    total_events = 0\n    total_high = 0\n    total_critical = 0\n    total_attacks = 0\n\n    for group, ids in group_memberships.items():\n        # Un agente puede pertenecer a más de un grupo; en ese caso se\n        # muestra en cada grupo correspondiente, sin volver a leer logs.\n        stats = {agent_id: agent_stats[agent_id] for agent_id in ids}\n\n        total_agents += len(ids)\n        total_events += sum(stat[\"events\"] for stat in stats.values())\n        total_high += sum(stat[\"high\"] for stat in stats.values())\n        total_critical += sum(stat[\"critical\"] for stat in stats.values())\n        total_attacks += sum(stat[\"attacks\"] for stat in stats.values())\n        rendered_sections.append((group, stats))\n\n    # Mostrar siempre los grupos efectivos. Con --group all se usan los\n    # grupos funcionales realmente resueltos, no la etiqueta literal \"all\".\n    client_name = \", \".join(group_memberships.keys())\n    title = f\"OrangeBox — Reporte detallado: {client_name}\"\n    subtitle = \"\"\n    period = f\"{start.strftime('%d/%m/%Y %H:%M')} — {end.strftime('%d/%m/%Y %H:%M')}\"\n    body = generate_html(\n        rendered_sections,\n        title,\n        subtitle,\n        period,\n        total_agents,\n        total_events,\n        total_high,\n        total_critical,\n        total_attacks,\n        vuln_error=vuln_error,\n        mitre_descriptions=getattr(module, \"MITRE_DESCRIPTIONS\", {}),\n    )\n    archive = archive_html(\n        body,\n        f\"group-{args.group}-{mode.replace(':', '-')}-{start:%Y%m%d}-{end:%Y%m%d}\",\n    )\n\n    text_body = generate_plain(\n        rendered_sections,\n        period,\n        total_agents,\n        total_events,\n        total_high,\n        total_critical,\n        total_attacks,\n        vuln_error=vuln_error,\n    )\n\n    subject = (\n        f\"[ORANGEBOX] {period_label(mode)} - Informe de Seguridad Detallado - {args.group}\"\n        if len(groups) == 1\n        else f\"[ORANGEBOX] {period_label(mode)} - Informe de Seguridad Detallado\"\n    )\n\n    print(f\"Grupo: {args.group}\")\n    print(f\"Período: {period}\")\n    print(f\"Servidores: {total_agents}\")\n    print(f\"Eventos: {total_events}\")\n    print(f\"Alta severidad: {total_high}\")\n    print(f\"Críticas: {total_critical}\")\n    print(f\"Ataques: {total_attacks}\")\n    if vuln_error:\n        print(f\"CVE críticos en inventario: NO CONSULTADO — {vuln_error}\")\n    else:\n        print(\n            \"CVE críticos en inventario consultados: \"\n            f\"{sum(len(stat['cves']) for _, stats in rendered_sections for stat in stats.values())}\"\n        )\n    print(f\"Archivo: {archive}\")\n\n    if args.dry_run:\n        print(\"Dry-run: no se envió correo.\")\n        return 0\n\n    sent = 0\n    for recipient in args.email:\n        if not re.fullmatch(r\"[^\\s@]+@[^\\s@]+\", recipient):\n            print(f\"ERROR: correo inválido: {recipient}\", flush=True)\n            continue\n\n        msg = MIMEMultipart(\"alternative\")\n        msg[\"Subject\"] = subject\n        msg[\"From\"] = f\"Wazuh SOC <{DEFAULT_FROM}>\"\n        msg[\"To\"] = recipient\n        msg.attach(MIMEText(text_body, \"plain\", \"utf-8\"))\n        msg.attach(MIMEText(body, \"html\", \"utf-8\"))\n\n        try:\n            result = subprocess.run(\n                [\"/usr/sbin/sendmail\", \"-t\", \"-i\"],\n                input=msg.as_string(),\n                text=True,\n                capture_output=True,\n                timeout=10,\n                check=False,\n            )\n            if result.returncode != 0:\n                detail = (result.stderr or result.stdout or f\"sendmail exit={result.returncode}\").strip()\n                raise RuntimeError(f\"Postfix maildrop: {detail}\")\n            sent += 1\n        except (OSError, RuntimeError, subprocess.SubprocessError) as exc:\n            print(f\"ERROR enviando a {recipient}: {exc}\", flush=True)\n\n    if sent == 0:\n        raise SystemExit(\"No se pudo enviar el reporte a ningún destinatario.\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    raise SystemExit(main())"

ENGINE_FILENAME = "orangebox-report-engine-v3.py"
REPORT_FILENAME = "orangebox-security-report.py"
DETAIL_FILENAME = "orangebox-detailed-security-report.py"

CACHE_DIR = Path("/var/ossec/reports/cache-proto-v3")
ARCHIVE_DIR = Path("/var/ossec/reports/archive")
DEFAULT_FROM = "wazuh@example.com"
SMTP_HOST = "localhost"
SMTP_PORT = 25


def cleanup_cache_artifaCLIENTE_02():
    """Limpia residuos de ejecuciones interrumpidas sin tocar datos válidos."""
    if not CACHE_DIR.exists():
        return
    temp_dir_re = re.compile(r"^\d{4}-\d{2}-\d{2}\.[A-Za-z0-9_-]+$")
    for path in sorted(CACHE_DIR.rglob("*"), key=lambda p: len(p.parts), reverse=True):
        try:
            if path.is_dir() and temp_dir_re.fullmatch(path.name):
                shutil.rmtree(path, ignore_errors=True)
                continue
            if not path.is_file():
                continue
            name = path.name
            if (
                name.endswith((".tmp", ".partial", ".part", ".swp"))
                or name.startswith(("manifest.json.",))
                or re.search(r"\.jsonl\.gz\.[A-Za-z0-9._-]+\.gz$", name)
            ):
                path.unlink()
        except OSError:
            pass


def cleanup_archive_artifaCLIENTE_02():
    """Limpia temporales de HTML dejados por una ejecución interrumpida."""
    if not ARCHIVE_DIR.exists():
        return
    for path in list(ARCHIVE_DIR.glob("*.html.tmp")) + list(ARCHIVE_DIR.glob("*.zip.tmp")):
        try:
            path.unlink()
        except OSError:
            pass


def load_embedded(source, name, filename):
    namespace = {
        "__name__": name,
        "__file__": filename,
        "__package__": None,
    }
    exec(compile(source, filename, "exec"), namespace, namespace)
    return namespace


# Fuente única de infraestructura/base: la misma del reporte normal que ya
# está validado en producción.
cleanup_cache_artifaCLIENTE_02()
cleanup_archive_artifaCLIENTE_02()

ENGINE = load_embedded(
    ENGINE_SOURCE,
    "orangebox_embedded_engine",
    ENGINE_FILENAME,
)

FIREWALL_RULE = ENGINE["FIREWALL_RULE"]
REPORT = load_embedded(
    REPORT_SOURCE,
    "orangebox_embedded_normal_report",
    "/var/ossec/reports/orangebox-security-report.py",
)

# Compatibilidad interna: algunos componentes del reporte detallado usan
# el nombre corto "standardize", mientras el renderer normal expone
# "standardize_rule_description".
REPORT["standardize"] = REPORT["standardize_rule_description"]

# Interfaz de módulo real para las funciones del detallado que esperan
# atributos (module.indexer_settings, module.geoip_country_map, etc.).
REPORT_MODULE = types.ModuleType("orangebox_embedded_normal_report")
REPORT_MODULE.__dict__.update(REPORT)

# Compatibilidad con el renderer detallado: este espera un helper llamado
# "standardize", mientras el reporte normal expone "standardize_rule_description".
REPORT_MODULE.standardize = REPORT["standardize_rule_description"]

# Fuente única del formato y modelo de datos: snapshot del renderer detallado
# productivo. Se ejecuta aislado para no pisar helpers del normal.
DETAIL = load_embedded(
    DETAIL_SOURCE,
    "orangebox_embedded_detailed_report",
    "/var/ossec/reports/orangebox-detailed-security-report.py",
)



# ---------------------------------------------------------------------------
# Resumen ejecutivo sobre el mismo stream usado por el reporte detallado.
# No se acumula la lista completa de eventos en memoria.
# ---------------------------------------------------------------------------

def build_summary(events, allowed):
    security_count = 0
    critical_count = 0
    source_ips = set()
    agents = Counter()
    agent_stats = defaultdict(
        lambda: {"events": 0, "high": 0, "ips": set(), "attacks": 0}
    )
    categories = {
        name: {
            "count": 0,
            "ips": set(),
            "agents": set(),
            "rules": Counter(),
            "rule_agents": defaultdict(set),
        }
        for name in (
            "authentication",
            "web",
            "fim",
            "malware",
            "privilege",
            "attack",
        )
    }
    mitre_counts = Counter()
    mitre_names = {}
    firewall_attempts = Counter()
    firewall_ips = set()
    firewall_rows = defaultdict(set)
    firewall_recurrence = Counter()
    firewall_rules_by_ip = defaultdict(set)
    firewall_timeouts = REPORT["load_firewall_timeouts"]()

    for event in events:
        aid = str(event.get("agent_id", "000"))
        if aid not in allowed:
            continue

        if event.get("outer_rule") == FIREWALL_RULE:
            if event.get("command") != "add" or not event.get("srcip"):
                continue
            agent_id = aid
            agent_name = event.get("agent_name", "unknown")
            rule_id = str(event.get("rule_id", "unknown"))
            description = REPORT["standardize"](
                rule_id,
                event.get("description", "Firewall Drop"),
                event.get("groups", []),
            )
            src = str(event["srcip"])
            firewall_rows[(agent_id, agent_name, rule_id, description)].add(src)
            firewall_ips.add(src)
            firewall_recurrence[src] += 1
            firewall_rules_by_ip[src].add((rule_id, description))
            continue

        srcip = event.get("srcip")
        if srcip:
            firewall_attempts[(aid, str(event.get("rule_id", "")), srcip)] += 1

        category = event.get("category") or REPORT["classify"](
            event.get("rule_id", ""),
            event.get("groups", []),
            event.get("level", 0),
        )

        if category == "other":
            continue

        security_count += 1
        level = int(event.get("level", 0) or 0)
        if level >= 13:
            critical_count += 1

        agent_name = event.get("agent_name", "unknown")
        event_agent = (aid, agent_name)
        agents[event_agent] += 1

        info = agent_stats[event_agent]
        info["events"] += 1
        if level >= 13:
            info["high"] += 1
        if srcip:
            source_ips.add(srcip)
            info["ips"].add(srcip)
        if category == "attack":
            info["attacks"] += 1

        cat = categories[category]
        cat["count"] += 1
        if srcip:
            cat["ips"].add(srcip)
        cat["agents"].add(aid)
        rule_key = (
            str(event.get("rule_id", "")),
            event.get("description", "Sin descripción"),
        )
        cat["rules"][rule_key] += 1
        cat["rule_agents"][rule_key].add(agent_name)

        techniques = event.get("techniques") or []
        mitre = event.get("mitre") or []
        if isinstance(mitre, str):
            mitre = [mitre]
        if isinstance(techniques, str):
            techniques = [techniques]
        for index, mitre_id in enumerate(mitre):
            if mitre_id:
                mitre_counts[str(mitre_id)] += 1
                if index < len(techniques) and techniques[index]:
                    mitre_names[str(mitre_id)] = techniques[index]

    firewall_rows_out = []
    for (agent_id, agent_name, rule_id, description), ips in firewall_rows.items():
        attempts = sum(
            firewall_attempts[(agent_id, rule_id, src)]
            for src in ips
        )
        if attempts == 0:
            attempts = len(ips)
        firewall_rows_out.append(
            {
                "agent_id": agent_id,
                "agent_name": agent_name,
                "rule_id": rule_id,
                "description": description,
                "ips": sorted(
                    ips,
                    key=lambda value: (
                        ipaddress.ip_address(value).version,
                        int(ipaddress.ip_address(value)),
                    ),
                ),
                "attempts": attempts,
            }
        )
    firewall_rows_out.sort(key=lambda row: row["agent_name"].lower())

    return {
        "security_count": security_count,
        "critical_count": critical_count,
        "source_ips": source_ips,
        "agents": agents,
        "agent_stats": agent_stats,
        "categories": categories,
        "mitre_counts": mitre_counts,
        "mitre_names": mitre_names,
        "firewall_ips": firewall_ips,
        "firewall_rows": firewall_rows_out,
        "firewall_recurrence": firewall_recurrence,
        "firewall_rules_by_ip": firewall_rules_by_ip,
        "firewall_timeouts": firewall_timeouts,
        "timeline": Counter(),
    }


def archive_detailed_zip(body, label):
    ARCHIVE_DIR.mkdir(parents=True, exist_ok=True)
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", label)
    zip_path = ARCHIVE_DIR / f"detailed-security-report-{safe}.zip"
    tmp = zip_path.with_suffix(".zip.tmp")

    # El ZIP debe contener exactamente un archivo HTML en su raíz.
    html_name = Path(f"detailed-security-report-{safe}.html").name
    if not html_name or html_name in {".", ".."}:
        raise RuntimeError("Nombre interno del ZIP inválido.")

    with zipfile.ZipFile(
        tmp,
        mode="w",
        compression=zipfile.ZIP_DEFLATED,
        compresslevel=9,
    ) as archive:
        archive.writestr(html_name, body.encode("utf-8"))

        # Blindaje: nunca aceptar directorios ni rutas internas.
        names = archive.namelist()
        if names != [html_name] or any(
            name.endswith("/") or Path(name).name != name
            for name in names
        ):
            raise RuntimeError(
                f"ZIP detallado inválido: entradas inesperadas: {names!r}"
            )

    tmp.replace(zip_path)
    return zip_path


def send_unified_email(subject, summary_body, detailed_zip, recipient):
    msg = MIMEMultipart("mixed")
    msg["Subject"] = subject
    msg["From"] = f"Wazuh SOC <{DEFAULT_FROM}>"
    msg["To"] = recipient

    alternative = MIMEMultipart("alternative")
    alternative.attach(
        MIMEText(
            "OrangeBox Wazuh Security Activity Report. "
            "El reporte detallado completo se adjunta en formato ZIP.",
            "plain",
            "utf-8",
        )
    )
    alternative.attach(MIMEText(summary_body, "html", "utf-8"))
    msg.attach(alternative)

    with detailed_zip.open("rb") as handle:
        attachment = MIMEApplication(handle.read(), _subtype="zip")
    attachment.add_header(
        "Content-Disposition",
        "attachment",
        filename=detailed_zip.name,
    )
    msg.attach(attachment)

    result = subprocess.run(
        ["/usr/sbin/sendmail", "-t", "-i"],
        input=msg.as_string(),
        text=True,
        capture_output=True,
        timeout=30,
        check=False,
    )
    if result.returncode != 0:
        detail = (
            result.stderr
            or result.stdout
            or f"sendmail exit={result.returncode}"
        ).strip()
        raise RuntimeError(f"Postfix maildrop: {detail}")


def main():
    p = argparse.ArgumentParser(
        description="OrangeBox Security Report v4 - resumen + detallado ZIP"
    )
    modes = p.add_mutually_exclusive_group(required=True)
    for name in (
        "today",
        "yesterday",
        "thisweek",
        "lastweek",
        "thismonth",
        "lastmonth",
        "thisyear",
        "lastyear",
    ):
        modes.add_argument("--" + name, action="store_true")
    modes.add_argument("--date")
    p.add_argument("--group", required=True)
    p.add_argument("--email", action="append")
    p.add_argument("--dry-run", action="store_true")
    p.add_argument("--cache-dir", type=Path, default=CACHE_DIR)
    args = p.parse_args()

    t0 = time.monotonic()
    now = datetime.now().astimezone()

    mode = (
        args.date
        and f"date:{args.date}"
        or next(
            name
            for name in (
                "today",
                "yesterday",
                "thisweek",
                "lastweek",
                "thismonth",
                "lastmonth",
                "thisyear",
                "lastyear",
            )
            if getattr(args, name)
        )
    )

    start, end, label = REPORT["period_bounds"](mode, now)

    groups = (
        REPORT["all_groups"]()
        if args.group.lower() == "all"
        else [value.strip() for value in args.group.split(",") if value.strip()]
    )
    if not groups:
        raise SystemExit("No hay grupos Wazuh seleccionados.")

    memberships = {}
    allowed = set()
    for group_name in groups:
        ids = REPORT["group_members"](group_name)
        if ids:
            memberships[group_name] = ids
            allowed.update(ids)
        else:
            print(f"Grupo omitido: {group_name} no tiene servidores asignados.")

    if not memberships:
        raise SystemExit("No hay grupos con servidores asignados para generar el reporte.")

    report_groups = ", ".join(memberships.keys())

    # Una sola actualización del cache para ambas vistas.
    t_cache = time.monotonic()
    ENGINE["ensure_cache"](args.cache_dir, start, end)
    cache_time = time.monotonic() - t_cache

    agent_info = DETAIL["parse_agent_control"]()
    agent_stats = DETAIL["init_agent_stats"](allowed, agent_info)

    # Un solo stream del cache:
    # - acumula el detallado;
    # - alimenta el resumen ejecutivo;
    # No se construye una lista de cientos de miles de eventos.
    def event_stream():
        full_closed_day = (
            start.time() == datetime.min.time()
            and end == start + timedelta(days=1)
            and end <= now
        )
        for event in ENGINE["iter_cache"](
            args.cache_dir,
            start.date(),
            (end - timedelta(microseconds=1)).date(),
            allowed,
        ):
            if not full_closed_day:
                timestamp = REPORT["parse_timestamp"](event.get("timestamp"))
                if not timestamp or timestamp < start or timestamp >= end:
                    continue

            if event.get("agent_id") not in allowed:
                continue

            if event.get("outer_rule") == ENGINE["FIREWALL_RULE"]:
                if event.get("command") != "add":
                    continue

            DETAIL["accumulate_event"](agent_stats, event, REPORT_MODULE)
            yield event

    t_read = time.monotonic()
    summary = build_summary(event_stream(), allowed)
    read_time = time.monotonic() - t_read

    # Una sola consulta de vulnerabilidades; reutilizar su resultado en ambas vistas.
    t_agg = time.monotonic()
    cves, vuln_error = DETAIL["fetch_critical_cves"](REPORT_MODULE, allowed)
    cloudlinux_agents = DETAIL["fetch_cloudlinux_agents"](REPORT_MODULE, allowed)

    for agent_id, stat in agent_stats.items():
        stat["cves"] = cves.get(agent_id, [])
        stat["vd_unsupported"] = agent_id in cloudlinux_agents

    cve_agents = {}
    cve_unsupported = {}
    for agent_id, rows in cves.items():
        if rows:
            name = agent_stats.get(agent_id, {}).get("name", f"Servidor {agent_id}")
            cve_agents[str(agent_id)] = {
                "name": name,
                "count": len(rows),
            }
    for agent_id in cloudlinux_agents:
        name = agent_stats.get(agent_id, {}).get("name", f"Servidor {agent_id}")
        cve_unsupported[str(agent_id)] = {"name": name}

    summary["cve_summary"] = {
        "total": sum(len(rows) for rows in cves.values()),
        "agents": cve_agents,
        "unsupported_agents": cve_unsupported,
    }
    if vuln_error:
        summary["cve_summary"]["error"] = vuln_error

    rendered = []
    total_agents = 0
    total_events = 0
    total_high = 0
    total_critical = 0
    total_attacks = 0

    for group, ids in memberships.items():
        stats = {
            agent_id: agent_stats[agent_id]
            for agent_id in ids
            if agent_id in agent_stats
        }
        total_agents += len(ids)
        total_events += sum(s["events"] for s in stats.values())
        total_high += sum(s["high"] for s in stats.values())
        total_critical += sum(s["critical"] for s in stats.values())
        total_attacks += sum(s["attacks"] for s in stats.values())
        rendered.append((group, stats))

    agg_time = time.monotonic() - t_agg

    period = (
        f"{start.strftime('%d/%m/%Y %H:%M')} — "
        f"{end.strftime('%d/%m/%Y %H:%M') if end < now else 'ahora'}"
    )

    # Vista ejecutiva para el cuerpo del correo.
    t_render = time.monotonic()
    summary_body = REPORT["generate_html"](
        summary,
        REPORT["labels"]("es")["report"],
        REPORT["labels"]("es")["subtitle"],
        period,
        report_groups,
        "es",
    )
    summary_render_time = time.monotonic() - t_render

    # Vista detallada para el archivo ZIP adjunto.
    t_detail = time.monotonic()
    detailed_body = DETAIL["generate_html"](
        rendered,
        f"OrangeBox — Reporte detallado: {report_groups}",
        "",
        period,
        total_agents,
        total_events,
        total_high,
        total_critical,
        total_attacks,
        vuln_error=vuln_error,
        mitre_descriptions=REPORT.get("MITRE_DESCRIPTIONS", {}),
        report_module=REPORT_MODULE,
    )
    detail_render_time = time.monotonic() - t_detail

    if not summary_body:
        raise SystemExit("El renderer ejecutivo no produjo HTML.")
    if not detailed_body:
        raise SystemExit("El renderer detallado no produjo HTML.")

    # Archivar el resumen HTML y el detallado como ZIP. No se conserva el HTML
    # detallado suelto para ahorrar espacio.
    t_archive = time.monotonic()
    ARCHIVE_DIR.mkdir(parents=True, exist_ok=True)
    safe_groups = re.sub(r"[^A-Za-z0-9_.-]+", "_", report_groups)

    summary_archive = ARCHIVE_DIR / (
        f"security-report-{safe_groups}-{mode.replace(':','-')}-"
        f"{start:%Y%m%d}-{end:%Y%m%d}.html"
    )
    tmp_summary = summary_archive.with_suffix(".html.tmp")
    tmp_summary.write_text(summary_body, encoding="utf-8")
    tmp_summary.replace(summary_archive)

    detailed_zip = archive_detailed_zip(
        detailed_body,
        f"{safe_groups}-{mode.replace(':','-')}-{start:%Y%m%d}-{end:%Y%m%d}",
    )
    archive_time = time.monotonic() - t_archive

    subject_period = {
        "today": "Diario",
        "yesterday": "Diario",
        "thisweek": "Semanal",
        "lastweek": "Semanal",
        "thismonth": "Mensual",
        "lastmonth": "Mensual",
        "thisyear": "Anual",
        "lastyear": "Anual",
    }.get(mode, "Seguridad")
    subject = f"[ORANGEBOX] {subject_period} - Informe de Seguridad {report_groups}"

    print(f"Grupo: {report_groups}")
    print(f"Período: {period}")
    print(f"Servidores: {total_agents}")
    print(f"Eventos: {total_events}")
    print(f"Alta severidad: {total_high}")
    print(f"Críticas: {total_critical}")
    print(f"Ataques: {total_attacks}")
    print(f"Cache/update: {cache_time:.3f}s")
    print(f"Lectura cache (una pasada): {read_time:.3f}s")
    print(f"Agregación/CVE: {agg_time:.3f}s")
    print(f"Render resumen: {summary_render_time:.3f}s")
    print(f"Render detallado: {detail_render_time:.3f}s")
    print(f"Archivo: {archive_time:.3f}s")
    print(f"Archivo resumen: {summary_archive}")
    print(f"Archivo detallado ZIP: {detailed_zip}")
    print(f"Tiempo total: {time.monotonic() - t0:.3f}s")

    recipients = []
    for value in args.email or []:
        recipients.extend(v.strip() for v in value.split(",") if v.strip())

    if args.dry_run or not recipients:
        print("Dry-run / sin correo.")
        return 0

    t_email = time.monotonic()
    sent = 0
    for recipient in recipients:
        if not re.fullmatch(r"[^\s@]+@[^\s@]+", recipient):
            print(f"ERROR: correo inválido: {recipient}", flush=True)
            continue
        try:
            send_unified_email(
                subject,
                summary_body,
                detailed_zip,
                recipient,
            )
            sent += 1
            print(f"Correo enviado a {recipient}")
        except (OSError, RuntimeError, subprocess.SubprocessError) as exc:
            print(f"ERROR enviando a {recipient}: {exc}", flush=True)

    print(f"SMTP/correo: {time.monotonic() - t_email:.3f}s")
    if sent == 0:
        raise SystemExit("No se pudo enviar el reporte a ningún destinatario.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
